                            if bDebugMessages == true then LOG(sFunctionRef..': Is the human player '..oBrain.Nickname..' an enemy='..tostring(IsEnemy(oBrain:GetArmyIndex(), aiBrain:GetArmyIndex()))) end
                            if IsEnemy(oBrain:GetArmyIndex(), aiBrain:GetArmyIndex()) then
                                if bDebugMessages == true then LOG(sFunctionRef..': Cur units owned by aiBrain='..aiBrain:GetCurrentUnits(categories.ALLUNITS - categories.UNSELECTABLE - categories.INSIGNIFICANTUNIT)..'; Cur engineers and factories='..aiBrain:GetCurrentUnits(categories.COMMAND + categories.SUBCOMMANDER + AiBotUnitInfo.refCategoryEngineer + AiBotUnitInfo.refCategoryFactory)) end
