function GetFactoryLifetimeCount(oFactory, iCategory, bAllUnitsInsteadOfCategory)
    if bAllUnitsInsteadOfCategory then
        return (oFactory[AiBotFactory.refiTotalBuildCount] or 0)
    else
        local iTotalCount = 0
        if oFactory[AiBotFactory.refiBuildCountByBlueprint] then
            for sBPID, iCurCount in oFactory[AiBotFactory.refiBuildCountByBlueprint] do
                if EntityCategoryContains(iCategory, sBPID) then
                    iTotalCount = iTotalCount + iCurCount
                end
            end
        end
        return iTotalCount
    end
end

function IsEngineerAvailable(oEngineer, bDebugOnly)
    --If bDebugOnly is true then wont adjust counts/tracking (i.e. set to true if are calling for logging purposes, so we dont desync the replay)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'IsEngineerAvailable'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if bDebugMessages == true then
        local iCurPlateau, iCurLZ = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(oEngineer:GetPosition(), true, oEngineer)
        LOG(sFunctionRef..': GameTIme '..GetGameTimeSeconds()..': Engineer '..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)..' owned by '..oEngineer:GetAIBrain().Nickname..': oEngineer:GetFractionComplete()='..oEngineer:GetFractionComplete()..'; Unit state='..AiBotUnitInfo.GetUnitState(oEngineer)..'; Are last orders empty='..tostring(oEngineer[AiBotOrders.reftiLastOrders] == nil)..'; Engineer Plateau='..(iCurPlateau or 'nil')..'; LZ='..(iCurLZ or 'nil')..'; Is unit state moving='..tostring(oEngineer:IsUnitState('Moving'))..'; Engineer position='..repru(oEngineer:GetPosition())..'; Engineer assigned action='..(oEngineer[AiBotEngineer.refiAssignedAction] or 'nil')..'; reftArtiTemplateRefs=P'..(oEngineer[AiBotBuilding.reftArtiTemplateRefs][1] or 'nil')..'Z'..(oEngineer[AiBotBuilding.reftArtiTemplateRefs][2] or 'nil')..'T'..(oEngineer[AiBotBuilding.reftArtiTemplateRefs][3] or 'nil')..'; Special micro active='..tostring(oEngineer[AiBotUnitInfo.refbSpecialMicroActive] or false)..'; oEngineer[refiEngineerStuckCheckCount]='..(oEngineer[refiEngineerStuckCheckCount] or 'nil')..'; refiSequentialReclaimCount='..(oEngineer[AiBotEngineer.refiSequentialReclaimCount] or 'nil'))
    end
    if oEngineer:GetFractionComplete() == 1 and not(oEngineer:IsUnitState('Attached')) and not(oEngineer[AiBotEngineer.refiAssignedAction] == AiBotEngineer.refActionSpecialShieldDefence) and not(oEngineer[AiBotEngineer.refiAssignedAction] == AiBotEngineer.refActionManageGameEnderTemplate) and not(oEngineer:IsUnitState('Capturing')) then
        --Spare engineers - always treat as available even if in the middle of something
        if oEngineer[AiBotEngineer.refbHasSpareAction] then
            if bDebugMessages == true then LOG(sFunctionRef..': Engineer given spare action so marking as available') end
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            return true
        elseif not(oEngineer:IsUnitState('Building')) and not(oEngineer:IsUnitState('Repairing')) then
            if oEngineer:IsUnitState('Reclaiming') then
                --Cover rare scenario where engineer shows as reclaiming but has nothing to reclaim
                if oEngineer[AiBotEngineer.refiAssignedAction] == AiBotEngineer.refActionReclaimArea then
                    local tUnitsReclaiming = oEngineer[AiBotEngineer.reftUnitsWeAreReclaiming]
                    local bNotReclaiming = true
                    if AiBotUtilities.IsTableEmpty(tUnitsReclaiming) == false then
                        for iReclaiming, oReclaiming in tUnitsReclaiming do
                            if not(oReclaiming.Dead) and (not(oReclaiming.BeenDestroyed) or not(oReclaiming:BeenDestroyed())) then
                                bNotReclaiming = false
                                break
                            end
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': Engineer is reclaiming, bNotReclaiming='..tostring(bNotReclaiming)..'; Stuck check='..(oEngineer[refiEngineerStuckCheckCount] or 'nil')) end
                    if bNotReclaiming then
                        oEngineer[refiEngineerStuckCheckCount] = (oEngineer[refiEngineerStuckCheckCount] or 0) + 1
                        if oEngineer[refiEngineerStuckCheckCount] >= 3 then
                            if bDebugMessages == true then LOG(sFunctionRef..': Engi might be stuck trying to reclaim so making available') end
                            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                            return true
                        end
                    end
                    --if got here then havent flagged that have nothing to reclaim
                    if oEngineer[refiEngineerStuckCheckCount] then oEngineer[refiEngineerStuckCheckCount] = 0 end
                elseif oEngineer[AiBotEngineer.refiAssignedAction] == AiBotEngineer.refActionAttackMoveToLandZone and (oEngineer[AiBotEngineer.refiSequentialReclaimCount] or 0) >= 30 then
                    if oEngineer[AiBotEngineer.refiSequentialReclaimCount] >= 100 then
                        if bDebugMessages == true then LOG(sFunctionRef..': Engi has been reclaiming a long time, will make available') end
                        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                        return true
                    else
                        local iCurPlateau, iCurLZ = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(oEngineer:GetPosition(), true, oEngineer)
                        if bDebugMessages == true then LOG(sFunctionRef..': Engineer on attack move has action to move to LZ, reftiPlateauAndLZToMoveTo='..reprs(oEngineer[AiBotLand.reftiPlateauAndLZToMoveTo])..'; Eng position iCurPlateau='..(iCurPlateau or 'nil')..'; iCurLZ='..(iCurLZ or 'nil')) end
                        if iCurPlateau == oEngineer[AiBotLand.reftiPlateauAndLZToMoveTo][1] and iCurLZ == oEngineer[AiBotLand.reftiPlateauAndLZToMoveTo][2] then
                            if bDebugMessages == true then LOG(sFunctionRef..': Engi is in its target zone and has reclaimed a reasonable amount so will make available again to check for new orders') end
                            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                            return true
                        end
                    end
                end
                if bDebugMessages == true then LOG(sFunctionRef..': Engineer is reclaiming so will treat as unavailable') end

                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                return false
            else
                AiBotOrders.UpdateRecordedOrders(oEngineer)
                if not(oEngineer[AiBotOrders.reftiLastOrders]) then
                    if bDebugMessages == true then LOG(sFunctionRef..': Engineer has no last orders active so is available') end
                    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                    return true
                else
                    --If engineer is moving but it doesnt have an assignment, or its assignment isnt to move, then make it available, unless it has special micro active
                    if oEngineer[AiBotUnitInfo.refbSpecialMicroActive] then
                        if bDebugMessages == true then LOG(sFunctionRef..': Special micro is active') end
                        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                        return false
                    else
                        local iLastOrderType = oEngineer[AiBotOrders.reftiLastOrders][oEngineer[AiBotOrders.refiOrderCount]][AiBotOrders.subrefiOrderType]
                        if bDebugMessages == true then LOG(sFunctionRef..': Engineer '..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)..' owned by '..oEngineer:GetAIBrain().Nickname..' has a last order type of '..(iLastOrderType or 'nil')..'; and an action assigned of '..(oEngineer[AiBotEngineer.refiAssignedAction] or 'nil')..'; Order for this action='..(AiBotEngineer.tiActionOrder[oEngineer[AiBotEngineer.refiAssignedAction]] or 'nil')..'; oEngineer[refiEngineerStuckCheckCount]='..(oEngineer[refiEngineerStuckCheckCount] or 'nil')..'; refiRepairProgressWhenLastChecked='..(oEngineer[AiBotEngineer.refiRepairProgressWhenLastChecked] or 'nil')) end
                        --Rare case where engineer acn be given a move order yet doesn't move - below is to try and mitigate it
                        if oEngineer:IsUnitState('Moving') and oEngineer[AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefiOrderType] == AiBotOrders.refiOrderIssueMove and not(bDebugOnly) then
                            if (oEngineer[refiEngineerStuckCheckCount] or 0) == 0 then
                                oEngineer[refiEngineerStuckCheckCount] = 1
                                oEngineer[reftEngineerStuckCheckLastPosition] = {oEngineer:GetPosition()[1], oEngineer:GetPosition()[2], oEngineer:GetPosition()[3]}
                            else
                                oEngineer[refiEngineerStuckCheckCount] = oEngineer[refiEngineerStuckCheckCount] + 1
                                if oEngineer[refiEngineerStuckCheckCount] >= 10 then
                                    oEngineer[refiEngineerStuckCheckCount] = 0
                                    if AiBotUtilities.GetDistanceBetweenPositions(oEngineer:GetPosition(),oEngineer[reftEngineerStuckCheckLastPosition]) <= 0.01 then
                                        --Engineer is stuck, clear its orders and treat as available
                                        if bDebugMessages == true then LOG(sFunctionRef..': Engineer appears stuck, oEngineer[refiEngineerStuckCheckCount]='..oEngineer[refiEngineerStuckCheckCount]) end
                                        AiBotOrders.IssueTrackedClearCommands(oEngineer)
                                        oEngineer[reftEngineerStuckCheckLastPosition] = nil
                                        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                                        return true
                                    end
                                end
                            end
                        end

                        if iLastOrderType == AiBotOrders.refiOrderIssueMove then
                            if oEngineer[AiBotEngineer.refiAssignedAction] and (AiBotEngineer.tiActionOrder[oEngineer[AiBotEngineer.refiAssignedAction]] == iLastOrderType or oEngineer[AiBotEngineer.refiAssignedAction] == AiBotEngineer.refActionLoadOntoTransport) then
                                --Engineer not available, unless its order was to move to a land or water zone, in which case check if it is now in that land or water zone (or if it has reclaimed 30+ things on route)
                                if oEngineer[AiBotEngineer.refiAssignedAction] == AiBotEngineer.refActionMoveToLandZone or (oEngineer[AiBotEngineer.refiAssignedAction] == AiBotEngineer.refActionAttackMoveToLandZone and (oEngineer[AiBotEngineer.refiSequentialReclaimCount] or 0) <= 30) then
                                    local iCurPlateau, iCurLZ = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(oEngineer:GetPosition(), true, oEngineer)
                                    if bDebugMessages == true then LOG(sFunctionRef..': Engineer has action to move to LZ, reftiPlateauAndLZToMoveTo='..reprs(oEngineer[AiBotLand.reftiPlateauAndLZToMoveTo])..'; Eng position iCurPlateau='..(iCurPlateau or 'nil')..'; iCurLZ='..(iCurLZ or 'nil')) end
                                    if iCurPlateau == oEngineer[AiBotLand.reftiPlateauAndLZToMoveTo][1] and iCurLZ == oEngineer[AiBotLand.reftiPlateauAndLZToMoveTo][2] then
                                        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                                        return true
                                    else
                                        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                                        return false
                                    end
                                elseif oEngineer[AiBotEngineer.refiAssignedAction] == AiBotEngineer.refActionMoveToWaterZone then
                                    local iCurWaterZone = AiBotMap.GetWaterZoneFromPosition(oEngineer:GetPosition(), true, oEngineer)
                                    if bDebugMessages == true then LOG(sFunctionRef..': Engineer has action to move to WZ, refiWZToMoveTo='..(oEngineer[AiBotNavy.refiWZToMoveTo] or 'nil')..'; Eng position iCurWaterZone='..(iCurWaterZone or 'nil')) end
                                    if iCurWaterZone and iCurWaterZone == oEngineer[AiBotNavy.refiWZToMoveTo] then
                                        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                                        return true
                                    else
                                        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                                        return false
                                    end
                                elseif oEngineer[AiBotEngineer.refiAssignedAction] == AiBotEngineer.refActionRunToLandZone then --Make available if no enemies in cur LZ and adjacent LZ, or alternatively none in cur LZ, and have friendly cmobat in cur LZ and dont need more
                                    local iCurPlateau, iCurLZ = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(oEngineer:GetPosition(), true, oEngineer)
                                    if bDebugMessages == true then LOG(sFunctionRef..': Engineer has action to run to LZ, reftiPlateauAndLZToMoveTo='..reprs(oEngineer[AiBotLand.reftiPlateauAndLZToMoveTo])..'; Eng position iCurPlateau='..(iCurPlateau or 'nil')..'; iCurLZ='..(iCurLZ or 'nil')) end
                                    if iCurPlateau == oEngineer[AiBotLand.reftiPlateauAndLZToMoveTo][1] and iCurLZ == oEngineer[AiBotLand.reftiPlateauAndLZToMoveTo][2] then
                                        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                                        return true
                                    else
                                        local tLZTeamData = AiBotMap.tAllPlateaus[iCurPlateau][AiBotMap.subrefPlateauLandZones][iCurLZ][AiBotMap.subrefLZTeamData][oEngineer:GetAIBrain().AiBotTeam]
                                        if bDebugMessages == true then LOG(sFunctionRef..': Engineer isnt at LZ to run to yet, are there enemies in this or adjacent LZ='..tostring(tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ])..'; tLZTeamData[AiBotMap.subrefbDangerousEnemiesInAdjacentWZ]='..tostring(tLZTeamData[AiBotMap.subrefbDangerousEnemiesInAdjacentWZ])) end
                                        if not(tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ] or tLZTeamData[AiBotMap.subrefbDangerousEnemiesInAdjacentWZ]) then
                                            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                                            return true
                                        else
                                            if tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] >= 10 then
                                                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                                                return false
                                            else
                                                local iTotalEnemyThreatNearby = tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal]
                                                if AiBotUtilities.IsTableEmpty(AiBotMap.tAllPlateaus[iCurPlateau][AiBotMap.subrefPlateauLandZones][iCurLZ][AiBotMap.subrefLZAdjacentLandZones]) == false then
                                                    for _, iAdjLZ in AiBotMap.tAllPlateaus[iCurPlateau][AiBotMap.subrefPlateauLandZones][iCurLZ][AiBotMap.subrefLZAdjacentLandZones] do
                                                        iTotalEnemyThreatNearby = iTotalEnemyThreatNearby + AiBotMap.tAllPlateaus[iCurPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][oEngineer:GetAIBrain().AiBotTeam][AiBotMap.subrefTThreatEnemyCombatTotal]
                                                    end
                                                end
                                                if bDebugMessages == true then LOG(sFunctionRef..': iTotalEnemyThreatNearby='..iTotalEnemyThreatNearby..'; tLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFTotal]='..tLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFTotal]) end
                                                if iTotalEnemyThreatNearby * 5 < tLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFTotal] then
                                                    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                                                    return true
                                                end
                                            end
                                            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                                            return false
                                        end
                                    end
                                elseif oEngineer[AiBotEngineer.refiAssignedAction] == AiBotEngineer.refActionRunToWaterZone then --Make available if no enemies in cur WZ and adjacent LZ, or alternatively none in cur WZ, and have friendly cmobat in cur WZ and dont need more
                                    local iCurWaterZone = AiBotMap.GetWaterZoneFromPosition(oEngineer:GetPosition(), true, oEngineer)
                                    if bDebugMessages == true then LOG(sFunctionRef..': Engineer has action to run to WZ, refiWZToMoveTo='..(oEngineer[AiBotNavy.refiWZToMoveTo] or 'nil')..'; Eng position iCurWaterZone='..(iCurWaterZone or 'nil')) end
                                    if iCurWaterZone and iCurWaterZone == oEngineer[AiBotNavy.refiWZToMoveTo] then
                                        if bDebugMessages == true then LOG(sFunctionRef..': Engi has reached the WZ it wants to run to') end
                                        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                                        return true
                                    else
                                        local iPond = AiBotMap.tiPondByWaterZone[iCurWaterZone]
                                        local iTeam = oEngineer:GetAIBrain().AiBotTeam
                                        local tWZData = AiBotMap.tPondDetails[iPond][AiBotMap.subrefPondWaterZones][iCurWaterZone]
                                        local tWZTeamData = tWZData[AiBotMap.subrefWZTeamData][iTeam]
                                        if bDebugMessages == true then LOG(sFunctionRef..': Engineer isnt at WZ to run to yet, are there enemies in this or adjacent WZ='..tostring(tWZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentWZ])) end
                                        if not(tWZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentWZ]) then
                                            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                                            return true
                                        else
                                            if tWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] >= 10 then
                                                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                                                return false
                                            else
                                                local iTotalEnemyThreatNearby = tWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal]
                                                if AiBotUtilities.IsTableEmpty(tWZData[AiBotMap.subrefWZAdjacentWaterZones]) == false then
                                                    for iEntry, tSubtable in tWZData[AiBotMap.subrefWZAdjacentWaterZones] do
                                                        local iAdjWZ = tSubtable[AiBotMap.subrefAWZRef]
                                                        iTotalEnemyThreatNearby = iTotalEnemyThreatNearby + (AiBotMap.tPondDetails[iPond][AiBotMap.subrefPondWaterZones][iAdjWZ][AiBotMap.subrefWZTeamData][iTeam][AiBotMap.subrefTThreatEnemyCombatTotal] or 0)
                                                    end
                                                end
                                                if bDebugMessages == true then LOG(sFunctionRef..': iTotalEnemyThreatNearby='..iTotalEnemyThreatNearby..'; tWZTeamData[AiBotMap.subrefWZTThreatAllyCombatTotal]='..tWZTeamData[AiBotMap.subrefWZTThreatAllyCombatTotal]) end
                                                if iTotalEnemyThreatNearby * 5 < tWZTeamData[AiBotMap.subrefWZTThreatAllyCombatTotal] then
                                                    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                                                    return true
                                                end
                                            end
                                            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                                            return false
                                        end
                                    end
                                else
                                    if bDebugMessages == true then LOG(sFunctionRef..': Engineer doesnt appear to be available') end
                                    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                                    return false
                                end
                            else
                                if bDebugMessages == true then LOG(sFunctionRef..': Engineer either doesnt have an assigned action or its current orders are inconsistent with that action, so returning true') end
                                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                                return true
                            end
                        elseif (iLastOrderType == AiBotOrders.refiOrderIssueGuard or iLastOrderType == AiBotOrders.refiOrderIssueCapture) then
                            if not(AiBotUnitInfo.IsUnitValid(oEngineer[AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefoOrderUnitTarget])) then
                                if bDebugMessages == true then LOG(sFunctionRef..': Guard or capture order where target no longer valid so available, oEngineer[AiBotOrders.reftiLastOrders][oEngineer[AiBotOrders.subrefoOrderUnitTarget]]='..(oEngineer[AiBotOrders.reftiLastOrders][oEngineer[AiBotOrders.subrefoOrderUnitTarget]].UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oEngineer[AiBotOrders.reftiLastOrders][oEngineer[AiBotOrders.subrefoOrderUnitTarget]]) or 'nil')) end
                                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                                return true
                                --Redundancy if assisting engineer with no action (shouldnt be needed)
                            elseif EntityCategoryContains(AiBotUnitInfo.refCategoryEngineer, oEngineer[AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefoOrderUnitTarget].UnitId) then
                                if bDebugMessages == true then LOG(sFunctionRef..': We are assisting an engineer, engineer action we are assisting='..(oEngineer[AiBotOrders.reftiLastOrders][oEngineer[AiBotOrders.subrefoOrderUnitTarget]][AiBotEngineer.refiAssignedAction] or 'nil')..'; Unit state='..AiBotUnitInfo.GetUnitState(oEngineer[AiBotOrders.reftiLastOrders][oEngineer[AiBotOrders.subrefoOrderUnitTarget]])) end
                                if not(oEngineer[AiBotOrders.reftiLastOrders][oEngineer[AiBotOrders.subrefoOrderUnitTarget]][AiBotEngineer.refiAssignedAction]) then
                                    if bDebugMessages == true then LOG(sFunctionRef..': We are assisting an engineer with no action so will make us available again') end
                                    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                                    return true
                                end
                            end
                        elseif iLastOrderType == AiBotOrders.refiOrderIssueBuild and oEngineer:IsUnitState('Moving') and not(EntityCategoryContains(AiBotUnitInfo.refCategoryWall + AiBotUnitInfo.refCategoryPD * categories.TECH1 + AiBotUnitInfo.refCategoryStructureAA * categories.TECH1, oEngineer[AiBotOrders.reftiLastOrders][oEngineer[AiBotOrders.refiOrderCount]][AiBotOrders.subrefsOrderBlueprint])) then
                            --Check if there is already a constructed building at the build location
                            local tLastOrderPosition = oEngineer[AiBotOrders.reftiLastOrders][oEngineer[AiBotOrders.refiOrderCount]][AiBotOrders.subreftOrderPosition]
                            local rRect = AiBotUtilities.GetRectAroundLocation(tLastOrderPosition, 0.49)
                            local tUnitsInRect = GetUnitsInRect(rRect)
                            if AiBotUtilities.IsTableEmpty(tUnitsInRect) == false then
                                for iUnit, oUnit in tUnitsInRect do
                                    if oUnit:GetFractionComplete() == 1 and EntityCategoryContains(AiBotUnitInfo.refCategoryStructure, oUnit.UnitId) and AiBotUnitInfo.GetBuildingSize(oUnit.UnitId) > 1 then
                                        if bDebugMessages == true then LOG(sFunctionRef..': Engineer has a constructed building at its target location so making it available') end
                                        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                                        return true
                                    end
                                end
                            end
                        elseif iLastOrderType == AiBotOrders.refiOrderIssueRepair then
                            local oUnitRepairing = oEngineer[AiBotOrders.reftiLastOrders][oEngineer[AiBotOrders.refiOrderCount]][AiBotOrders.subrefoOrderUnitTarget]
                            if not(AiBotUnitInfo.IsUnitValid(oUnitRepairing)) or (oUnitRepairing:GetFractionComplete() == 1 and (oEngineer[AiBotEngineer.refiAssignedAction] == AiBotEngineer.refActionRepairAllyUnit or AiBotUnitInfo.GetUnitHealthPercent(oUnitRepairing) == 1)) then
                                if bDebugMessages == true then LOG(sFunctionRef..': Are repairing a unit that is completed and full health or was an ally unit to repair, so are available') end
                                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                                return true
                            else
                                if bDebugMessages == true then LOG(sFunctionRef..': Are assigned to repair a unit that isnt complete or healed yet so not available, oUnitRepairing='..oUnitRepairing.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnitRepairing)..'; reftArtiTemplateRefs on unitrepairing='..repru(oUnitRepairing[AiBotBuilding.reftArtiTemplateRefs])) end
                                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                                return false
                            end
                        elseif iLastOrderType == AiBotOrders.refiOrderIssueReclaim and oEngineer:IsUnitState('Moving') then
                            --If engi is in close to the target then reclaim it
                            if oEngineer[AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefoOrderUnitTarget].CachePosition and (oEngineer[AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefoOrderUnitTarget].MaxMassReclaim or 0) > 0 and AiBotUtilities.GetDistanceBetweenPositions(oEngineer[AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefoOrderUnitTarget].CachePosition, oEngineer:GetPosition()) <= (oEngineer:GetBlueprint().Economy.MaxBuildDistance or 5) then
                                --Reissue reclaim order (but treat as unavailable)
                                if IsDestroyed(oEngineer[AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefoOrderUnitTarget]) then
                                    --Abort reclaim target
                                    if bDebugMessages == true then LOG(sFunctionRef..': Reclaim target is dead so trat engi as available now') end
                                    oEngineer[AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefoOrderUnitTarget] = nil
                                    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                                    return true
                                else
                                    AiBotOrders.IssueTrackedReclaim(oEngineer, oEngineer[AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefoOrderUnitTarget], false, 'RecInRng', false)
                                end
                            end

                            --Note - have a rare issue where given reclaim order far away in QUIET; however it doesnt show up on the navigator currenttargetpos
                            if bDebugMessages == true then
                                LOG(sFunctionRef..': Have been given a reclaim order, oEngineer[AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefoOrderUnitTarget].CachePosition='..repru(oEngineer[AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefoOrderUnitTarget].CachePosition)..'; Eng position='..repru(oEngineer:GetPosition())..'; Target max mass reclaim='..(oEngineer[AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefoOrderUnitTarget].MaxMassReclaim or 'nil'))
                                if oEngineer[AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefoOrderUnitTarget].CachePosition then LOG(sFunctionRef..': Dist to cache position='..AiBotUtilities.GetDistanceBetweenPositions(oEngineer:GetPosition(), oEngineer[AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefoOrderUnitTarget].CachePosition)) end
                                local oNavigator = oEngineer:GetNavigator()
                                if oNavigator then
                                    local tCurNavigatorTarget = oNavigator:GetCurrentTargetPos()
                                    if bDebugMessages == true then LOG(sFunctionRef..': Dist to tCurNavigatorTarget='..AiBotUtilities.GetDistanceBetweenPositions(tCurNavigatorTarget, oEngineer:GetPosition())) end
                                end
                            end
                            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                            return false
                        else
                            if bDebugMessages == true then LOG(sFunctionRef..'; Will return false') end
                            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                            return false
                        end
                    end
                end
            end
        else
            if bDebugMessages == true then LOG(sFunctionRef..': Engineer is building or repairing so treating as unavailable in most cases') end --, refiEngineerBuildWithoutFocusUnitCount='..(oEngineer[refiEngineerBuildWithoutFocusUnitCount] or 0)) end
            if oEngineer:IsUnitState('Building') then
                local oFocusObject = oEngineer:GetFocusUnit()
                if oFocusObject then
                    if bDebugMessages == true then LOG(sFunctionRef..': Engineer oFocusObject='..(oFocusObject.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oFocusObject) or 'nil')..'; Focus object fraction complete='..oFocusObject:GetFractionComplete()..'; Focus object work progress='..oFocusObject:GetWorkProgress()) end
                    if oEngineer[refiEngineerBuildWithoutFocusUnitCount] then oEngineer[refiEngineerBuildWithoutFocusUnitCount] = 0 end
                else
                    if bDebugMessages == true then LOG(sFunctionRef..': Engi is building without a focus object, will increase refiEngineerBuildWithoutFocusUnitCount') end
                    if (oEngineer[refiEngineerBuildWithoutFocusUnitCount] or 0) == 0 then
                        oEngineer[refiEngineerBuildWithoutFocusUnitCount] = 1
                        --oEngineer[reftEngineerBuildWithoutFocusUnitPosition] = {oEngineer:GetPosition()[1], oEngineer:GetPosition()[2], oEngineer:GetPosition()[3]}
                    else
                        oEngineer[refiEngineerBuildWithoutFocusUnitCount] = oEngineer[refiEngineerBuildWithoutFocusUnitCount] + 1
                        if oEngineer[refiEngineerBuildWithoutFocusUnitCount] >= 30 then
                            --If close to unit cap consider killing units
                            if bDebugMessages == true then LOG(sFunctionRef..': refbCloseToUnitCap='..tostring(oEngineer:GetAIBrain()[AiBotOverseer.refbCloseToUnitCap] or false)..'; will check unit cap in case that is why we are unable to build') end
                            oEngineer[refiEngineerBuildWithoutFocusUnitCount] = 0
                            AiBotOverseer.CheckUnitCap(oEngineer:GetAIBrain())
                        end
                    end
                end
            elseif oEngineer:IsUnitState('Repairing') then
                --Repairing GE template unit that has a long way until completed - reassess periodically what we whould do with the engineer (as it may have made sense to repair to use up spare mass a while ago, but we may no longer want to do that now)
                if not(oEngineer[AiBotEngineer.refiAssignedAction]) and not(oEngineer[AiBotEngineer.refiRepairProgressWhenLastChecked]) then
                    --E.g. might be we cleared engineer tracking to make available, but it wasnt given any new orders, and is still repairing, in which case want to still keep it as being available
                    local oFocusUnit = oEngineer:GetFocusUnit()
                    if AiBotUnitInfo.IsUnitValid(oFocusUnit) and oFocusUnit[AiBotBuilding.reftArtiTemplateRefs] and oFocusUnit:GetFractionComplete() < 0.5 and oFocusUnit:GetFractionComplete() > 0.1 and (oFocusUnit[AiBotUnitInfo.refiUnitMassCost] or AiBotUnitInfo.GetUnitMassCost(oFocusUnit)) >= 30000 and oEngineer:GetAIBrain():GetEconomyStoredRatio('MASS') < 0.05 then
                        if bDebugMessages == true then LOG(sFunctionRef..': Will treat engi as available despite no value for refiRepairProgressWhenLastChecked') end
                        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                        return true
                    end
                end
                if bDebugMessages == true then LOG(sFunctionRef..': Engi is repairing, oEngineer[AiBotEngineer.refiRepairProgressWhenLastChecked]='..(oEngineer[AiBotEngineer.refiRepairProgressWhenLastChecked] or 'nil')) end
                if oEngineer[AiBotEngineer.refiRepairProgressWhenLastChecked] then
                    local oFocusUnit = oEngineer:GetFocusUnit()
                    if bDebugMessages == true then LOG(sFunctionRef..': Expect we are repairing an arti/similar in a GE template but not part of GE template logic, oFocusUnit='..(oFocusUnit.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oFocusUnit) or 'nil')..'; Work progress='..oEngineer:GetWorkProgress()..'; oEngineer[AiBotEngineer.refiRepairProgressWhenLastChecked]='..oEngineer[AiBotEngineer.refiRepairProgressWhenLastChecked]..'; Brain % mass stored='..oEngineer:GetAIBrain():GetEconomyStoredRatio('MASS')) end
                    if AiBotUnitInfo.IsUnitValid(oFocusUnit) and oFocusUnit[AiBotBuilding.reftArtiTemplateRefs] and oFocusUnit:GetFractionComplete() < 0.5 and oFocusUnit:GetFractionComplete() > oEngineer[AiBotEngineer.refiRepairProgressWhenLastChecked] + 0.1 and (oFocusUnit[AiBotUnitInfo.refiUnitMassCost] or AiBotUnitInfo.GetUnitMassCost(oFocusUnit)) >= 30000 and oEngineer:GetAIBrain():GetEconomyStoredRatio('MASS') < 0.05 then
                        if bDebugMessages == true then LOG(sFunctionRef..': Will treat engineer as available and return true') end
                        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                        return true
                    end
                end

            end

            --Below was to try and resolve issue with engi appearing to try and build somewhere and failing, but realised likely was just unit cap
            --if not(oEngineer[AiBotEngineer.refbHasSpareAction]) then
            --local tLastOrderPosition = oEngineer[AiBotOrders.reftiLastOrders][oEngineer[AiBotOrders.refiOrderCount]][AiBotOrders.subreftOrderPosition]
