                    local tPotentialBuildLocations = AiBotEngineer.GetPotentialBuildLocationsNearLocation(oEngineer:GetAIBrain(), tLZOrWZData, iPlateauOrZero, iLandOrWaterZone, AiBotUnitInfo.GetBuildingSize(sLastBlueprint), nil)
