function SafeToUpgradeUnit(oUnit)
    --Returns true if safe to upgrade oUnit

    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'SafeToUpgradeUnit'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    if AiBotOverseer.bNoRushActive and AiBotOverseer.iNoRushTimer - GetGameTimeSeconds() >= 120 then --have al ower 60s timer later on which just flags the zone as safe but does other checks after that
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        return true
    end

    local iPlateauOrZero, iLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oUnit:GetPosition())
    local bSafeZone = false

    --If have land exp and dealing with ACU then treat as not safe
    if EntityCategoryContains(categories.COMMAND, oUnit.UnitId) and AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[oUnit:GetAIBrain().AiBotTeam][AiBotTeam.reftEnemyLandExperimentals]) == false then
        local iTeam = oUnit:GetAIBrain().AiBotTeam
        local iCurDist
        for iExp, oExp in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyLandExperimentals] do
            if not(oExp.Dead) and oExp[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][1] == iPlateauOrZero then
                iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oExp:GetPosition())
                if bDebugMessages == true then LOG(sFunctionRef..': Dist of oExp='..oExp.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oExp)..' to ACU='..iCurDist) end
                if iCurDist < 150 then
                    if bDebugMessages == true then LOG(sFunctionRef..': Within 150 of Exp so not safe to upgrade here') end
                    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                    return false
                end
            end
        end
    end

    if (iLandOrWaterZone or 'nil') > 0 and not(iPlateauOrZero == 0) then
        local tLZData = AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iLandOrWaterZone]
        if AiBotUtilities.IsTableEmpty(tLZData) == false then
            local tLZTeamData = tLZData[AiBotMap.subrefLZTeamData][oUnit:GetAIBrain().AiBotTeam]
            --Have we recently canceled our upgrade? If so then dont get
            if bDebugMessages == true then LOG(sFunctionRef..': Time since last cancelled='..GetGameTimeSeconds() - (oUnit[AiBotUnitInfo.refiTimeLastCanceledUpgrade] or 0)) end
            if oUnit[AiBotUnitInfo.refiTimeLastCanceledUpgrade] then
                local iTimeSinceLastCancelled = GetGameTimeSeconds() - oUnit[AiBotUnitInfo.refiTimeLastCanceledUpgrade]
                local bCancel = false
                if iTimeSinceLastCancelled <= 30 then
                    bCancel = true
                elseif iTimeSinceLastCancelled <= 60 then
                    local iDistToBase = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tLZTeamData[AiBotMap.reftClosestEnemyBase])
                    if iDistToBase - (oUnit[AiBotUnitInfo.refiDistToEnemyBaseWhenLastCanceledUpgrade] or 0) < 50 then
                        bCancel = true
                    end
                end
                if bDebugMessages == true then LOG(sFunctionRef..': Considering whether to cancel due to recently cancelling upgrade, iTimeSinceLastCancelled='..iTimeSinceLastCancelled..'; Dist to enemy base='..AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tLZTeamData[AiBotMap.reftClosestEnemyBase])..'; Dist when we cancelled='..(oUnit[AiBotUnitInfo.refiDistToEnemyBaseWhenLastCanceledUpgrade] or 0)..'; bCancel='..tostring(bCancel)) end
                if bCancel then
                    if bDebugMessages == true then LOG(sFunctionRef..': Will return false (that not safe') end
                    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                    return false
                end
            end
            if not(tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ] or tLZTeamData[AiBotMap.subrefbDangerousEnemiesInAdjacentWZ]) then
                bSafeZone = true
            elseif tLZTeamData[AiBotMap.subrefLZbCoreBase] and tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] < 150 then
                if bDebugMessages == true then LOG(sFunctionRef..': Are in a core base so treating it as safe to upgrade as enemy lacks significant threat in this zone specificaly; however will make an exception if enemy has significant threat nearby, tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ]='..tostring(tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ] or false)..'; Is table of nearest df enemies empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoNearestDFEnemies]))..'; Dist to closest enemy base='..AiBotUtilities.GetDistanceBetweenPositions(tLZData[AiBotMap.subrefMidpoint], tLZTeamData[AiBotMap.reftClosestEnemyBase])) end
                bSafeZone = true
                if tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ] and iPlateauOrZero > 0 and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoNearestDFEnemies]) == false and AiBotMap.iMapSize >= 512 and AiBotUtilities.GetDistanceBetweenPositions(tLZData[AiBotMap.subrefMidpoint], tLZTeamData[AiBotMap.reftClosestEnemyBase]) >= 180 then
                    local iTeam = oUnit:GetAIBrain().AiBotTeam
                    local iRangeThreshold = math.max(20, oUnit[AiBotUnitInfo.refiCombatRange]) --i.e. a guncom ignores enemies with less range than it
                    local iThreatThreshold = 150
                    local iDistUntilInRangeThreshold = 50
                    local iCurThreat = tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal]
                    if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                        for _, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
                            local tAdjLZData = AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iAdjLZ]
                            local tAdjLZTeamData = tAdjLZData[AiBotMap.subrefLZTeamData][iTeam]
                            if bDebugMessages == true then LOG(sFunctionRef..': Considering iAdjLZ='..iAdjLZ..'; Enemy combat total in this zone='..tAdjLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal]) end
                            if tAdjLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] >= 150 then
                                for iEnemy, oEnemy in tAdjLZTeamData[AiBotMap.subrefTEnemyUnits] do
                                    if bDebugMessages == true and not(oEnemy.Dead) then LOG(sFunctionRef..': Considering enemy unit '..oEnemy.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEnemy)..'; Dist to us='..AiBotUtilities.GetDistanceBetweenPositions(oEnemy:GetPosition(), oUnit:GetPosition())..'; Combat range='..oEnemy[AiBotUnitInfo.refiCombatRange]..'; iRangeThreshold='..iRangeThreshold) end
                                    if oEnemy[AiBotUnitInfo.refiCombatRange] >= iRangeThreshold and not(oEnemy.Dead) then
                                        if AiBotUtilities.GetDistanceBetweenPositions(oEnemy:GetPosition(), oUnit:GetPosition()) - oEnemy[AiBotUnitInfo.refiCombatRange] <= iDistUntilInRangeThreshold then
                                            iCurThreat = iCurThreat + AiBotUnitInfo.GetCombatThreatRating({ oEnemy }, true)
                                            if bDebugMessages == true then LOG(sFunctionRef..': iCurThreat after reflecting this unit='..iCurThreat..'; iThreatThreshold='..iThreatThreshold) end
                                            if iCurThreat >= iThreatThreshold then
                                                bSafeZone = false
                                                break
                                            end
                                        end
                                    end
                                end
                            end
                        end
                    end
                    if bSafeZone and AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefAdjacentWaterZones]) == false then
                        local iAdjWZ, iPond
                        for iEntry, tSubtable in tLZData[AiBotMap.subrefAdjacentWaterZones] do
                            iAdjWZ = tSubtable[AiBotMap.subrefAWZRef]
                            iPond = AiBotMap.tiPondByWaterZone[iAdjWZ]
                            local tAdjWZTeamData = AiBotMap.tPondDetails[iPond][AiBotMap.subrefPondWaterZones][iAdjWZ][AiBotMap.subrefWZTeamData][iTeam]
                            if (tAdjWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0) >= 20 and tAdjWZTeamData[AiBotMap.subrefWZBestEnemyDFRange] > iRangeThreshold and AiBotUtilities.IsTableEmpty(tAdjWZTeamData[AiBotMap.subrefTEnemyUnits]) == false then
                                for iEnemy, oEnemy in tAdjWZTeamData[AiBotMap.subrefTEnemyUnits] do
                                    if oEnemy[AiBotUnitInfo.refiCombatRange] >= iRangeThreshold and not(oEnemy.Dead) then
                                        if AiBotUtilities.GetDistanceBetweenPositions(oEnemy:GetPosition(), oUnit:GetPosition()) - oEnemy[AiBotUnitInfo.refiCombatRange] <= iDistUntilInRangeThreshold then
                                            iCurThreat = iCurThreat + AiBotUnitInfo.GetCombatThreatRating({ oEnemy }, true)
                                            if iCurThreat >= iThreatThreshold then
                                                bSafeZone = false
                                                break
                                            end
                                        end
                                    end
                                end
                            end
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': iCurThreat after detailed check (but stopping if we get to the threshold)='..iCurThreat..'; iThreatThreshold='..iThreatThreshold..'; bSafeZone='..tostring(bSafeZone)) end
                end
            end
            --ACU specific:
            if EntityCategoryContains(categories.COMMAND, oUnit.UnitId) and tLZTeamData[AiBotMap.reftClosestFriendlyBase] then
                if bDebugMessages == true then LOG(sFunctionRef..': Considering upgrading ACU, iLandOrWaterZone='..iLandOrWaterZone..'; bSafeZone before extra checks='..tostring(bSafeZone or false)..'; tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ]='..tostring(tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ] or false)..'; ACU health='..AiBotUnitInfo.GetUnitHealthPercent(oUnit)..'; Is table of nearby friendly T2 PD empty='..tostring(AiBotUtilities.IsTableEmpty(oUnit:GetAIBrain():GetUnitsAroundPoint(AiBotUnitInfo.refCategoryT2PlusPD, oUnit:GetPosition(), 15, 'Ally')))..'; ACU owned by player '..oUnit:GetAIBrain().Nickname) end
                -- dont treat as safe if low health unless close to a base
                local iDistToClosestFriendlyBase = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tLZTeamData[AiBotMap.reftClosestFriendlyBase])
                if bSafeZone and iDistToClosestFriendlyBase > 10 then
                    if AiBotUnitInfo.GetUnitHealthPercent(oUnit) < 0.5 then
                        bSafeZone = false
                    elseif iDistToClosestFriendlyBase >= 50 then
                        --ACU out of base, check slightly further afield than just adjacent zone for indirect fire enemies that coudl cause us problems
                        local iMaxSearchRange = math.min(iDistToClosestFriendlyBase*1.5, 150)
                        local iOtherPlateauOrZero
                        local iTeam = oUnit:GetAIBrain().AiBotTeam
                        local iEnemyRangeThreshold = oUnit[AiBotUnitInfo.refiDFRange]
                        local bEnemyHasLongerRangedUnits = false
                        if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefOtherLandAndWaterZonesByDistance]) == false then
                            for iEntry, tSubtable in tLZData[AiBotMap.subrefOtherLandAndWaterZonesByDistance] do
                                if tSubtable[AiBotMap.subrefiDistance] > iMaxSearchRange then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Are outside the max range so wil stop searching') end
                                    break
                                end
                                --Add to potential zone table
                                local tAltLZOrWZData
                                local tAltLZOrWZTeamData
                                if tSubtable[AiBotMap.subrefbIsWaterZone] then
                                    iOtherPlateauOrZero = 0

                                    tAltLZOrWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[tSubtable[AiBotMap.subrefiLandOrWaterZoneRef]]][AiBotMap.subrefPondWaterZones][tSubtable[AiBotMap.subrefiLandOrWaterZoneRef]]
                                    tAltLZOrWZTeamData = tAltLZOrWZData[AiBotMap.subrefWZTeamData][iTeam]
                                    if (tAltLZOrWZTeamData[AiBotMap.subrefWZBestEnemyDFRange] or 0) > iEnemyRangeThreshold then bEnemyHasLongerRangedUnits = true break end
                                else
                                    iOtherPlateauOrZero = tSubtable[AiBotMap.subrefiPlateauOrPond]
                                    tAltLZOrWZData = AiBotMap.tAllPlateaus[iOtherPlateauOrZero][AiBotMap.subrefPlateauLandZones][tSubtable[AiBotMap.subrefiLandOrWaterZoneRef]]
                                    tAltLZOrWZTeamData = tAltLZOrWZData[AiBotMap.subrefLZTeamData][iTeam]
                                    if bDebugMessages == true then LOG(sFunctionRef..': Considering other land zone '..tSubtable[AiBotMap.subrefiLandOrWaterZoneRef]..'; Enemy best mobile DF range='..tAltLZOrWZTeamData[AiBotMap.subrefLZThreatEnemyBestMobileDFRange]..'; Enemy best mobile indirect range='..tAltLZOrWZTeamData[AiBotMap.subrefLZThreatEnemyBestMobileIndirectRange]..'; Enemy combat='..tAltLZOrWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal]..'; Ally mobile DF='..tAltLZOrWZTeamData[AiBotMap.subrefLZThreatAllyMobileDFTotal]) end
                                    if tAltLZOrWZTeamData[AiBotMap.subrefLZThreatEnemyBestMobileDFRange] > iEnemyRangeThreshold or tAltLZOrWZTeamData[AiBotMap.subrefLZThreatEnemyBestMobileIndirectRange] > iEnemyRangeThreshold then
                                        if tAltLZOrWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] > tAltLZOrWZTeamData[AiBotMap.subrefLZThreatAllyMobileDFTotal] * 0.5 then
                                            bEnemyHasLongerRangedUnits = true break
                                        end
                                    end
                                end
                            end
                        end
                        if bEnemyHasLongerRangedUnits then bSafeZone = false end
                    end
                end
                --Treat as safe if are near T2 PD and have at least 40% health, and enemy lacks significant indirect fire threat nearby, and doesnt have huge DF threat nearby
                if not(bSafeZone) and AiBotUnitInfo.GetUnitHealthPercent(oUnit) >= 0.4 and AiBotUnitInfo.GetUnitHealthAndShieldPercent(oUnit) >= 0.4 then
                    if AiBotUtilities.IsTableEmpty(oUnit:GetAIBrain():GetUnitsAroundPoint(AiBotUnitInfo.refCategoryT2PlusPD, oUnit:GetPosition(), 15, 'Ally')) == false then
                        if bDebugMessages == true then LOG(sFunctionRef..': ACU near PD so will treat as safe') end
                        bSafeZone = true
                    elseif AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefLZThreatAllyStructureDFByRange]) == false then
                        local iTotalLongRangePDThreat = 0
                        for iRange, iThreat in tLZTeamData[AiBotMap.subrefLZThreatAllyStructureDFByRange] do
                            if iRange >= 50 then
                                iTotalLongRangePDThreat = iTotalLongRangePDThreat + iThreat
                            end
                        end
                        --If have decent amount of T2 PD in this zone then even if we arent close to the PD still  consider this safe if we are close to the midpoint which ought to be covered by said PD
                        if bDebugMessages == true then LOG(sFunctionRef..': iTotalLongRangePDThreat='..iTotalLongRangePDThreat..'; Distance to midpoint='..AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tLZData[AiBotMap.subrefMidpoint])) end
                        if iTotalLongRangePDThreat >= 1500 then
                            if AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tLZData[AiBotMap.subrefMidpoint]) <= 10 then
                                if bDebugMessages == true then LOG(sFunctionRef..': Is table of T2+ PD in longer range empty='..tostring(AiBotUtilities.IsTableEmpty(oUnit:GetAIBrain():GetUnitsAroundPoint(AiBotUnitInfo.refCategoryT2PlusPD, oUnit:GetPosition(), 40, 'Ally')))) end
                                if AiBotUtilities.IsTableEmpty(oUnit:GetAIBrain():GetUnitsAroundPoint(AiBotUnitInfo.refCategoryT2PlusPD, oUnit:GetPosition(), 40, 'Ally')) == false then
                                    bSafeZone = true
                                end
                            end
                        end
                    end
                    --Exception - enemy has MMLs or other long ranged units nearby, or large DF threat
                    if bSafeZone then
                        local iTeam = oUnit:GetAIBrain().AiBotTeam
                        local iRangeThreshold = math.max(55, oUnit[AiBotUnitInfo.refiCombatRange])
                        local iThreatThreshold = 400
                        local iShortAndLongRangedThreatThreshold = 500 + AiBotUnitInfo.GetCombatThreatRating(oUnit, false) + tLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal]  --set high as good chance we are pushed back to our base if there is nearby PD, and may want combat upgrade to have a chance; but ned to balance against it being obviously wrong to get an upgrade due to how high enemy threat is
                        if tLZTeamData[AiBotMap.subrefLZbCoreBase] and tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] < 500 then iShortAndLongRangedThreatThreshold = iShortAndLongRangedThreatThreshold * 1.1 end --if at our core base then more likely we will get support from gunships and building more PD
                        local iDistUntilInRangeThreshold = 40
                        local iCurThreat = tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal]
                        if iCurThreat > iShortAndLongRangedThreatThreshold then bSafeZone = false
                        else
                            local iShortAndLongRangedThreat = 0
                            local bConsiderShortRangedThreats, iCurDistLessRange

                            if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                                for _, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
                                    local tAdjLZData = AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iAdjLZ]
                                    local tAdjLZTeamData = tAdjLZData[AiBotMap.subrefLZTeamData][iTeam]
                                    bConsiderShortRangedThreats = false
                                    if tAdjLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFTotal] >= 2000 then bConsiderShortRangedThreats = true end

                                    if tAdjLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] >= 150 then
                                        for iEnemy, oEnemy in tAdjLZTeamData[AiBotMap.subrefTEnemyUnits] do
                                            if not(oEnemy.Dead) then
                                                if oEnemy[AiBotUnitInfo.refiCombatRange] >= iRangeThreshold then
                                                    if AiBotUtilities.GetDistanceBetweenPositions(oEnemy:GetPosition(), oUnit:GetPosition()) - oEnemy[AiBotUnitInfo.refiCombatRange] <= iDistUntilInRangeThreshold then
                                                        iCurThreat = iCurThreat + AiBotUnitInfo.GetCombatThreatRating({ oEnemy }, true)
                                                        if iCurThreat >= iThreatThreshold then
                                                            bSafeZone = false
                                                            break
                                                        end
                                                    end
                                                elseif bConsiderShortRangedThreats and (oEnemy[AiBotUnitInfo.refiDFRange] or 0) > 0 then
                                                    iCurDistLessRange = AiBotUtilities.GetDistanceBetweenPositions(oEnemy:GetPosition(), oUnit:GetPosition()) - oUnit[AiBotUnitInfo.refiDFRange]
                                                    if iCurDistLessRange <= iDistUntilInRangeThreshold and (iCurDistLessRange <= 5 or EntityCategoryContains(categories.MOBILE, oEnemy.UnitId)) then
                                                        iShortAndLongRangedThreat = iShortAndLongRangedThreat + AiBotUnitInfo.GetCombatThreatRating({ oEnemy }, true)
                                                    end
                                                end
                                            end
                                        end
                                    end
                                end
                            end
                            if bSafeZone and AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefAdjacentWaterZones]) == false then
                                local iAdjWZ, iPond
                                for iEntry, tSubtable in tLZData[AiBotMap.subrefAdjacentWaterZones] do
                                    iAdjWZ = tSubtable[AiBotMap.subrefAWZRef]
                                    iPond = AiBotMap.tiPondByWaterZone[iAdjWZ]
                                    local tAdjWZTeamData = AiBotMap.tPondDetails[iPond][AiBotMap.subrefPondWaterZones][iAdjWZ][AiBotMap.subrefWZTeamData][iTeam]
                                    bConsiderShortRangedThreats = false
                                    if tAdjWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] >= 2000 then bConsiderShortRangedThreats = true end
                                    if (bConsiderShortRangedThreats or ((tAdjWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0) >= 20 and tAdjWZTeamData[AiBotMap.subrefWZBestEnemyDFRange] > iRangeThreshold)) and AiBotUtilities.IsTableEmpty(tAdjWZTeamData[AiBotMap.subrefTEnemyUnits]) == false then
                                        for iEnemy, oEnemy in tAdjWZTeamData[AiBotMap.subrefTEnemyUnits] do
                                            if not(oEnemy.Dead) then
                                                if oEnemy[AiBotUnitInfo.refiCombatRange] >= iRangeThreshold then
                                                    if AiBotUtilities.GetDistanceBetweenPositions(oEnemy:GetPosition(), oUnit:GetPosition()) - oEnemy[AiBotUnitInfo.refiCombatRange] <= iDistUntilInRangeThreshold then
                                                        iCurThreat = iCurThreat + AiBotUnitInfo.GetCombatThreatRating({ oEnemy }, true)
                                                        if iCurThreat >= iThreatThreshold then
                                                            bSafeZone = false
                                                            break
                                                        end
                                                    end
                                                elseif bConsiderShortRangedThreats and (oEnemy[AiBotUnitInfo.refiDFRange] or 0) > 0 then
                                                    iCurDistLessRange = AiBotUtilities.GetDistanceBetweenPositions(oEnemy:GetPosition(), oUnit:GetPosition()) - oUnit[AiBotUnitInfo.refiDFRange]
                                                    if iCurDistLessRange <= math.min(10, iDistUntilInRangeThreshold) and (iCurDistLessRange <= 5 or EntityCategoryContains(categories.MOBILE, oEnemy.UnitId)) then
                                                        iShortAndLongRangedThreat = iShortAndLongRangedThreat + AiBotUnitInfo.GetCombatThreatRating({ oEnemy }, true)
                                                    end
                                                end
                                            end
                                        end
                                    end
                                end
                            end
                            iShortAndLongRangedThreat = iShortAndLongRangedThreat + iCurThreat
                            if iShortAndLongRangedThreat > iShortAndLongRangedThreatThreshold then bSafeZone = false end
                            if bDebugMessages == true then LOG(sFunctionRef..': iShortAndLongRangedThreatThreshold='..iShortAndLongRangedThreatThreshold..'; iShortAndLongRangedThreat='..iShortAndLongRangedThreat..'; LR threat only iCurThreat='..iCurThreat) end
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': bSafeZone after checking for nearby longer ranged enemies='..tostring(bSafeZone)) end
                    end
                end
            end

            --If this mex has survived 5 mins and has no enemies in this zone itself, then treat as safe
            if not(bSafeZone) and EntityCategoryContains(AiBotUnitInfo.refCategoryMex, oUnit.UnitId) and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefTEnemyUnits]) and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftLZEnemyAirUnits]) and GetGameTimeSeconds() - (oUnit[AiBotUnitInfo.refiTimeCreated] or 0) >= 300 then
                if GetGameTimeSeconds() - (oUnit[AiBotUnitInfo.refiTimeCreated] or 0) >= 420 or EntityCategoryContains(categories.TECH1, oUnit.UnitId) then
                    if bDebugMessages == true then LOG(sFunctionRef..': Mex survived a while so treating as safe, mex survived for '..GetGameTimeSeconds() - (oUnit[AiBotUnitInfo.refiTimeCreated] or 0)..' seconds') end
                    bSafeZone = true
                end
            end

            --Treat as safe if we are under a shield
            if not(bSafeZone) and AiBotUtilities.IsTableEmpty(oUnit[AiBotBuilding.reftoShieldsProvidingCoverage]) == false then
                local iCurShieldHealth, iMaxShieldHealth
                for iShield, oShield in oUnit[AiBotBuilding.reftoShieldsProvidingCoverage] do
                    if AiBotUnitInfo.IsUnitValid(oShield) then
                        iCurShieldHealth, iMaxShieldHealth = AiBotUnitInfo.GetCurrentAndMaximumShield(oUnit, false)
                        if (iCurShieldHealth or 0) >= (iMaxShieldHealth or -1) and iCurShieldHealth >= 2000 and iCurShieldHealth > iMaxShieldHealth * 0.9 then
                            if bDebugMessages == true then LOG(sFunctionRef..': Under fixed shield, iCurShieldHealth='..iCurShieldHealth..'; iMaxShieldHealth='..iMaxShieldHealth..'; so treating as safe') end
                            bSafeZone = true
                            break
                        end
                    end
                end
            end

            --If are within range of enemy t2 arti and not a core base then dont trear as safe unless both mex and arti alive for at least 8m
            if bDebugMessages == true then LOG(sFunctionRef..': Checking if enemy T2 arti in range if we think this is safe, bSafeZone='..tostring(bSafeZone)..'; iPlateau='..iPlateauOrZero..'; Is core base='..tostring(tLZTeamData[AiBotMap.subrefLZbCoreBase])..'; Zone='..(iLandOrWaterZone or 'nil')..'; Is table of enemy t2 arti empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits]))) end
            if bSafeZone and iPlateauOrZero > 0 and not(tLZTeamData[AiBotMap.subrefLZbCoreBase]) and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits]) == false then
                local bBothAliveForAWhile = true
                if GetGameTimeSeconds() - (oUnit[AiBotUnitInfo.refiTimeCreated] or 0) <= 480 then bBothAliveForAWhile = false
                else
                    for iArti, oArti in tLZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits] do
                        if bDebugMessages == true then LOG(sFunctionRef..': Time since Arti created='..GetGameTimeSeconds() - (oArti[AiBotUnitInfo.refiTimeCreated] or 0)) end
                        if GetGameTimeSeconds() - (oArti[AiBotUnitInfo.refiTimeCreated] or 0) <= 480 then bBothAliveForAWhile = false break end
                    end
                end
                if bDebugMessages == true then LOG(sFunctionRef..': bBothAliveForAWhile='..tostring(bBothAliveForAWhile)) end
                if not(bBothAliveForAWhile) then
                    local bEnemyArtiInRange = false
                    for iArti, oArti in tLZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits] do
                        if bDebugMessages == true then LOG(sFunctionRef..': Dist of enemy Arti to unit position='..AiBotUtilities.GetDistanceBetweenPositions(oArti:GetPosition(), oUnit:GetPosition())..'; Arti combat range='..oArti[AiBotUnitInfo.refiCombatRange]) end
                        if AiBotUtilities.GetDistanceBetweenPositions(oArti:GetPosition(), oUnit:GetPosition()) <= oArti[AiBotUnitInfo.refiCombatRange] then
                            bSafeZone = false
                            break
                        end
                    end
                end
            end
        else
            AiBotUtilities.ErrorHandler('Dont have a valid LZData table for iPlateauOrZero='..(iPlateauOrZero or 'nil')..'; iLandOrWaterZone='..(iLandOrWaterZone or 'nil')..'; Unit='..(oUnit.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oUnit) or 'nil')..'; will treat as safe for non-mobilre units only')
            if bDebugMessages == true then AiBotUtilities.DrawLocation(oUnit:GetPosition()) end
            if not(EntityCategoryContains(categories.MOBILE, oUnit.UnitId)) then
                bSafeZone = true
            end
        end
    else
        --probably have a water zone - consider if safe to upgrade
        local iWaterZone = AiBotMap.GetWaterZoneFromPosition(oUnit:GetPosition())
        if (iWaterZone or 0) > 0 then
            local iPond = AiBotMap.tiPondByWaterZone[iWaterZone]
            local tWZTeamData = AiBotMap.tPondDetails[iPond][AiBotMap.subrefPondWaterZones][iWaterZone][AiBotMap.subrefWZTeamData][oUnit:GetAIBrain().AiBotTeam]
            if not(tWZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentWZ]) then bSafeZone = true end
        end
    end
    if AiBotOverseer.bNoRushActive then
        if AiBotOverseer.iNoRushTimer - GetGameTimeSeconds() > 60 then
            bSafeZone = true
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': Nearing end of code, before TML check, bSafeZone='..tostring(bSafeZone)) end
    if bSafeZone then
        local bDangerousTML = false
        --TML adjust
        if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[oUnit:GetAIBrain().AiBotTeam][AiBotTeam.reftEnemyTML]) == false and not(IsTableOfUnitsStillValid(oUnit[AiBotBuilding.reftoShieldsProvidingCoverage])) then
            --Buildings alreayd record TML in range and if covered by TMD
            if EntityCategoryContains(AiBotUnitInfo.refCategoryProtectFromTML, oUnit.UnitId) then
                if AiBotUtilities.IsTableEmpty(oUnit[AiBotBuilding.reftTMDCoveringThisUnit]) and AiBotUtilities.IsTableEmpty(oUnit[AiBotBuilding.reftTMLInRangeOfThisUnit]) == false then
                    bDangerousTML = true
                end
            end
        else
            --Is this an ACU? If so dont want to upgrade in range of enemy TML unless we have TMD nearby
            if EntityCategoryContains(categories.COMMAND, oUnit.UnitId) then
                local bTMLInRange = false
                for iTML, oTML in AiBotTeam.tTeamData[oUnit:GetAIBrain().AiBotTeam][AiBotTeam.reftEnemyTML] do
                    if AiBotUnitInfo.IsUnitValid(oTML) and AiBotUtilities.GetDistanceBetweenPositions(oTML:GetPosition(), oUnit:GetPosition()) <= AiBotBuilding.iTMLMissileRange + 2 then
                        bTMLInRange = true
                        break
                    end
                end
                if bTMLInRange then
                    --Do we have TMD nearby?
                    local tNearbyTMD = oUnit:GetAIBrain():GetUnitsAroundPoint(AiBotUnitInfo.refCategoryTMD, oUnit:GetPosition(), 25, 'Ally')
                    local bNearbyTMD = false
                    if AiBotUtilities.IsTableEmpty(tNearbyTMD) == false then
                        for iTMD, oTMD in tNearbyTMD do
                            if AiBotUtilities.GetDistanceBetweenPositions(oTMD:GetPosition(), oUnit:GetPosition()) <= math.max(12, (oTMD[AiBotUnitInfo.refiMissileDefenceRange] or 12.5) - 5) then
                                bNearbyTMD = true
                                break
                            end
                        end
                    end
                    if not(bNearbyTMD) then
                        bDangerousTML = true
                    end
                end
            end
        end
        if not(bDangerousTML) then
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            return true
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return false

end

function HaveLowMass(aiBrain)
    --Not actually used as yet
    local bHaveLowMass = false
    if aiBrain[AiBotEconomy.refiGrossMassBaseIncome] <= math.min(1000, 400 * aiBrain[AiBotEconomy.refiBrainBuildRateMultiplier]) then --i.e. we dont ahve a paragon or crazy amount of SACUs
        local iMassStoredRatio = aiBrain:GetEconomyStoredRatio('MASS')
        if (iMassStoredRatio <= 0.15 or aiBrain:GetEconomyStored('MASS') <= 300) then
            if aiBrain[AiBotEconomy.refiNetMassBaseIncome] < 0.2 then bHaveLowMass = true
            elseif iMassStoredRatio <= 0.05 and aiBrain[AiBotEconomy.refiNetMassBaseIncome] < aiBrain[AiBotEconomy.refiGrossMassBaseIncome] * 0.05 then bHaveLowMass = true
            end
        end
    elseif aiBrain:GetEconomyStoredRatio('MASS') < 0.01 and aiBrain[AiBotEconomy.refiNetMassBaseIncome] < aiBrain[AiBotEconomy.refiGrossMassBaseIncome] * 0.01 and not(aiBrain[AiBotEconomy.refbBuiltParagon]) then
        bHaveLowMass = true
    end
    return bHaveLowMass
end

function TeamHasLowMass(iTeam)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'TeamHasLowMass'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local bHaveLowMass = false
    if not(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbBuiltParagon]) then
        if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass] then bHaveLowMass = true
        elseif AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] <= 400 * (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] or 1) * (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiHighestBrainBuildMultiplier] or 1) then --i.e. we dont ahve a paragon or crazy amount of SACUs
            local iMassStoredRatio = AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored]

            if (iMassStoredRatio <= 0.15 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored] <= 300 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]) then
                if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetMass] < 0.2 then bHaveLowMass = true
                elseif iMassStoredRatio <= 0.05 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetMass] < AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] * 0.05 then bHaveLowMass = true
                elseif GetGameTimeSeconds() - (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeOfLastMassStall] or -10) < 10 then
                    bHaveLowMass = true
                end
            end
        elseif AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] < 0.01 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetMass] < AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] * 0.01 then
            bHaveLowMass = true
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': Time='..GetGameTimeSeconds()..'; End of code, bHaveLowMass='..tostring(bHaveLowMass)..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass]..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored]..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]..'; Net mass='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetMass]..'; Time of last mass stall='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeOfLastMassStall] or 'nil')..'; Is team stalling='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass])) end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return bHaveLowMass
end

function HaveLowPower(iTeam)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'HaveLowPower'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    if bDebugMessages == true then LOG(sFunctionRef..': Time='..GetGameTimeSeconds()..', team='..iTeam..'; Net energy='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetEnergy]..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy]='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy] or false)..'; AiBotTeam.tTeamDta[iTeam][AiBotTeam.subrefiGrossEnergyWhenStalled]='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiGrossEnergyWhenStalled] or 'nil')..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy]..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored]..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]..'; Just built lots of power='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbJustBuiltLotsOfPower])..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass]..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTooLittleEnergyForUpgrade]='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTooLittleEnergyForUpgrade])..'; Min energy per tech='..AiBotEconomy.tiMinEnergyPerTech[AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]]..'; subrefiTeamAverageEnergyPercentStored='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored]) end
    local bHaveLowPower = false

    if (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] < 80000 or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] < 80000 * (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] or 1) * (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiHighestBrainResourceMultiplier] or 1) and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbBuiltParagon])))
         or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy] and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored] <= 0.5) then --Paragon gives 1000000 per sec I think
        if not(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbJustBuiltLotsOfPower]) or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetEnergy] < 0 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored] <= 0.8) then
            if (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetEnergy] < 0 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored] <= 0.95)
                    or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy]
                    or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] < AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiGrossEnergyWhenStalled] then
                bHaveLowPower = true
            elseif AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored] < AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] > 0.4 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 25 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored] <= 0.95 then
                bHaveLowPower = true
            else
                if AiBotMap.bIsLowMexMap and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] <= 2 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetEnergy] > 0 then
                    --Do nothing
                    --T1 spam where we havent stalled E with this amount, and/or we have positive net energy
                elseif AiBotTeam.tTeamData[iTeam][AiBotTeam.refbFocusOnT1Spam] and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetEnergy] >= 0 and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetEnergy] > 1 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamEnergyStored] >= 2000*AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]) and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetEnergy] >= 3 or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetEnergy] >= 2 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] <= 0.1) or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] > AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiGrossEnergyWhenStalled] and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] <= 0.3 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] > AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiGrossEnergyWhenStalled] * 1.05))) then
                    --Do nothing - dont have low power
                    --Dont have much more energy than when we last stalled - sometimes treat as low power (i.e. if we have low net energy, or dont have 100% energy stored)
                elseif AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] < AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiGrossEnergyWhenStalled] * 1.05 and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored] <= 0.99 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetEnergy] < AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] * 0.1 or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetEnergy] < AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] * 0.2 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.1)) then
                    bHaveLowPower = true
                    --Low power levels - apply slightly different test where it's ok to not have 100% energy
                elseif AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] <= 25 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] <= 2.2 then
                    --if bDebugMessages == true then LOG(sFunctionRef..': iTeam='..iTeam..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored]='..( AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored] or 'nil')..'; Lowest mass% stored='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] or 'nil')..'; Team net energy='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetEnergy] or 'nil')) end
                    if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored] >= math.max(0.35, math.min(0.9, AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] * 2.5)) and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetEnergy] >= 0.5 or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored] >= 0.9 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetEnergy] >= -9)) then
                        --Do nothing (false)
                    else
                        bHaveLowPower = true
                    end
                elseif AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.15 and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored] < 0.5 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTooLittleEnergyForUpgrade] or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] < AiBotEconomy.tiMinEnergyPerTech[AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]]) then
                    bHaveLowPower = true
                end
            end
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': End of code, bHaveLowPower='..tostring(bHaveLowPower)) end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return bHaveLowPower
end

function GetNumberOfConstructedUnitsMeetingCategoryInZone(tLZOrWZTeamData, iCategoryWanted)
    local iCount = 0
    if AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then
        local tUnitsOfCategory = EntityCategoryFilterDown(iCategoryWanted, tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
        if AiBotUtilities.IsTableEmpty(tUnitsOfCategory) == false then
            for iUnit, oUnit in tUnitsOfCategory do
                if AiBotUnitInfo.IsUnitValid(oUnit) and oUnit:GetFractionComplete() == 1 then
                    iCount = iCount + 1
                end
            end
        end
    end
    return iCount
end

function GetNumberOfConstructedUnitsInAirSubteam(iAirSubteam, iCategory)
    local iCount = 0
    for iBrain, oBrain in AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subreftoFriendlyAiBotBrains] do
        iCount = iCount + oBrain:GetCurrentUnits(iCategory)
    end
    return iCount
end

function GetNumberOfUnitsMeetingCategoryUnderConstructionInLandOrWaterZone(tLZTeamData, iCategoryWanted, bAllConstructionNotFactory, bReturnMassValueInstead)
    --Returns the number of factories that are building a unit meeting iCategoryWanted
    --if bAllConstructionNotFactory then instead returns number of part-complete units of iCategoryWanted
    local iAlreadyBuilding = 0
    if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then
        if bAllConstructionNotFactory then
            local tUnitsOfCategory = EntityCategoryFilterDown(iCategoryWanted, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
            if AiBotUtilities.IsTableEmpty(tUnitsOfCategory) == false then
                for iUnit, oUnit in tUnitsOfCategory do
                    if AiBotUnitInfo.IsUnitValid(oUnit) and oUnit:GetFractionComplete() < 1 then
                        if bReturnMassValueInstead then iAlreadyBuilding = iAlreadyBuilding + (oUnit[AiBotUnitInfo.refiUnitMassCost] or AiBotUnitInfo.GetUnitMassCost(oUnit))
                        else
                            iAlreadyBuilding = iAlreadyBuilding + 1
                        end
                    end
                end
            end
        else
            local tLZFactories = EntityCategoryFilterDown(categories.FACTORY, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
            if AiBotUtilities.IsTableEmpty(tLZFactories) == false then
                local oCurUnitBuilding
                for iFactory, oFactory in tLZFactories do
                    oCurUnitBuilding = oFactory:GetFocusUnit()
                    if oCurUnitBuilding and EntityCategoryContains(iCategoryWanted, oCurUnitBuilding) then
                        --LOG('Temp to check we have a factory building the category wanted - we do, oFactory='..oFactory.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oFactory)..'; Unit building='..oCurUnitBuilding.UnitId)
                        if bReturnMassValueInstead then iAlreadyBuilding = iAlreadyBuilding + (oCurUnitBuilding[AiBotUnitInfo.refiUnitMassCost] or AiBotUnitInfo.GetUnitMassCost(oCurUnitBuilding))
                        else
                            iAlreadyBuilding = iAlreadyBuilding + 1
                        end
                    end
                end
            end
        end
    end
    return iAlreadyBuilding
end

function WantMorePower(iTeam)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'WantMorePower'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local bWantMorePower = true
    if bDebugMessages == true then LOG(sFunctionRef..': Start of code at time '..GetGameTimeSeconds()..'; Gross energy='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy]..'; Energy when last unable to build air='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnergyWhenAirFactoryLastUnableToBuildAir] or 0)..'; Highest factory tech='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.refiHighestBrainResourceMultiplier]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.refiHighestBrainResourceMultiplier]..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.refbJustBuiltLotsOfPower]='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbJustBuiltLotsOfPower] or false)..'; HaveLowPower(iTeam)='..tostring(HaveLowPower(iTeam))..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiGrossEnergyWhenStalled]='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiGrossEnergyWhenStalled] or 'nil')) end
    if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 100000 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored] >= 0.5 and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy]) and (AiBotTeam.tTeamData[iTeam][AiBotTeam.refbBuiltParagon] or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored] >= 0.95)) then
        bWantMorePower = false
    elseif AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] < 1.25 * (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnergyWhenAirFactoryLastUnableToBuildAir] or 0) and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetEnergy] < math.max(250, AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] * 0.25) or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] < (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnergyWhenAirFactoryLastUnableToBuildAir] or 0) + 150) then
        --No change - want more power
        if bDebugMessages == true then LOG(sFunctionRef..': Want more given amount we had when unable to build air units') end
    elseif AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] >= 2 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] <= (30 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] + 160 * math.max(0, (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] - 2))) * AiBotTeam.tTeamData[iTeam][AiBotTeam.refiHighestBrainResourceMultiplier] * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] then
        --We dont have 1 pgen of our cur tech level (roughly) per brain so want more; i.e. no change
        if bDebugMessages == true then LOG(sFunctionRef..': Want base level of power given our tech level') end
        --Have re recently build lots of power, and at a high level it looks like we should have a decent amount of power for our mass income?
    elseif AiBotTeam.tTeamData[iTeam][AiBotTeam.refbJustBuiltLotsOfPower] and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] <= 0.3 or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] <= 0.6 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] > 20 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass]) or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] <= 0.98 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] > 30 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass])) then
        bWantMorePower = false
        if bDebugMessages == true then LOG(sFunctionRef..': Just built lots of power so dont want more') end
    else
        if HaveLowPower(iTeam) then
            bWantMorePower = true
            if bDebugMessages == true then LOG(sFunctionRef..': Have low power') end
        else
            local iExtraFactor = 1.1
            if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.5 then iExtraFactor = 1.5 end
            if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] < (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiGrossEnergyWhenStalled] or 0) * iExtraFactor then bWantMorePower = true
            else
                local iNetPowerWanted
                local iHighestTeamTech = AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]
                local iUpgradingMexAdditionalFactor = 0
                if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftTeamUpgradingMexes]) == false then
                    local iUpgradingMexes = 0
                    if iHighestTeamTech <= 2 then
                        iUpgradingMexes = table.getn(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftTeamUpgradingMexes])
                    else
                        local tUpgradingT2PlusMexes = EntityCategoryFilterDown(categories.TECH2 + categories.TECH3, AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftTeamUpgradingMexes])
                        if AiBotUtilities.IsTableEmpty(tUpgradingT2PlusMexes) == false then
                            iUpgradingMexes = table.getn(tUpgradingT2PlusMexes)
                        end
                    end
                    if iUpgradingMexes >= 3 then
                        iUpgradingMexAdditionalFactor = iUpgradingMexes * 0.02
                    end
                end
                if iHighestTeamTech >= 3 then

                    iNetPowerWanted = math.max(50, AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] * 0.2 + iUpgradingMexAdditionalFactor)

                elseif iHighestTeamTech == 2 then
                    iNetPowerWanted = math.max(15, AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] * 0.15 + iUpgradingMexAdditionalFactor)
                elseif AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 20 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] then
                    iNetPowerWanted = math.max(3, AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] * 0.1 + iUpgradingMexAdditionalFactor)
                else
                    iNetPowerWanted = 2
                end
                if AiBotTeam.tTeamData[iTeam][AiBotTeam.refiHighestBrainResourceMultiplier] > 1 then
                    iNetPowerWanted = iNetPowerWanted * (1 + (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiHighestBrainResourceMultiplier] - 1) * 0.5)
                end
                if bDebugMessages == true then LOG(sFunctionRef..': iNetPowerWanted='..iNetPowerWanted..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetEnergy]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetEnergy]) end
                if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetEnergy] < iNetPowerWanted then
                    if bDebugMessages == true then LOG(sFunctionRef..': Want more net power') end
                    bWantMorePower = true
                else
                    bWantMorePower = false
                end
            end
        end
    end
    --Override if close to the unit cap and have good net energy already
    if bDebugMessages == true then LOG(sFunctionRef..': Checking if should hold off building due to unit cap, bWantMorePower='..tostring(bWantMorePower)..'; Time since near unit cap='..(GetGameTimeSeconds() - (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeLastNearUnitCap] or -100))..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetEnergy]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetEnergy]) end
    if bWantMorePower and GetGameTimeSeconds() - (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeLastNearUnitCap] or -100) < 60 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetEnergy] > math.min(250, AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] * 0.4) then
        bWantMorePower = false
        if bDebugMessages == true then LOG(sFunctionRef..': Dont want more power due to unit cap') end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': End of code, bWantMorePower='..tostring(bWantMorePower)..'; Just built lots of power='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbJustBuiltLotsOfPower] or false)..'; HaveLowPower='..tostring(HaveLowPower(iTeam))..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy]='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] or 'nil')..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetEnergy]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetEnergy]) end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return bWantMorePower
end

function WantToReclaimEnergyNotMass(iTeam, iPlateau, iLandZone)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'WantToReclaimEnergyNotMass'
    if not(iPlateau) and not(iLandZone) then AiBotUtilities.ErrorHandler('Invalid arguments for if want to reclaim energy not mass') end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    if bDebugMessages == true then LOG(sFunctionRef..': Time='..GetGameTimeSeconds()..'; iTeam='..(iTeam or 'nil')..'; iPlateau='..(iPlateau or 'nil')..'; iLandZone='..(iLandZone or 'nil')..'; Lowest % energy='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored] or 'nil')..'; Gross energy='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] or 'nil')..'; Reclaim total energy='..(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone][AiBotMap.subrefLZTotalEnergyReclaim] or 'nil')..'; Net team energy='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetEnergy] or 'nil')) end
    if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored] <= 0.7 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] <= 80 and AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone][AiBotMap.subrefLZTotalEnergyReclaim] >= 100 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetEnergy] < 2 then
        if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] <= 0.05 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored] >= 0.3 then
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            return false
        --LOUD specific - more likely to have lower % stored due to higher E storage
        elseif (AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] <= math.min(0.25, AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored] * 3) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] >= 40 then
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            return false
        end

        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        return true
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return false
end


function HaveFactionTech(iSubteam, iFactoryType, iFactionWanted, iMinTechLevelNeeded)
    for iCurTech = iMinTechLevelNeeded, 3 do
        if AiBotTeam.tLandSubteamData[iSubteam][AiBotTeam.subrefFactoriesByTypeFactionAndTech][iFactoryType][iFactionWanted][iCurTech] > 0 then
            return true
        end
    end
    return false
end

function EnemyTeamHasFaction(iAiBotTeam, iEnemyFaction)
    for iBrain, oBrain in AiBotTeam.tTeamData[iAiBotTeam][AiBotTeam.subreftoEnemyBrains] do
        if oBrain:GetFactionIndex() == iEnemyFaction then return true end
    end
    return false
end

function IsUnitInRangeOfLRIndirectFireUnits(oUnit, tLZTeamData, iDistThreshold)
    --Checks whether oUnit can be attacked by any of the long range indirectfire units, or is within iDistThreshold of being able to be attacked
    if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefoNearbyEnemyLongRangeIFThreats]) == false then
        for iEnemy, oEnemy in tLZTeamData[AiBotMap.subrefoNearbyEnemyLongRangeIFThreats] do
            if AiBotUtilities.GetDistanceBetweenPositions(oEnemy:GetPosition(), oUnit:GetPosition()) - oEnemy[AiBotUnitInfo.refiCombatRange] <= iDistThreshold then
                return true
            end
        end
    end
end

function CloseToEnemyUnit(tStartPosition, tUnitsToCheck, iDistThreshold, iTeam, bIncludeEnemyDFRange, iAltThresholdToDFRange, oUnitIfConsideringAngleAndLastShot, oOptionalFriendlyUnitToRecordClosestEnemy, iOptionalDistThresholdForStructure, bIncludeEnemyAntiNavyRange, bIncludeEnemyIndirectRangeIfNoDFRange, iIndirectDistThresholdOverride)
    --Returns true if our distance to any of tUnitsToCheck is <= iDistThreshold; if bIncludeEnemyDFRange is true then our distance to the units is reduced by the enemy unit's DF range (meaning it returns true if we are within iDistThreshold of the enemy unit being able to shoot at us);
    --iAltThresholdToDFRange - if bIncludeEnemyDFRange is true and this also has a value specified, then if we are within iAltThresholdToDFRange will return true regardless of the iDistThreshold test; i.e. we will both check if enemy dist-DF range is within iDistThreshold, or if enemy dist is within iAltThresholdToDFRange
    --oUnitIfConsideringAngleAndLastShot - if we have a unit that is very vulnerable at lcose range (e.g. a skirmisher unit), then including this here will mean a check is done of the enemy unit facing angle and unit state (to factor in how easily it could close in to us) to decide whether to run or not
    --iIndirectDistThresholdOverride - iDistThreshold to use when checking IF ranges, only relevant if bIncludeEnemyIndirectRangeIfNoDFRange is true and the unit lacks a DF attack

    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'CloseToEnemyUnit'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    local iCurDist
    if bDebugMessages == true then
        LOG(sFunctionRef..': tStartPosition='..repru(tStartPosition)..'; Size of tUnitsToCheck='..table.getn(tUnitsToCheck)..'; iDistThreshold='..iDistThreshold..'; bIncludeEnemyDFRange='..tostring(bIncludeEnemyDFRange or false)..'; bIncludeEnemyIndirectRangeIfNoDFRange='..tostring(bIncludeEnemyIndirectRangeIfNoDFRange or false))
        for iUnit, oUnit in tUnitsToCheck do
            LOG(sFunctionRef..': Dist to oUnit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' = '..AiBotUtilities.GetDistanceBetweenPositions(tStartPosition, oUnit[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam])..' based on last known position of '..repru(oUnit[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam])..'; actual unit position='..repru(oUnit:GetPosition())..'; Unit range='..(oUnit[AiBotUnitInfo.refiDFRange] or 0)..'; Is distance less tahn threshold='..tostring(AiBotUtilities.GetDistanceBetweenPositions(tStartPosition, oUnit[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam]) < iDistThreshold))
        end
    end
    local bIncludeAngleChecks, iAngleDistMod, iAngleDifferenceThreshold, iMiniAngleDistMod, iMiniAngleThreshold, iCurAngleDif
    local bAreCloseToUnit = false
    if AiBotUnitInfo.IsUnitValid(oUnitIfConsideringAngleAndLastShot) then
        bIncludeAngleChecks = true
        iAngleDistMod = -3 --i.e. will decrease enemy unit range to us by this amount if they are facing a similar angle to us; we decrease it by even more than this if enemy is close to us in range
        iAngleDifferenceThreshold = 25 --if angle dif is less than this amount, will reduce enemy distance to us by iAngleDistMod
        iMiniAngleDistMod = -1.5
        iMiniAngleThreshold = iAngleDifferenceThreshold + 10
        --iOurFacingAngle = AiBotUnitInfo.GetUnitFacingAngle(oUnitIfConsideringAngleAndLastShot)

        --Adjust distance threshold if we have fired recently since being in range to fire again is less important
        if bDebugMessages == true then LOG(sFunctionRef..': About to adjust dist threshold based on if we have fired recently, iDistThreshold before adjustment='..iDistThreshold..'; Time='..GetGameTimeSeconds()..'; Last weapon event='..(oUnitIfConsideringAngleAndLastShot[AiBotUnitInfo.refiLastWeaponEvent] or -100)..'; Time between DF shots='..(oUnitIfConsideringAngleAndLastShot[AiBotUnitInfo.refiTimeBetweenDFShots] or 'nil')) end
        if GetGameTimeSeconds() - (oUnitIfConsideringAngleAndLastShot[AiBotUnitInfo.refiLastWeaponEvent] or -100) < (oUnitIfConsideringAngleAndLastShot[AiBotUnitInfo.refiTimeBetweenDFShots] or oUnitIfConsideringAngleAndLastShot[AiBotUnitInfo.refiTimeBetweenIFShots] or 100) then
            if GetGameTimeSeconds() - (oUnitIfConsideringAngleAndLastShot[AiBotUnitInfo.refiLastWeaponEvent] or -100) < (oUnitIfConsideringAngleAndLastShot[AiBotUnitInfo.refiTimeBetweenDFShots] or oUnitIfConsideringAngleAndLastShot[AiBotUnitInfo.refiTimeBetweenIFShots] or 100) - math.min(1.2, (oUnitIfConsideringAngleAndLastShot[AiBotUnitInfo.refiTimeBetweenDFShots] or oUnitIfConsideringAngleAndLastShot[AiBotUnitInfo.refiTimeBetweenIFShots] or 100) * 0.2) then
                iDistThreshold = iDistThreshold * 1
            else
                iDistThreshold = iDistThreshold * 1.06
            end
        else iDistThreshold = iDistThreshold * 0.94
        end
    end
    local iClosestEnemyDist, iCurSpeedX, iCurSpeedY, iCurSpeedZ, iDistanceShortly
    if oOptionalFriendlyUnitToRecordClosestEnemy then
        iClosestEnemyDist = 100000
        oOptionalFriendlyUnitToRecordClosestEnemy[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck] = nil
    end
    for iUnit, oUnit in tUnitsToCheck do
        if AiBotUnitInfo.IsUnitValid(oUnit) then
            iCurDist = AiBotUtilities.GetDistanceBetweenPositions(tStartPosition, oUnit[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam])
            if oOptionalFriendlyUnitToRecordClosestEnemy and iCurDist < iClosestEnemyDist then
                iClosestEnemyDist = iCurDist
                oOptionalFriendlyUnitToRecordClosestEnemy[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck] = oUnit
            end
            if bIncludeAngleChecks and EntityCategoryContains(categories.MOBILE, oUnit.UnitId) then
                local tCurPosition = oUnit:GetPosition()
                iCurSpeedX, iCurSpeedY, iCurSpeedZ = oUnit:GetVelocity()
                iDistanceShortly = AiBotUtilities.GetDistanceBetweenPositions({tCurPosition[1] + iCurSpeedX, tCurPosition[2] + iCurSpeedY, tCurPosition[3] + iCurSpeedZ}, tStartPosition)
                if bDebugMessages == true then LOG(sFunctionRef..': Will see if enemy appears to be moving closer to us, iCurDist='..iCurDist..'; iDistanceShortly='..iDistanceShortly) end
                if iDistanceShortly < iCurDist then
                    if oUnit[AiBotUnitInfo.refiCombatRange] + 5 > oUnitIfConsideringAngleAndLastShot[AiBotUnitInfo.refiCombatRange] then
                        iCurDist = iCurDist + math.min(iAngleDistMod, -(iCurDist - iDistanceShortly)*1.5)-3
                    elseif iDistanceShortly + 2.5 < iCurDist then
                        iCurDist = iCurDist + math.min(iAngleDistMod, -(iCurDist - iDistanceShortly))-1
                        if bDebugMessages == true then LOG(sFunctionRef..': Applying full angle dist mod, iDistanceShortly-iCurDist='..iDistanceShortly-iCurDist) end
                    elseif iDistanceShortly + 0.5 < iCurDist then
                        iCurDist = iCurDist + math.min(iMiniAngleDistMod, -(iCurDist - iDistanceShortly) * 1.5) - 0.5
                        if bDebugMessages == true then LOG(sFunctionRef..': Applying minor angle dist mod, iDistanceShortly-iCurDist='..iDistanceShortly-iCurDist) end
                    elseif bDebugMessages == true then LOG(sFunctionRef..': Wont apply any mod after considering direction unit is moving')
                    end
                elseif (oUnit[AiBotUnitInfo.refiCombatRange] + 3.5 > oUnitIfConsideringAngleAndLastShot[AiBotUnitInfo.refiCombatRange]) then
                    iCurAngleDif = AiBotUtilities.GetAngleDifference(AiBotUtilities.GetAngleFromAToB(tCurPosition, tStartPosition), AiBotUnitInfo.GetUnitFacingAngle(oUnit))
                    if iCurAngleDif <= iAngleDifferenceThreshold then
                        if bDebugMessages == true then LOG(sFunctionRef..': Unit facing angle='..AiBotUnitInfo.GetUnitFacingAngle(oUnit)..'; Angle to start position='..AiBotUtilities.GetAngleFromAToB(oUnit:GetPosition(), tStartPosition)..'; so will adjust iCurDist '..iCurDist..' by iAngleDistMod='..iAngleDistMod..'; will adjust further if it is moving, unit state='..AiBotUnitInfo.GetUnitState(oUnit)) end
                        iCurDist = iCurDist + iAngleDistMod
                    elseif iCurAngleDif <= iMiniAngleThreshold then
                        iCurDist = iCurDist + iMiniAngleDistMod
                        if bDebugMessages == true then LOG(sFunctionRef..': iCurAngleDif is below mini angle threshold, iCurAngleDif='..iCurAngleDif..'; iMiniAngleThreshold='..iMiniAngleThreshold..'; will adjust dist by iMiniAngleDistMod='..iMiniAngleDistMod) end
                    end
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': Considering enemy unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; bIncludeEnemyDFRange='..tostring(bIncludeEnemyDFRange or false)..'; Unit range='..(oUnit[AiBotUnitInfo.refiDFRange] or 0)..'; iCurDist='..iCurDist..'; iDistThreshold='..iDistThreshold..'; iAltThresholdToDFRange='..(iAltThresholdToDFRange or 'nil')) end
            if (bIncludeEnemyDFRange and (iCurDist - (oUnit[AiBotUnitInfo.refiDFRange] or 0) <= iDistThreshold or iCurDist <= (iAltThresholdToDFRange or 0) or (bIncludeEnemyIndirectRangeIfNoDFRange and (oUnit[AiBotUnitInfo.refiDFRange] or 0) == 0 and oUnit[AiBotUnitInfo.refiIndirectRange] and iCurDist - oUnit[AiBotUnitInfo.refiIndirectRange] <= (iIndirectDistThresholdOverride or iDistThreshold)) or (bIncludeEnemyAntiNavyRange and iCurDist - (oUnit[AiBotUnitInfo.refiAntiNavyRange] or 0) <= iDistThreshold))) or (not(bIncludeEnemyDFRange) and iCurDist <= iDistThreshold) then
                --Structure specific
                if not(iOptionalDistThresholdForStructure) or iCurDist <= iOptionalDistThresholdForStructure or not(EntityCategoryContains(AiBotUnitInfo.refCategoryStructure, oUnit.UnitId)) or (bIncludeEnemyDFRange and (oUnit[AiBotUnitInfo.refiDFRange] or 0) > 0 and iCurDist <= math.min(iDistThreshold, iOptionalDistThresholdForStructure) + (oUnit[AiBotUnitInfo.refiDFRange] or 0)) then
                    if bDebugMessages == true then LOG(sFunctionRef..': Are close to unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)) end
                    bAreCloseToUnit = true
                    --Want to keep searching to get the closest enemy unit if dont have one in range and have specified the closest unit be recorded
                    if not(oOptionalFriendlyUnitToRecordClosestEnemy) or iClosestEnemyDist <= -5 + math.max((oOptionalFriendlyUnitToRecordClosestEnemy[AiBotUnitInfo.refiDFRange] or 0), (oOptionalFriendlyUnitToRecordClosestEnemy[AiBotUnitInfo.refiIndirectRange] or 0)) then
                        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                        return true
                    end
                else
                    if bDebugMessages == true then LOG(sFunctionRef..': Are close to structure but not too close yet, iOptionalDistThresholdForStructure='..iOptionalDistThresholdForStructure) end
                end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return bAreCloseToUnit
end

function CloseToIFUnit(oUnit, tHiddenIFEnemies, iTeam, iReturnTrueIfWithinThisDistOfEnemyShootingUs)
    --Intended to be called for skirmisher units where we want them to stay out of range of enemy if we dont have intel of that enemy
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'CloseToIFUnit'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local tUnitPosition = oUnit:GetPosition()
    local iClosestEnemyLessRange, iCurDistLessRange
    if AiBotUnitInfo.IsUnitValid(oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]) then
        iClosestEnemyLessRange = AiBotUtilities.GetDistanceBetweenPositions(tUnitPosition, oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]:GetPosition()) - (oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck][AiBotUnitInfo.refiCombatRange] or 0)
    else
        iClosestEnemyLessRange = 10000
    end
    local oClosestIFUnit
    if bDebugMessages == true then LOG(sFunctionRef..': Checking hidden IF enemies for oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck] before this='..(oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck].UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]) or 'nil')..'; iClosestEnemyLessRange='..iClosestEnemyLessRange) end
    for iEnemy, oEnemy in tHiddenIFEnemies do
        iCurDistLessRange = AiBotUtilities.GetDistanceBetweenPositions(tUnitPosition, oEnemy[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam]) - oEnemy[AiBotUnitInfo.refiCombatRange]
        if bDebugMessages == true then LOG(sFunctionRef..': Considering oEnemy='..oEnemy.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEnemy)..'; iCurDistLessRange='..iCurDistLessRange..'; Dist based on last known position='..AiBotUtilities.GetDistanceBetweenPositions(tUnitPosition, oEnemy[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam])..'; Actual dist based on actual position='..AiBotUtilities.GetDistanceBetweenPositions(tUnitPosition, oEnemy:GetPosition())) end
        if iCurDistLessRange < iClosestEnemyLessRange then
            iClosestEnemyLessRange = iCurDistLessRange
            oClosestIFUnit = oEnemy
            if iClosestEnemyLessRange < iReturnTrueIfWithinThisDistOfEnemyShootingUs then
                break
            end
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': iClosestEnemyLessRange after check='..iClosestEnemyLessRange..'; oClosestIFUnit='..(oClosestIFUnit.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oClosestIFUnit) or 'nil')..'; Value that will return='..tostring(iClosestEnemyLessRange < iReturnTrueIfWithinThisDistOfEnemyShootingUs)) end
    if oClosestIFUnit then oUnit[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck] = oClosestIFUnit end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return iClosestEnemyLessRange < iReturnTrueIfWithinThisDistOfEnemyShootingUs
end

function TeamHasAirControl(iTeam)
--Returns true if any of the air subteams has air control
    local tbSubteams = {}
    for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains] do
        tbSubteams[oBrain.AiBotAirSubteam] = true
    end
    for iAirSubteam, bTrue in tbSubteams do
        if AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbHaveAirControl] then return true end
    end
    return false
end

function TeamIsFarBehindOnAir(iTeam)
    --Returns true if any of the air subteams is far behind on air
    local tbSubteams = {}
    for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains] do
        tbSubteams[oBrain.AiBotAirSubteam] = true
    end
    for iAirSubteam, bTrue in tbSubteams do
        if AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbFarBehindOnAir] then return true end
    end
    return false

end

function ZoneWantsT1Spam(tLZTeamData, iTeam)
    local bWantT1Spam = false
    if AiBotTeam.tTeamData[iTeam][AiBotTeam.refbFocusOnT1Spam] then
        bWantT1Spam = true
    elseif IsTableOfUnitsStillValid(tLZTeamData[AiBotMap.subrefoNearbyEnemyLandFacs]) and GetGameTimeSeconds() <= 900 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyLandFactoryTech] <= 2 then
        bWantT1Spam = true
    elseif AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] < 3 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyGroundTech] < 3 then
        local aiBrain = ArmyBrains[tLZTeamData[AiBotMap.reftiClosestFriendlyAiBotBrainIndex]]
        if aiBrain[AiBotOverseer.refbPrioritiseLowTech] and aiBrain[AiBotMap.refbCanPathToEnemyBaseWithLand] and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiLowestFriendlyLandFactoryTech] < 2 then
            bWantT1Spam = true
        end
    end
    if bWantT1Spam then
        local aiBrain = ArmyBrains[tLZTeamData[AiBotMap.reftiClosestFriendlyAiBotBrainIndex]]
        if aiBrain[AiBotOverseer.refbPrioritiseHighTech] or aiBrain[AiBotOverseer.refbPrioritiseNavy] or aiBrain[AiBotOverseer.refbPrioritiseDefence] or aiBrain[AiBotOverseer.refbPrioritiseAir] then
            bWantT1Spam = false
        end
    end
    return bWantT1Spam
end

function WantMoreFactories(iTeam, iPlateau, iLandZone, bIgnoreMainEcoConditions)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'WantMoreFactories'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    --e.g. 1 t1 land factory building tank uses 0.4 mass per tick, so would want 1 factory for every 0.8 mass as a rough baseline; T2 is 0.9 mass per tick, T3 is 1.6; probably want ratio to be 50%-50%-33%
    local tiGrossMassWantedPerFactoryByTech = {[1] = 1.2, [2] = 2.2, [3] = 5.5} --i.e. how much mass we want per tick for each factory of the tech level
    --Adjust factory T1 ratios if we cant path to enemy by land
    local tLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone]
    local tLZTeamData = tLZData[AiBotMap.subrefLZTeamData][iTeam]
    local aiBrain = ArmyBrains[tLZTeamData[AiBotMap.reftiClosestFriendlyAiBotBrainIndex]]


    local iCurIsland = NavUtils.GetLabel(AiBotMap.refPathingTypeLand, tLZData[AiBotMap.subrefMidpoint])
    local iEnemyIsland = NavUtils.GetLabel(AiBotMap.refPathingTypeLand, tLZTeamData[AiBotMap.reftClosestEnemyBase])
    if iCurIsland ~= iEnemyIsland and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] <= 0.35 then
        tiGrossMassWantedPerFactoryByTech = {[1]=3.5, [2] = 3.5, [3] = 6.5}
    elseif AiBotMap.iMapSize <= 256 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored] >= 60 then
        if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored] >= 120 then
            tiGrossMassWantedPerFactoryByTech[1] = 0.4
        else
            tiGrossMassWantedPerFactoryByTech[1] = 0.6
        end
    elseif AiBotMap.iMapSize >= 1000 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] < 3 and tLZTeamData[AiBotMap.subrefMexCountByTech][3] == 0 and tLZTeamData[AiBotMap.refiModDistancePercent] <= 0.2 then
        for iTech, iValue in tiGrossMassWantedPerFactoryByTech do
            if aiBrain[AiBotOverseer.refbPrioritiseNavy] or aiBrain[AiBotOverseer.refbPrioritiseHighTech] or aiBrain[AiBotOverseer.refbPrioritiseDefence] then
                tiGrossMassWantedPerFactoryByTech[iTech] = iValue * 4
            elseif not(AiBotUtilities.bQuietModActive) or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass] or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyLandFactoryTech] >= 3 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] <= 0.02) then
                tiGrossMassWantedPerFactoryByTech[iTech] = iValue * 2
            else
                tiGrossMassWantedPerFactoryByTech[iTech] = iValue * 1.5
            end
        end
        --10km+ maps with lots of mexes in core base and not many in this zone - reduce factories wanted if we have reached t2 already but arent at t3
    else
        if bDebugMessages == true then LOG(sFunctionRef..': High mex in base astro style map check, subrefiTeamAverageMassPercentStored='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored]..'; subrefLZOrWZMexCount='..tLZData[AiBotMap.subrefLZOrWZMexCount]..'; subrefMexCountByTech[3]='..tLZTeamData[AiBotMap.subrefMexCountByTech][3]..'; subrefiHighestFriendlyFactoryTech='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]..'; refiModDistancePercent='..tLZTeamData[AiBotMap.refiModDistancePercent]..'; refiEnemyMobileDFThreatNearOurSide='..AiBotTeam.tLandSubteamData[aiBrain.AiBotLandSubteam][AiBotTeam.refiEnemyMobileDFThreatNearOurSide]..'; refiAllyMobileDFThreatNearOurSide='..AiBotTeam.tLandSubteamData[aiBrain.AiBotLandSubteam][AiBotTeam.refiAllyMobileDFThreatNearOurSide]..'; refbFocusOnT1Spam='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbFocusOnT1Spam])..'; subrefLZbCoreBase='..tostring(tLZTeamData[AiBotMap.subrefLZbCoreBase])) end
        if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] <= 0.2 and tLZTeamData[AiBotMap.refiModDistancePercent] <= 0.35 and (tLZTeamData[AiBotMap.refiModDistancePercent] <= 0.25 or AiBotMap.iMapSize < 1000) and (tLZData[AiBotMap.subrefLZOrWZMexCount] <= 3 or tLZTeamData[AiBotMap.subrefLZbCoreBase]) and tLZTeamData[AiBotMap.subrefMexCountByTech][3] == 0 and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] == 0 and AiBotMap.iMapSize >= 512 and AiBotMap.iMapSize <= 1024 and iCurIsland == NavUtils.GetLabel(AiBotMap.refPathingTypeLand, tLZTeamData[AiBotMap.reftClosestFriendlyBase]) and AiBotTeam.tLandSubteamData[aiBrain.AiBotLandSubteam][AiBotTeam.refiEnemyMobileDFThreatNearOurSide] * 1.25 < AiBotTeam.tLandSubteamData[aiBrain.AiBotLandSubteam][AiBotTeam.refiAllyMobileDFThreatNearOurSide] and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbFocusOnT1Spam]) then
            --Are we a 'high mex in safe position' map like astro? If so then want to prioritise eco over land units
            local tBaseLZData, tBaseLZTeamData = AiBotMap.GetLandOrWaterZoneData(tLZTeamData[AiBotMap.reftClosestFriendlyBase], true, iTeam)
            if bDebugMessages == true then LOG(sFunctionRef..': If majority of mexes are in our nearest base then reduce factories wanted, tBaseLZData[AiBotMap.subrefLZOrWZMexCount]='..tBaseLZData[AiBotMap.subrefLZOrWZMexCount]..'; subrefPlateauTotalMexCount='..AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauTotalMexCount]..'; subrefMexCountByTech][3]='..tBaseLZTeamData[AiBotMap.subrefMexCountByTech][3]) end
            if tBaseLZTeamData and tBaseLZData[AiBotMap.subrefLZOrWZMexCount] >= 6 and tBaseLZData[AiBotMap.subrefLZOrWZMexCount] > AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauTotalMexCount] * (0.3 / AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]) and tBaseLZTeamData[AiBotMap.subrefMexCountByTech][3] < 2 then
                if bDebugMessages == true then LOG(sFunctionRef..': Will reduce the number of factories wanted') end
                for iTech, iValue in tiGrossMassWantedPerFactoryByTech do
                    if aiBrain[AiBotOverseer.refbPrioritiseNavy] or aiBrain[AiBotOverseer.refbPrioritiseHighTech] or aiBrain[AiBotOverseer.refbPrioritiseDefence] then
                        tiGrossMassWantedPerFactoryByTech[iTech] = iValue * 4
                    elseif not(AiBotUtilities.bQuietModActive) or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass] or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyLandFactoryTech] >= 3 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] <= 0.02) then
                        tiGrossMassWantedPerFactoryByTech[iTech] = iValue * 2
                    else
                        tiGrossMassWantedPerFactoryByTech[iTech] = iValue * 1.5
                    end
                end
            end
        end
    end
    local iTeamCount = AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]
    if iTeamCount > 1 then
        for iEntry, iFactoryCountWanted in tiGrossMassWantedPerFactoryByTech do
            tiGrossMassWantedPerFactoryByTech[iEntry] = iFactoryCountWanted * iTeamCount
        end
    end
    --If we have navy then reduce the mass wanted
    if (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyNavalFactoryTech] >= 1 or AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] > 0) and not(aiBrain[AiBotOverseer.refbPrioritiseAir]) and not(aiBrain[AiBotOverseer.refbPrioritiseLowTech]) then
        local iReductionFactor = 0.75
        if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyNavalFactoryTech] >= 2 then iReductionFactor = 0.5 end
        if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyNavalFactoryTech] >= 1 and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] > 0 then
            iReductionFactor = math.min(0.5, iReductionFactor * 0.8)
        end
        for iEntry, iFactoryCountWanted in tiGrossMassWantedPerFactoryByTech do
            tiGrossMassWantedPerFactoryByTech[iEntry] = iFactoryCountWanted * iReductionFactor
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': Finished updating gross mass wanted per average facotry count, tiGrossMassWantedPerFactoryByTech='..repru(tiGrossMassWantedPerFactoryByTech)..'; refbBaseInSafePosition='..tostring((tLZTeamData[AiBotMap.refbBaseInSafePosition] or false))) end
    local iAverageCurAirAndLandFactories = (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTotalFactoryCountByType][AiBotFactory.refiFactoryTypeLand] or 0) / AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] + (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTotalFactoryCountByType][AiBotFactory.refiFactoryTypeAir] or 0) / AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]
    local iFactoriesInZone --will change value from nil if needed
    local iAirFacsInZone --will change value from nil if needed
    local iLandFacsInZone
    local bWantMoreFactories = false
    local bDontWantDueToUnitCap = false
    local bCanBuildAirFac = true
    --Are air facs restricted?
    if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech] == 0 then
        bCanBuildAirFac = false
        if not(aiBrain.GetFactionIndex) then aiBrain = AiBotTeam.GetFirstActiveAiBotBrain(iTeam) end
        local tsAirFacs = EntityCategoryGetUnitList(AiBotUnitInfo.refCategoryAirFactory * categories.TECH1 * AiBotUnitInfo.ConvertFactionToCategory(aiBrain:GetFactionIndex()))
        if AiBotUtilities.IsTableEmpty(tsAirFacs) == false then
            for iAirFac, sAirFac in tsAirFacs do
                if not(AiBotUnitInfo.IsUnitRestricted(sAirFac)) then
                    bCanBuildAirFac = true
                    break
                end
            end
        end
    end


    --Unit cap - want max of 2 factories in the core LZ and no more factories in non-core LZs
    if AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeLastNearUnitCap] then
        if not(tLZTeamData[AiBotMap.subrefLZbCoreBase]) then
            --Dont wnat more factories (no change to default)
            bDontWantDueToUnitCap = true
        else
            local tFactoriesInZone
            if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then
                tFactoriesInZone = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryFactory, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                if AiBotUtilities.IsTableEmpty(tFactoriesInZone) == false then
                    if not(iFactoriesInZone) then iFactoriesInZone = table.getn(tFactoriesInZone) end
                    if iFactoriesInZone >= 5 then
                        bDontWantDueToUnitCap = true
                    elseif iFactoriesInZone >= 2 then
                        if not(iAirFacsInZone) or not(iLandFacsInZone) then
                            iAirFacsInZone = 0
                            iLandFacsInZone = 0
                            for iFactory, oFactory in tFactoriesInZone do
                                if oFactory:GetFractionComplete() == 1 then
                                    if EntityCategoryContains(AiBotUnitInfo.refCategoryLandFactory, oFactory.UnitId) then iLandFacsInZone = iLandFacsInZone + 1
                                    elseif EntityCategoryContains(AiBotUnitInfo.refCategoryAirFactory, oFactory.UnitId) then iAirFacsInZone = iAirFacsInZone + 1
                                    end

                                end
                            end
                        end
                        if (iAirFacsInZone > 0 or not(bCanBuildAirFac)) and iLandFacsInZone > 0 then bDontWantDueToUnitCap = true end

                    end
                end
            end
        end
    end

    if bDebugMessages == true then LOG(sFunctionRef..': Finished checking if close to unit cap, bDontWantDueToUnitCap='..tostring(bDontWantDueToUnitCap)..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeLastNearUnitCap]='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeLastNearUnitCap] or 'nil')..'; iAverageCurAirAndLandFactories='..iAverageCurAirAndLandFactories..'; iPlateau='..iPlateau..'; iLandZone='..iLandZone..'; Mass stored='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored]) end

    --Norush or eco slot at T2 and lower when arent overflowing mass
    if (AiBotOverseer.bNoRushActive and AiBotOverseer.iNoRushTimer - GetGameTimeSeconds() >= 30) or (tLZTeamData[AiBotMap.refbBaseInSafePosition] and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech] < 3 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] <= 0.7) then
        --Only want more factories if we dont have 1 land and 1 air in this LZ
        if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) then
            bWantMoreFactories = true
            if bDebugMessages == true then LOG(sFunctionRef..': No units in the zone so want more factories') end
        else
            if not(iLandFacsInZone) or not(iAirFacsInZone) then
                iLandFacsInZone = 0
                iAirFacsInZone = 0
                if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then
                    local tFriendlyFactory = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryFactory, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                    if AiBotUtilities.IsTableEmpty(tFriendlyFactory) == false then
                        for iUnit, oUnit in tFriendlyFactory do
                            if EntityCategoryContains(AiBotUnitInfo.refCategoryLandFactory, oUnit.UnitId) then
                                iLandFacsInZone = iLandFacsInZone + 1
                            else
                                iAirFacsInZone = iAirFacsInZone + 1
                            end
                        end
                    end
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': NoRush: iLandFacsInZone='..iLandFacsInZone..'; iAirFacsInZone='..iAirFacsInZone..'; Do we want air fac instead of land fac='..tostring(DoWeWantAirFactoryInsteadOfLandFactory(iTeam, tLZData, tLZTeamData))) end
            if iLandFacsInZone > 0 and (iAirFacsInZone > 0 or not(bCanBuildAirFac) or not(DoWeWantAirFactoryInsteadOfLandFactory(iTeam, tLZData, tLZTeamData))) then
                --Dont want more factories
                bWantMoreFactories = false --redundancy
            else
                bWantMoreFactories = true
            end
        end
    else
        if bDebugMessages == true then LOG(sFunctionRef..': Checking if want more factories at gamttime '..GetGameTimeSeconds()..' for iTeam='..iTeam..'; iPlateau='..(iPlateau or 'nil')..'; iLandZone='..(iLandZone or 'nil')..'; Mass % stored='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] or 'nil')..'; Land fac count='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTotalFactoryCountByType][AiBotFactory.refiFactoryTypeLand] or 'nil')..'; Gross mass count='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] or 'nil')..'; Highest factory tech='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] or 'nil')..'; iAverageCurAirAndLandFactories='..(iAverageCurAirAndLandFactories or 'nil')..'; Factories wanted based on gross mass='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] or 0) / (tiGrossMassWantedPerFactoryByTech[AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]] or 0)..'; iCurIsland='..(iCurIsland or 0)..'; iEnemyIsland='..(iEnemyIsland or 0)..'; Time since air fac last failed to have osmething to build='..(GetGameTimeSeconds() - (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeLastHadNothingToBuildForAirFactory] or -100))..'; Time since land fac last failed to have something to build='..(GetGameTimeSeconds() - (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeLastHadNothingToBuildForLandFactory] or -100))) end
        if not(bWantMoreFactories) and not(bDontWantDueToUnitCap) then
            --Failure to build at both land and air facs and have a significant number of factories already (at least 5)
            if (iAverageCurAirAndLandFactories >= 5 or (iAverageCurAirAndLandFactories >= 2.5 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] >= 2 and iAverageCurAirAndLandFactories * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] >= 8)) and GetGameTimeSeconds() - (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeLastHadNothingToBuildForAirFactory] or -100) <= 10 and GetGameTimeSeconds() - (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeLastHadNothingToBuildForLandFactory] or -100) <= 10 and GetGameTimeSeconds() - (tLZTeamData[AiBotMap.subrefiTimeLandFacHadNothingToBuild] or -100) <= 10 then
                --Dont want more factories unless we want an air fac, have T3 air, and arent mass stalling, and are building air units
                if bDebugMessages == true then LOG(sFunctionRef..': Have high average number of factories so dont want more') end
                --Stalling E and have factory in zone - dont want more factories early game
            elseif AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy] and iAverageCurAirAndLandFactories >= 1 and (iAverageCurAirAndLandFactories >= 2 or not(tLZTeamData[AiBotMap.subrefLZbCoreBase])) and (not(AiBotUtilities.bQuietModActive) or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored] < 0.3) then
                if bDebugMessages == true then LOG(sFunctionRef..': Stalling E so dont want more factories at the moment as already have at least one') end
            else
                --If core base then make sure we have an air fac
                if tLZTeamData[AiBotMap.subrefLZbCoreBase] and bCanBuildAirFac and tLZTeamData[AiBotMap.subrefMexCountByTech][2] + tLZTeamData[AiBotMap.subrefMexCountByTech][3] > 2 and not(iAirFacsInZone) and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass]) and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then
                    iAirFacsInZone = 0
                    iLandFacsInZone = 0
                    local tFactoriesInZone = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryFactory, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                    if AiBotUtilities.IsTableEmpty(tFactoriesInZone) == false then
                        for iFactory, oFactory in tFactoriesInZone do
                            if oFactory:GetFractionComplete() == 1 then
                                if EntityCategoryContains(AiBotUnitInfo.refCategoryLandFactory, oFactory.UnitId) then iLandFacsInZone = iLandFacsInZone + 1
                                elseif EntityCategoryContains(AiBotUnitInfo.refCategoryAirFactory, oFactory.UnitId) then iAirFacsInZone = iAirFacsInZone + 1
                                end
                            end
                        end
                    end
                end
                if (iAirFacsInZone > 0 or not(bCanBuildAirFac)) and iLandFacsInZone > 0 then bDontWantDueToUnitCap = true end

                --Have we failed to build something at existing land and air factories recently?
                if bDebugMessages == true then LOG(sFunctionRef..': AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat]..'; iAverageCurAirAndLandFactories='..iAverageCurAirAndLandFactories..'; Map size='..(AiBotMap.iMapSize or 'nil')..'; % Stored='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] or 'nil')..'; AIx team highest build mult='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.refiHighestBrainBuildMultiplier] or 'nil')..'; Gross mass='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] or 'nil')..'; Time of last stall='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeOfLastMassStall] or 'nil')..'; Highest air fac tech='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech] or 'nil')..'; Mex count by tech='..repru(tLZTeamData[AiBotMap.subrefMexCountByTech])..'; Time of last energy stall='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeOfLastEnergyStall] or 'nil')..'; Team has air control='..tostring(TeamHasAirControl(iTeam))..'; iAirFacsInZone (if calculated)='..(iAirFacsInZone or 'nil')..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass]='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass] or false)) end
                if (iAirFacsInZone == 0 and tLZTeamData[AiBotMap.subrefLZbCoreBase]) or (tLZTeamData[AiBotMap.refbBaseInSafePosition] and iAirFacsInZone < tLZTeamData[AiBotMap.subrefMexCountByTech][3] + 1) and DoWeWantAirFactoryInsteadOfLandFactory(iTeam, tLZData, tLZTeamData) then
                    if bDebugMessages == true then LOG(sFunctionRef..': we have a core base with no air fac (or safe zone with no more air facs than t3 mexes so want to build more facs') end
                    bWantMoreFactories = true
                elseif iAverageCurAirAndLandFactories >= 2 and ((GetGameTimeSeconds() - (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeLastHadNothingToBuildForLandFactory] or -100)) <= 10 and (TeamHasLowMass(iTeam) or GetGameTimeSeconds() - (tLZTeamData[AiBotMap.subrefiTimeLandFacHadNothingToBuild] or -100) <= 10)) and ((GetGameTimeSeconds() - (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeLastHadNothingToBuildForAirFactory] or -100)) <= 10 or not(DoWeWantAirFactoryInsteadOfLandFactory(iTeam, tLZData, tLZTeamData))) then
                    --Dont want more factories
                    if bDebugMessages == true then LOG(sFunctionRef..': Failed ot build anythign at land factory recently, and either failed to build at air factory or want land fac instead of air fac') end
                    --Lots of facs and are stalling
                elseif iAverageCurAirAndLandFactories >= 4 and ((AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored] <= 50 and not(bIgnoreMainEcoConditions)) or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass] and (not(bIgnoreMainEcoConditions) or iAverageCurAirAndLandFactories * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] >= AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] / 4))) then
                    if bDebugMessages == true then LOG(sFunctionRef..': Have too little mass stored and atl east 4 factories per player so wont build more even if we lack air') end
                    --Reached experimental stage of game and have <20% mass stored
                elseif iAverageCurAirAndLandFactories >= 4 and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] >= 2 and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] <= 0.2 or TeamHasLowMass(iTeam)) and (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] >= 4 or AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDefendAgainstArti] or GetGameTimeSeconds() - (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeOfLastMassStall] or 0) <= 30) and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbBuiltParagon]) then
                    if bDebugMessages == true then LOG(sFunctionRef..': Dont get more factories than already have as have built several experimentals') end
                    --Teamgame with high number of factories
                elseif iTeamCount > 1 and iAverageCurAirAndLandFactories >= 3 and iAverageCurAirAndLandFactories * iTeamCount >= 10 and iAverageCurAirAndLandFactories >= (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] or 0) / (tiGrossMassWantedPerFactoryByTech[AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]] or 0) and TeamHasLowMass(iTeam) then
                    --Dont want more factories
                    if bDebugMessages == true then LOG(sFunctionRef..': Have lots of factories in teamgame and have low mass so dont want more') end
                    --More air fac if enemy or us has large air to ground threat and we dont have air control, and have good gross eco (regardless of current eco)
                elseif iAverageCurAirAndLandFactories <= math.max(AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat], AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurGunshipThreat] + AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurT1ToT3BomberThreat] + (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurExpBomberThreat] or 0)) * 0.003 / AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyAirTech] and AiBotMap.iMapSize >= 512 and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.1 or iAverageCurAirAndLandFactories * 2.25 * AiBotTeam.tTeamData[iTeam][AiBotTeam.refiHighestBrainBuildMultiplier] <= AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] - 3) and GetGameTimeSeconds() - (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeOfLastMassStall] or -100) >= 10 and (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] > 0 or AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat] >= 500 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyAirTech]) and not(TeamHasAirControl(iTeam)) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 6 and GetGameTimeSeconds() - (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeOfLastEnergyStall] or -100) >= 10 and (not(bCanBuildAirFac) or GetGameTimeSeconds() - (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeLastHadNothingToBuildForAirFactory] or -100) > 10) then
                    if bDebugMessages == true then LOG(sFunctionRef..': Enemy has large air to ground threat so want more factories (on the assumption we will end up getting more air factories) to deal with it') end
                    bWantMoreFactories = true
                elseif bCanBuildAirFac and
                        --If our next fac would be an air fac, and either: (first row) we are at T3 air without air control, and we have ok eco; or (second row) we dont have 2 air facs but want to build torp bombers (and we have t2 air), then get another
                        ((not(TeamHasAirControl(iTeam)) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech] >= 2 --Cond1
                                and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored] >= 333*AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech] --Cond2
                                or iAverageCurAirAndLandFactories < AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] / tiGrossMassWantedPerFactoryByTech[AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech]] --Cond3
                                or (iAirFacsInZone < 3 and tLZTeamData[AiBotMap.subrefLZbCoreBase] and AiBotMap.iMapSize >= 500 and iLandFacsInZone >= 3 and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass]) and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy]) --Cond4
                                and (aiBrain[AiBotEconomy.refiOurHighestAirFactoryTech] >= 3 or not(tLZTeamData[AiBotMap.refbBaseInSafePosition])) --Cond5
                                and (tLZTeamData[AiBotMap.subrefMexCountByTech][3] >= 2 or (tLZTeamData[AiBotMap.subrefMexCountByTech][2] + tLZTeamData[AiBotMap.subrefMexCountByTech][3] >= 4 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech] >= 2))))) --Cond6
                                or (aiBrain[AiBotEconomy.refiOurHighestAirFactoryTech] >= 2 and AiBotTeam.tAirSubteamData[aiBrain.AiBotAirSubteam][AiBotTeam.refbNoAvailableTorpsForEnemies] and (iAirFacsInZone or 2) < 2 and aiBrain[AiBotEconomy.refiGrossMassBaseIncome] >= 6 and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass]) and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy]))) --Cond7
                        and DoWeWantAirFactoryInsteadOfLandFactory(iTeam, tLZData, tLZTeamData) then --Cond8
                    bWantMoreFactories = true
                    if bDebugMessages == true then LOG(sFunctionRef..': Want another air fac') end
                elseif bCanBuildAirFac and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTotalFactoryCountByType][AiBotFactory.refiFactoryTypeAir] or 0) / AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] < 1 and GetGameTimeSeconds() - (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeLastHadNothingToBuildForAirFactory] or -100) > 10  and (AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) or AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(AiBotUnitInfo.refCategoryAirFactory, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]))) then
                    --Fewer than 1 air fac per player; if have no air facs in this zone then get more factories
                    bWantMoreFactories = true
                elseif iAverageCurAirAndLandFactories >= 3 and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] >= 1 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] <= 0.4 and ( AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] <= 0.05 or not(DoWeWantAirFactoryInsteadOfLandFactory(iTeam, tLZData, tLZTeamData))) then
                    if bDebugMessages == true then LOG(sFunctionRef..': We have constructed at least 1 experimental and arent about to overflow mass so wont get any more factories') end
                elseif AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored] >= 250 and ZoneWantsT1Spam(tLZTeamData, iTeam) then
                    if bDebugMessages == true then LOG(sFunctionRef..': In t1 spam mode with at least 250 mass stored so want more factories') end
                    bWantMoreFactories = true
                elseif (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.6 and GetGameTimeSeconds() - (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeOfLastMassStall] or -120) >= 120 and GetGameTimeSeconds() - (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeOfLastEnergyStall] or -120) >= 120 and (GetGameTimeSeconds() >= 300 or GetGameTimeSeconds() >= 300 / AiBotTeam.tTeamData[iTeam][AiBotTeam.refiHighestBrainBuildMultiplier]))
                        or ((iCurIsland == iEnemyIsland or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech] >= 3 or iAverageCurAirAndLandFactories <= (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] or 0) / (tiGrossMassWantedPerFactoryByTech[AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]] or 0))
                        and     (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.05
                        or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.01 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] == 1 and AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftTeamUpgradingMexes]) == false and table.getn(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftTeamUpgradingMexes]) >= 3))
                        and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.4 or (iAverageCurAirAndLandFactories <= math.max(4 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount], AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] / tiGrossMassWantedPerFactoryByTech[AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]])) or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] == 1 and GetGameTimeSeconds() <= 600))) then
                    --If enemy has a firebase then dont want more factories if dont have lots of mass
                    if not(WantToEcoDueToEnemyFirebase(iTeam, tLZTeamData, iPlateau)) then
                        --Do we have the energy to support another factory?
                        if bDebugMessages == true then LOG(sFunctionRef..': iAverageCurAirAndLandFactories='..iAverageCurAirAndLandFactories..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech]..'; Playable area iMapSize='..AiBotMap.iMapSize..' Team mass stored='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored]) end

                        --Small map specific - want loads of land factories
                        if AiBotMap.iMapSize <= 256 and iAverageCurAirAndLandFactories <= AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] / tiGrossMassWantedPerFactoryByTech[AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]] and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored] >= 30 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetMass] > 0) then
                            bWantMoreFactories = true
                            if bDebugMessages == true then LOG(sFunctionRef..': Small map and we dont have all the factories we want for gross mass so want more') end

                        elseif iAverageCurAirAndLandFactories >= 2 and not(bIgnoreMainEcoConditions) and iCurIsland == iEnemyIsland and ((AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTotalFactoryCountByType][AiBotFactory.refiFactoryTypeAir] or 0) > 0 and HaveLowPower(iTeam)) and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] <= 0.6 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored] <= 0.5 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetEnergy] < 1) and (not(AiBotUtilities.bQuietModActive) or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored] <= 0.2 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetEnergy] <= -10) then
                            --Dont want more factories
                            if bDebugMessages == true then LOG(sFunctionRef..': Have low power so dont want more factories') end

                            --Cap on no. of factories on larger maps
                        elseif iAverageCurAirAndLandFactories >= 4 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech] < 3 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech] > 0 and AiBotMap.iMapSize > 256 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored] < 8000 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] <= math.min(0.75, 0.25 + 0.05 * iAverageCurAirAndLandFactories) and (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] > 0 or AiBotTeam.iPlayersAtGameStart >= 5 or iAverageCurAirAndLandFactories >= 10 or iAverageCurAirAndLandFactories * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] >= AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] * 1.2 or (not(bIgnoreMainEcoConditions) and TeamHasLowMass(iTeam))) then --1 t3 land fac is 2.4 mass per tick; if want to allow 50% of mass going on land/air, then means want 5 gross mass income per fac
                            --Dont want more factories
                            if bDebugMessages == true then LOG(sFunctionRef..': Cap on number of factories for larger maps, AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount]..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass]..'; iAverageCurAirAndLandFactories='..iAverageCurAirAndLandFactories..'; subrefiHighestFriendlyFactoryTech='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]..'; TeamHasLowMass='..tostring(TeamHasLowMass(iTeam))) end
                        elseif iAverageCurAirAndLandFactories < 2 and (iAverageCurAirAndLandFactories * 0.8 < AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored] >= 200) then
                            if bDebugMessages == true then LOG(sFunctionRef..': We have equiv of 3 mexes per player or 200 mass stored so want at least 2 factories') end
                            bWantMoreFactories = true
                            --If we dont have at least 25% mass stored, do we have an enemy in the same plateau as us who is within 350 land travel distance (225 if cant path by land), and we dont have loads of factories?
                        elseif (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] < 0.25 and not(bIgnoreMainEcoConditions)) or (iAverageCurAirAndLandFactories == 1 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] < 0.4 and GetGameTimeSeconds() <= 300) then
                            if bDebugMessages == true then LOG(sFunctionRef..': Net mass='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetMass] or 'nil')..'; Brain net mass='..(aiBrain[AiBotEconomy.refiNetMassBaseIncome] or 'nil')..'; brain mass stored='..aiBrain:GetEconomyStored('MASS')..'; iAverageCurAirAndLandFactories='..(iAverageCurAirAndLandFactories or 'nil')..'; refiOurHighestFactoryTechLevel='..(aiBrain[AiBotEconomy.refiOurHighestFactoryTechLevel] or 'nil')..'; aiBrain='..(aiBrain.Nickname or 'nil')..'; tLZTeamData[AiBotMap.reftiClosestFriendlyAiBotBrainIndex]='..(tLZTeamData[AiBotMap.reftiClosestFriendlyAiBotBrainIndex] or 'nil')) end
                            if bIgnoreMainEcoConditions or iAverageCurAirAndLandFactories < 6 - aiBrain[AiBotEconomy.refiOurHighestFactoryTechLevel] or (aiBrain[AiBotEconomy.refiNetMassBaseIncome] > 0 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetMass] > 0 and aiBrain:GetEconomyStored('MASS') >= 50) or (iAverageCurAirAndLandFactories < 8 and aiBrain[AiBotEconomy.refiOurHighestFactoryTechLevel] == 1 and AiBotTeam.tTeamData[iTeam][AiBotTeam.refbFocusOnT1Spam] and aiBrain:GetEconomyStored('MASS') >= 150 and (aiBrain:GetEconomyStored('MASS') >= 220 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetMass] > -0.5)) then
                                --Just get nearest enemy base
                                local iStartPlateau, iStartLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(tLZTeamData[AiBotMap.reftClosestEnemyBase])
                                if iStartPlateau == iPlateau and iStartLandZone > 0 then
                                    local iTravelDist = (AiBotMap.GetTravelDistanceBetweenLandZones(iPlateau, iLandZone, iStartLandZone) or 10000)
                                    if iTravelDist <= 350 and (iTravelDist <= 225 or NavUtils.GetLabel(AiBotMap.refPathingTypeLand, tLZTeamData[AiBotMap.reftClosestEnemyBase]) == tLZData[AiBotMap.subrefLZIslandRef]) then
                                        bWantMoreFactories = true
                                    end
                                    if bDebugMessages == true then LOG(sFunctionRef..': iTravelDist='..iTravelDist..'; This island='..(tLZData[AiBotMap.subrefLZIslandRef] or 'nil')..'; Closest enemy base island='..(NavUtils.GetLabel(AiBotMap.refPathingTypeLand, tLZTeamData[AiBotMap.reftClosestEnemyBase]) or 'nil')..'; bWantMoreFactories following distance based condition='..tostring(bWantMoreFactories)) end
                                end
                                if bDebugMessages == true then LOG(sFunctionRef..': Finished checking if have enemy within 350 of us, bWantMoreFactories after this check='..tostring(bWantMoreFactories)) end
                            end
                            --Can only path to enemy with navy, and we lack T3 air, and have <50% mass stored - then dont get more facs at core base
                        elseif AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech] < 3 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] < 0.5 and not(iCurIsland == iEnemyIsland) and tLZTeamData[AiBotMap.subrefLZbCoreBase] and (iAverageCurAirAndLandFactories >= 3 or not(DoWeWantAirFactoryInsteadOfLandFactory(iTeam, tLZData, tLZTeamData))) then
                            if bDebugMessages == true then LOG(sFunctionRef..': No more facs at core base as not at risk of overflowing and want to consderve resources for navy') end
                        else
                            if bDebugMessages == true then LOG(sFunctionRef..': Want more factories general') end
                            bWantMoreFactories = true
                        end
                    else
                        if bDebugMessages == true then LOG(sFunctionRef..': We dont have enough eco to justify more factories due to enemy firebase, bIgnoreMainEcoConditions='..tostring(bIgnoreMainEcoConditions or false)) end
                        if bIgnoreMainEcoConditions then bWantMoreFactories = true end
                    end
                elseif iAirFacsInZone <= 1 and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass]) and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy]) and AiBotUtilities.IsTableEmpty(AiBotTeam.tAirSubteamData[ArmyBrains[tLZTeamData[AiBotMap.reftiClosestFriendlyAiBotBrainIndex]].AiBotAirSubteam][AiBotTeam.reftPriorityUnitsWantingAirScout]) == false and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 6 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] and tLZTeamData[AiBotMap.subrefMexCountByTech][2] + tLZTeamData[AiBotMap.subrefMexCountByTech][3] >= 2 and DoWeWantAirFactoryInsteadOfLandFactory(iTeam, tLZData, tLZTeamData) then
                    if bDebugMessages == true then LOG(sFunctionRef..': Want a second air fac due to priority scouting targets') end
                else
                    if bDebugMessages == true then LOG(sFunctionRef..': We dont have enough eco to justify more factories, bIgnoreMainEcoConditions='..tostring(bIgnoreMainEcoConditions or false)..'; Later air fac COnd1='..tostring((AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.6 and GetGameTimeSeconds() - (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeOfLastMassStall] or -120) >= 120 and GetGameTimeSeconds() - (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeOfLastEnergyStall] or -120) >= 120 and (GetGameTimeSeconds() >= 300 or GetGameTimeSeconds() >= 300 / AiBotTeam.tTeamData[iTeam][AiBotTeam.refiHighestBrainBuildMultiplier])))..'; Cond 2a='..tostring((iCurIsland == iEnemyIsland or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech] >= 3 or iAverageCurAirAndLandFactories <= (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] or 0) / (tiGrossMassWantedPerFactoryByTech[AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]] or 0)))..'; Cond2b='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.05)..'; Cond2c='..tostring((AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.01 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] == 1 and AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftTeamUpgradingMexes]) == false and table.getn(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftTeamUpgradingMexes]) >= 3))..'; Cond 2d='..tostring((AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.4 or (iAverageCurAirAndLandFactories <= math.max(4 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount], AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] / tiGrossMassWantedPerFactoryByTech[AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]])) or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] == 1 and GetGameTimeSeconds() <= 600)))..'; Behind on air Main Cond1='..tostring((not(TeamHasAirControl(iTeam)) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech] >= 2))..'; Cond2='..tostring((AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored] >= 333*AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech]))..'; Cond3='..tostring(iAverageCurAirAndLandFactories < AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] / tiGrossMassWantedPerFactoryByTech[AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech]])..'; Cond4='..tostring((iAirFacsInZone < 3 and tLZTeamData[AiBotMap.subrefLZbCoreBase] and AiBotMap.iMapSize >= 500 and iLandFacsInZone >= 3 and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass]) and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy])))..'; Cond5='..tostring((aiBrain[AiBotEconomy.refiOurHighestAirFactoryTech] >= 3 or not(tLZTeamData[AiBotMap.refbBaseInSafePosition])))..'; Cond6='..tostring((tLZTeamData[AiBotMap.subrefMexCountByTech][3] >= 2 or (tLZTeamData[AiBotMap.subrefMexCountByTech][2] + tLZTeamData[AiBotMap.subrefMexCountByTech][3] >= 4 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech] >= 2)))..'; Cond7='..tostring((aiBrain[AiBotEconomy.refiOurHighestAirFactoryTech] >= 2 and AiBotTeam.tAirSubteamData[aiBrain.AiBotAirSubteam][AiBotTeam.refbNoAvailableTorpsForEnemies] and (iAirFacsInZone or 2) < 2 and aiBrain[AiBotEconomy.refiGrossMassBaseIncome] >= 6 and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass]) and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy])))..'; Cond8='..tostring(DoWeWantAirFactoryInsteadOfLandFactory(iTeam, tLZData, tLZTeamData))..'; TeamHasAirControl(iTeam)='..tostring(TeamHasAirControl(iTeam))..'; subrefiHighestFriendlyAirFactoryTech='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech]) end
                    if bIgnoreMainEcoConditions then bWantMoreFactories = true end
                end
            end
        end
    end
    --Exception - get more factories if base level of mass income per brain
    if not(bWantMoreFactories) and not(bDontWantDueToUnitCap) and iAverageCurAirAndLandFactories == 1 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 2 then
        if bDebugMessages == true then LOG(sFunctionRef..': We have at least 20 mass per sec so want to have more than 1 factory') end
        bWantMoreFactories = true
    end

    --decent eco and air fac count is < 1 on average in teamgame (ie want every player to consider getting air fac) and dealing with core base
    if not(bWantMoreFactories) and iTeamCount > 1 and bCanBuildAirFac and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 8 * iTeamCount and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech] >= 3 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyLandFactoryTech] >= 3) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 100 and tLZTeamData[AiBotMap.subrefLZbCoreBase] and not(HaveLowPower(iTeam)) then
        if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then
            local tAirFacs = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryAirFactory, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
            if AiBotUtilities.IsTableEmpty(tAirFacs) then

                bWantMoreFactories = true
                if bDebugMessages == true then LOG(sFunctionRef..': Want to build more land factories as have no air fac in this zone, bCanBuildAirFac='..tostring(bCanBuildAirFac or false)) end
            end
        end
    end
    if bWantMoreFactories then
        --Double-check - if we would want an air fac, and already have one, and arent at T2 air yet, then dont get more factories unless we have at least 40% stored mass and 99% energy
        if iAverageCurAirAndLandFactories >= 2 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech] == 1 and DoWeWantAirFactoryInsteadOfLandFactory(iTeam, tLZData, tLZTeamData) then
            local iAirFacsInLZ = 0
            if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then
                local tFriendlyAirFac = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryAirFactory, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                if AiBotUtilities.IsTableEmpty(tFriendlyAirFac) == false then
                    for iAirFac, oAirFac in tFriendlyAirFac do
                        if AiBotUnitInfo.IsUnitValid(oAirFac) and oAirFac:GetFractionComplete() == 1 then
                            iAirFacsInLZ = iAirFacsInLZ + 1
                        end
                    end
                end
            end
            if iAirFacsInLZ >= 1 and (iAirFacsInLZ >= 4 or AiBotTeam.tTeamData[aiBrain.AiBotAirSubteam][AiBotTeam.refbHaveAirControl]) and (iAirFacsInLZ >= 3 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] <= 0.4 or ((iAirFacsInLZ >= 2 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] <= 0.55) or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored] <= 0.9)) then
                bWantMoreFactories = false
                if bDebugMessages == true then LOG(sFunctionRef..': We already have '..iAirFacsInLZ..' air fac and dont have t2 air yet, so will hold off getting more air facs') end
            end
        end
    end

    --More factories in cases where overflowing and have no T3 engineers or active upgrades (e.g. campaign missions with unit restrictions)
    if not(bWantMoreFactories) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.99 and tLZTeamData[AiBotMap.subrefLZbCoreBase] and iAverageCurAirAndLandFactories <= 15 and not(HaveLowPower(iTeam)) and ((AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLowestUnitCapAdjustmentLevel] or 100) >= 0 or (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLowestUnitCapAdjustmentLevel] >= -1 and iAverageCurAirAndLandFactories <= 5)) then
        bWantMoreFactories = true
        if bDebugMessages == true then LOG(sFunctionRef..': Overflowing mass with no t3 engineers so want to build more factories') end
    end

    --AI personality adjustments - get fewer factories for certain AI types
    if bDebugMessages == true then LOG(sFunctionRef..': Considering personality adjustment if want more facs, bWantMoreFactories='..tostring(bWantMoreFactories)..'; Highest air='..aiBrain[AiBotEconomy.refiOurHighestAirFactoryTech]..'; Land='..aiBrain[AiBotEconomy.refiOurHighestLandFactoryTech]..'; Prioritise tech='..tostring(aiBrain[AiBotOverseer.refbPrioritiseHighTech] or false)..'; Prioritise defence='..tostring(aiBrain[AiBotOverseer.refbPrioritiseDefence] or false)..'; Prioritise navy='..tostring(aiBrain[AiBotOverseer.refbPrioritiseNavy] or false)) end
    if bWantMoreFactories and aiBrain[AiBotEconomy.refiOurHighestAirFactoryTech] > 0 and aiBrain[AiBotEconomy.refiOurHighestLandFactoryTech] > 0 then
        --Tech and turtle, and navy (except for water zones, but i think this condition is only used for land zones) - dont want as many
        if aiBrain[AiBotOverseer.refbPrioritiseHighTech] or aiBrain[AiBotOverseer.refbPrioritiseDefence] or aiBrain[AiBotOverseer.refbPrioritiseNavy] then
            --Only get more if have lots of mass
            if bDebugMessages == true then LOG(sFunctionRef..': Mass %='..aiBrain:GetEconomyStoredRatio('MASS')..'; Net income='..aiBrain[AiBotEconomy.refiNetMassBaseIncome]..'; Highest fac tech='..aiBrain[AiBotEconomy.refiOurHighestFactoryTechLevel]..'; Naval fac tech='..aiBrain[AiBotEconomy.refiOurHighestNavalFactoryTech]..'; Team net mass='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetMass]..'; Energy % stored='..aiBrain:GetEconomyStoredRatio('ENERGY')..'; Have low power='..tostring(HaveLowPower(iTeam))) end
            if not(iLandFacsInZone) or not(iAirFacsInZone) then
                iLandFacsInZone = 0
                iAirFacsInZone = 0
                if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then
                    local tFriendlyFactory = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryFactory, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                    if AiBotUtilities.IsTableEmpty(tFriendlyFactory) == false then
                        for iUnit, oUnit in tFriendlyFactory do
                            if EntityCategoryContains(AiBotUnitInfo.refCategoryLandFactory, oUnit.UnitId) then
                                iLandFacsInZone = iLandFacsInZone + 1
                            else
                                iAirFacsInZone = iAirFacsInZone + 1
                            end
                        end
                    end
                end
            end
            --If only 1 air fac in core zone and lack torp bombers, then get a second air fac
            local bDecided = false
            if bDebugMessages == true then LOG(sFunctionRef..': Considering if we want 2 air facs due to enemy torp bombers despite personality, iAirFacsInZone='..iAirFacsInZone..'; No avialable torps='..tostring(AiBotTeam.tAirSubteamData[aiBrain.AiBotAirSubteam][AiBotTeam.refbNoAvailableTorpsForEnemies])..'; Do we want air instead of land='..tostring(DoWeWantAirFactoryInsteadOfLandFactory(iTeam, tLZData, tLZTeamData))) end
            if iAirFacsInZone <= 1 and AiBotTeam.tAirSubteamData[aiBrain.AiBotAirSubteam][AiBotTeam.refbNoAvailableTorpsForEnemies] and DoWeWantAirFactoryInsteadOfLandFactory(iTeam, tLZData, tLZTeamData)  then
                if bDebugMessages == true then LOG(sFunctionRef..': Want another air fac due to needing torp bombers and wanting an air fac as our next factory') end
                bDecided = true
                bWantMoreFactories = true
            elseif iLandFacsInZone + iAirFacsInZone > 0 and aiBrain:GetEconomyStoredRatio('MASS') < 0.2 or (aiBrain:GetEconomyStoredRatio('MASS') < 0.75 and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetMass]  < 0 or GetGameTimeSeconds() <= 600) and (aiBrain:GetEconomyStoredRatio('MASS') < 0.4 or (aiBrain:GetEconomyStoredRatio('ENERGY') <= 0.9 or HaveLowPower(iTeam)))) then
                if aiBrain[AiBotOverseer.refbPrioritiseDefence] or aiBrain[AiBotEconomy.refiOurHighestAirFactoryTech] < 3 or aiBrain[AiBotEconomy.refiOurHighestLandFactoryTech] < 3
                        --Naval facs - want to get more land/air facs if we have lost navy
                        or (aiBrain[AiBotOverseer.refbPrioritiseNavy] and iPlateau > 0 and (aiBrain[AiBotEconomy.refiOurHighestFactoryTechLevel] < 3 or aiBrain[AiBotEconomy.refiOurHighestNavalFactoryTech] > 0 or (GetGameTimeSeconds() <= 600 and GetLifetimeBuildCount(aiBrain, AiBotUnitInfo.refCategoryNavalFactory) == 0)))
                        or (iLandFacsInZone + iAirFacsInZone >= 3 and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] < 2)
                        then
                    if bDebugMessages == true then LOG(sFunctionRef..': Dont want more facs as want to tech or turtle, unless this zone has no factories') end
                    bWantMoreFactories = false
                    bDecided = true
                end
            end
            if not(bDecided) then
                if iLandFacsInZone + iAirFacsInZone == 0 then
                    bWantMoreFactories = true --i.e. revert back to previous conclusion
                elseif aiBrain:GetEconomyStoredRatio('MASS') > 0.2 then
                    if iLandFacsInZone == 0 or (iAirFacsInZone == 0 and tLZTeamData[AiBotMap.subrefLZbCoreBase]) then
                        bWantMoreFactories = true --i.e. revert back to previous conclusion
                        if bDebugMessages == true then LOG(sFunctionRef..': low fac Personality- no land or air fac in zone, and either core base or no land fac') end
                    elseif aiBrain[AiBotOverseer.refbPrioritiseHighTech] and aiBrain[AiBotEconomy.refiOurHighestAirFactoryTech] >= 3 and aiBrain[AiBotEconomy.refiOurHighestLandFactoryTech] >= 3 then
                        bWantMoreFactories = true --i.e. revert back to previous conclusion
                    elseif (aiBrain:GetEconomyStoredRatio('MASS') < 0.35 and aiBrain[AiBotEconomy.refiNetMassBaseIncome] < 0) then
                        if bDebugMessages == true then LOG(sFunctionRef..': low fac Personality-Dont want more facs as want to tech or turtle or get navy') end
                        bWantMoreFactories = false
                    elseif iLandFacsInZone + iAirFacsInZone <= 4 and (iLandFacsInZone + iAirFacsInZone <= 3 or (aiBrain:GetEconomyStoredRatio('MASS') >= 0.45 and ((tLZTeamData[AiBotMap.subrefiActiveMexUpgrades] or 0) > 0 or tLZTeamData[AiBotMap.subrefMexCountByTech][3] >= tLZData[AiBotMap.subrefLZOrWZMexCount] or aiBrain:GetEconomyStoredRatio('MASS') >= 0.6))) then
                        if bDebugMessages == true then LOG(sFunctionRef..': low fac Personality-Dont have that many facs and got quite a lot of mass so will get another fac') end
                        bWantMoreFactories = false
                    elseif tLZTeamData[AiBotMap.subrefMexCountByTech][3] + (tLZTeamData[AiBotMap.subrefiActiveMexUpgrades] or 0) >= tLZData[AiBotMap.subrefLZOrWZMexCount] and (aiBrain[AiBotEconomy.refiNetMassBaseIncome] > 0 or aiBrain:GetEconomyStoredRatio('MASS') >= 0.9) then
                        bWantMoreFactories = true
                        if bDebugMessages == true then LOG(sFunctionRef..': low fac Personality-we are upgrading every mex in this zone but still have good mass so want to build another factory') end
                    elseif aiBrain:GetEconomyStoredRatio('MASS') >= 0.95 and not(HaveLowPower(iTeam)) then
                        bWantMoreFactories = true
                        if bDebugMessages == true then LOG(sFunctionRef..': low fac Personality-Too much mass so want more factories') end
                    else
                        bWantMoreFactories = false
                        if bDebugMessages == true then LOG(sFunctionRef..': low fac Personality-Dont want more factories due to personality') end
                    end
                else
                    bWantMoreFactories = false
                    if bDebugMessages == true then LOG(sFunctionRef..': low fac Personality-Dont have lots of mass and personality doesnt want lots of factories') end
                end
            end
        end
    end

    --Override - if we dont have a HQ for the factory type then want to rebuild it
    if not(bWantMoreFactories) and ((AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech] == 0 and bCanBuildAirFac) or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyLandFactoryTech] == 0) then
        --Is it likely we have built and then lost the factory?
        if bCanBuildAirFac and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech] == 0 and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTotalFactoryCountByType][AiBotFactory.refiFactoryTypeAir] or 0) > 0 then
            if bDebugMessages == true then LOG(sFunctionRef..': Want to rebuild air factory as have no HQ') end
            bWantMoreFactories = true
        elseif AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyLandFactoryTech] == 0 and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTotalFactoryCountByType][AiBotFactory.refiFactoryTypeLand] or 0) > 0 then
            if bDebugMessages == true then LOG(sFunctionRef..': Want to rebuild land factory as have no HQ') end
            bWantMoreFactories = true
        end
    end

    -- A Dual Gap navy slot must commit its early mass to navy. The generic
    -- factory heuristics otherwise see a land zone with spare capacity and
    -- add another land/air factory before the naval HQ is ready.
    if aiBrain.AiBotDualGapPrimary == 'navy'
            and GetGameTimeSeconds() < (aiBrain.AiBotDualGapCommitmentEnd or 360)
            and iAverageCurAirAndLandFactories >= 1
            and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyNavalFactoryTech] < 2 then
        bWantMoreFactories = false
    end

    if bDebugMessages == true then LOG(sFunctionRef..': End of code, bWantMoreFactories='..tostring(bWantMoreFactories)) end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return bWantMoreFactories
end

function GetActiveMexUpgrades(tLZTeamData)
    local iActiveMexUpgrades = 0
    if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoActiveUpgrades]) == false then
        for iUpgrade, oUpgrade in tLZTeamData[AiBotMap.subreftoActiveUpgrades] do
            if EntityCategoryContains(AiBotUnitInfo.refCategoryMex, oUpgrade.UnitId) then iActiveMexUpgrades = iActiveMexUpgrades + 1 end
        end
    end
    return iActiveMexUpgrades
end

function CanUnitUseOvercharge(aiBrain, oUnit, tLZTeamDataIfACU)
    --For now checks if enough energy and not underwater and not fired in last 5s; separate function used as may want to expand this with rate of fire check in future
    local sFunctionRef = 'CanUnitUseOvercharge'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local bCanUseOC = false
    if oUnit and (oUnit[AiBotUnitInfo.refiDFRange] or 0) > 0 and not(oUnit[AiBotUnitInfo.refbDisableOvercharge]) then --and (oUnit[AiBotUnitInfo.refiFailedOCCount] or 0) < 2 then
        local oBP = oUnit:GetBlueprint()
        if oBP.Weapon and type(oBP.Weapon) == "table" then
            local iEnergyNeeded
            if GetGameTimeSeconds() - (oUnit[AiBotUnitInfo.refiTimeOfLastOverchargeShot] or -100) >= 5 then
                local bHaveOverchargeWeapon = false
                for iWeapon, oWeapon in oBP.Weapon do
                    if oWeapon.OverChargeWeapon then
                        bHaveOverchargeWeapon = true
                        if oWeapon.EnergyRequired then
                            iEnergyNeeded = oWeapon.EnergyRequired
                            break
                        end
                    end
                end

                if bHaveOverchargeWeapon then
                    if aiBrain:GetEconomyStored('ENERGY') >= (iEnergyNeeded or 7500) then bCanUseOC = true end
                    if bDebugMessages == true then LOG(sFunctionRef..': iEnergyNeeded='..iEnergyNeeded..'; aiBrain:GetEconomyStored='..aiBrain:GetEconomyStored('ENERGY')..'; bCanUseOC='..tostring(bCanUseOC)) end
                    if bCanUseOC == true then
                        --Check if underwater
                        local oUnitPosition = oUnit:GetPosition()
                        local iHeightAtWhichConsideredUnderwater = AiBotMap.IsUnderwater(oUnitPosition, true) + 0.25 --small margin of error
                        local tFiringPositionStart = AiBotLogic.GetDirectFireWeaponPosition(oUnit)
                        if tFiringPositionStart then
                            local iFiringHeight = tFiringPositionStart[2]
                            if iFiringHeight <= iHeightAtWhichConsideredUnderwater then
                                if bDebugMessages == true then LOG(sFunctionRef..': ACU is underwater; iFiringHeight='..iFiringHeight..'; iHeightAtWhichConsideredUnderwater='..iHeightAtWhichConsideredUnderwater) end
                                bCanUseOC = false
                            end
                        end
                    else
                        --Cant use overcharge due to lack of energy - do we want to flag as such for power stall purposes?
                        local iTeam = aiBrain.AiBotTeam
                        if bDebugMessages == true then LOG(sFunctionRef..': Team gross energy='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy]..'; Active AiBot brain count='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]..'; Economy stored ratio='..aiBrain:GetEconomyStoredRatio('ENERGY')..'; Mex E storage='..aiBrain[AiBotEconomy.refiMaxEnergyStorage]..'; iEnergyNeeded='..(iEnergyNeeded or 'nil')..'; Is tLZTeamDataIfACU nil='..tostring(tLZTeamDataIfACU == nil)) end
                        if tLZTeamDataIfACU and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 50 + 20 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] and aiBrain:GetEconomyStoredRatio('ENERGY') <= 0.9 and aiBrain[AiBotEconomy.refiMaxEnergyStorage] >= (iEnergyNeeded or 7500) and EntityCategoryContains(categories.COMMAND, oUnit.UnitId) then
                            --Is ACU in dangerous zone?
                            if tLZTeamDataIfACU[AiBotMap.subrefLZThreatEnemyMobileDFTotal] >= 400 and (tLZTeamDataIfACU[AiBotMap.subrefLZThreatEnemyMobileDFTotal] >= 1000 or AiBotUnitInfo.GetUnitHealthPercent(oUnit) <= 0.75) then
                                --Do we have dangerous enemies within our combat range that we could be overcharging?
                                local tNearbyEnemies = aiBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryLandCombat * categories.RECLAIMABLE, oUnit:GetPosition(), oUnit[AiBotUnitInfo.refiDFRange], 'Enemy')
                                if AiBotUtilities.IsTableEmpty(tNearbyEnemies) == false then
                                    --Need to get power asap
                                    AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeLastNeededEnergyForOvercharge] = GetGameTimeSeconds()
                                    if bDebugMessages == true then LOG(sFunctionRef..': Flagging we need power asap for overcharge') end
                                end
                            end
                        end
                    end
                elseif EntityCategoryContains(categories.COMMAND, oUnit.UnitId) then AiBotUtilities.ErrorHandler('Dealing with an ACU with ID '..oUnit.UnitId..' but dont think it has an overcharge weapon')
                end
            elseif bDebugMessages == true then LOG(sFunctionRef..': Has been less tahn 5s since last overcharged')
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return bCanUseOC
end

function WantToEcoDueToEnemyFirebase(iTeam, tLZTeamData, iPlateau)
    local bEnemyHasFirebaseAwayFromCoreLZ = false --true if enemy both has a firebase, and we dont have a firebase in range of this LZ or a core LZ
    if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyFirebaseByPlateauAndLZ][iPlateau]) == false then
        bEnemyHasFirebaseAwayFromCoreLZ = true
        for iFBLZ, tSubtable in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyFirebaseByPlateauAndLZ][iPlateau] do
            if tSubtable[AiBotTeam.subrefbInRangeOfCoreLZ] then bEnemyHasFirebaseAwayFromCoreLZ = false end
        end
        if bEnemyHasFirebaseAwayFromCoreLZ then
            --If we have any <T3 mexes in this LZ then eco
            if tLZTeamData[AiBotMap.subrefMexCountByTech][1] + tLZTeamData[AiBotMap.subrefMexCountByTech][2] > 0 then
                if TeamHasLowMass(iTeam) or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] < 0.4 then
                    return true
                end
            end
        end
    end
    return false
end

function HaveEnoughThreatToAttack(iPlateau, iLandZone, tLZData, tLZTeamData, iOurCombatThreat, iEnemyCombatThreat, iFirebaseThreatAdjust, bHaveSignificantCombatCloserToFirebase, iTeam, iOptionalOverrideDefaultThreatRatioWanted, bOptionalUseSlightlyLowerThreatRatio)
    local sFunctionRef = 'HaveEnoughThreatToAttack'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end



    local iDefaultThreatRatioWanted
    if iOptionalOverrideDefaultThreatRatioWanted then iDefaultThreatRatioWanted = iOptionalOverrideDefaultThreatRatioWanted
    elseif bOptionalUseSlightlyLowerThreatRatio then
        iDefaultThreatRatioWanted = 1.25
        if ArmyBrains[tLZTeamData[AiBotMap.reftiClosestFriendlyAiBotBrainIndex]][AiBotOverseer.refbPrioritiseLowTech] then iDefaultThreatRatioWanted = 1.15 end
    else
        iDefaultThreatRatioWanted = 1.4
        if ArmyBrains[tLZTeamData[AiBotMap.reftiClosestFriendlyAiBotBrainIndex]][AiBotOverseer.refbPrioritiseLowTech] then iDefaultThreatRatioWanted = 1.25 end
    end

    if bDebugMessages == true then LOG(sFunctionRef..': Deciding if have enough combat threat to attack, iOurCombatThreat='..iOurCombatThreat..'; iEnemyCombatThreat='..iEnemyCombatThreat..'; iFirebaseThreatAdjust='..iFirebaseThreatAdjust..'; bHaveSignificantCombatCloserToFirebase='..tostring(bHaveSignificantCombatCloserToFirebase)..'; iTeam='..(iTeam or 'nil')..'; LZ value='..tLZTeamData[AiBotMap.subrefLZTValue]..'; Map size='..AiBotMap.iMapSize..'; Time='..GetGameTimeSeconds()..'; subrefLZSValue='..tLZTeamData[AiBotMap.subrefLZSValue]..'; tLZTeamData[AiBotMap.refiModDistancePercent]='..tLZTeamData[AiBotMap.refiModDistancePercent]) end
    if iOurCombatThreat > iEnemyCombatThreat * iDefaultThreatRatioWanted then
        if bDebugMessages == true then LOG(sFunctionRef..': Have more than the default threat ratio wanted') end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        return true
    elseif  iOurCombatThreat > iEnemyCombatThreat and ((iFirebaseThreatAdjust > 0 and bHaveSignificantCombatCloserToFirebase) or (iOurCombatThreat > (iEnemyCombatThreat + iFirebaseThreatAdjust) * 0.9 and (tLZTeamData[AiBotMap.subrefLZTValue] > iOurCombatThreat * 0.5 or AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefAlliedACU]) == false)) or (AiBotMap.iMapSize <= 256 and tLZTeamData[AiBotMap.refiModDistancePercent] <= 0.55 and tLZTeamData[AiBotMap.subrefLZSValue] > 0)) then
        if bDebugMessages == true then LOG(sFunctionRef..': Have more threat than the enemy') end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        return true
    elseif tLZTeamData[AiBotMap.subrefLZbCoreBase] and iOurCombatThreat > iEnemyCombatThreat * 0.8 then
        if bDebugMessages == true then LOG(sFunctionRef..': Core base so applying a lower threshold to attack the enemy') end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        return true
        --Wnat to be more aggressive if we have friendly buildings in the zone or engineers and we have a chance of beating the enemy
    elseif iOurCombatThreat >= iEnemyCombatThreat and iFirebaseThreatAdjust == 0 and ((tLZTeamData[AiBotMap.subrefLZSValue] or 0) > 0 or (iEnemyCombatThreat <= 200 and (tLZTeamData[AiBotMap.subrefLZTValue] >= iOurCombatThreat or (AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false and AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(AiBotUnitInfo.refCategoryEngineer, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])) == false)))) then
        if bDebugMessages == true then LOG(sFunctionRef..': Have a chance of beating enemy and friendly buildings') end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        return true
    elseif AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDontHaveBuildingsOrACUInPlayableArea] then
        if bDebugMessages == true then LOG(sFunctionRef..': Dont have any buildings left so might as well attack') end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        return true
    elseif IsTableOfUnitsStillValid(AiBotTeam.tTeamData[iTeam][AiBotTeam.toActiveSnipeTargets]) and AreAnyOfTableOfUnitsInAdjacentLandZone(AiBotTeam.tTeamData[iTeam][AiBotTeam.toActiveSnipeTargets], iPlateau, iLandZone, tLZData, tLZTeamData, iTeam) then
        if bDebugMessages == true then LOG(sFunctionRef..': Have snipe target nearby so want to target as high priority') end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        return true
    elseif iOurCombatThreat >= 15000 and iOurCombatThreat > (iEnemyCombatThreat + iFirebaseThreatAdjust) * 0.9 and (AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDefendAgainstArti] or AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyArtiAndExpStructure]) == false) then
        --Does enemy have gameender or lots of T3 arti? in which case want to lower threshold
        if AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyT3ArtiCount] + AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyNovaxCount] * 0.5 >= 3 then
            local iEnemyArtiCount = 0
            if bDebugMessages == true then LOG(sFunctionRef..': Enemy has gameender or t3 arti so will be more aggressive') end
            for iUnit, oUnit in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyArtiAndExpStructure] do
                if AiBotUnitInfo.IsUnitValid(oUnit) then
                    if oUnit:GetFractionComplete() >= 0.8 then
                        if EntityCategoryContains(AiBotUnitInfo.refCategoryGameEnder, oUnit.UnitId) then
                            iEnemyArtiCount = iEnemyArtiCount + 3
                        else
                            iEnemyArtiCount = iEnemyArtiCount + 1
                        end
                        if iEnemyArtiCount >= 3 then
                            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                            return true
                        end
                    end
                end
            end
            if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyMobileSatellites]) == false then
                local iNovaxCount = 0
                for iUnit, oUnit in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyMobileSatellites] do
                    iNovaxCount = iNovaxCount + 1
                end
                iEnemyArtiCount = math.max(iEnemyArtiCount, iNovaxCount * 0.5)
                if iEnemyArtiCount >= 3 then
                    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                    return true
                end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return false
end

function DoWeWantAirFactoryInsteadOfLandFactory(iTeam, tLZData, tLZTeamData, oOptionalBrainOverride)
    --Returns true if want an air factory - to be used where we want more production, so we can decide whether to get +1 air fac or +1 land fac

    local sFunctionRef = 'DoWeWantAirFactoryInsteadOfLandFactory'
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    --First check in case of unit restrictions
    if AiBotOverseer.bAirFactoriesCantBeBuilt then
        if bDebugMessages == true then LOG(sFunctionRef..': Air factories seem to be disabled so wont try to build') end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        return false
    elseif not(tLZTeamData[AiBotMap.subrefLZbCoreBase]) then
        if bDebugMessages == true then LOG(sFunctionRef..': Not a core base so dont want air fac') end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        return false
    else
        local iLandFactoriesHave = 0
        if (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyLandFactoryTech] or 0) > 0 and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then
            local tLandFactories = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryLandFactory, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
            if bDebugMessages == true then LOG(sFunctionRef..': Is tLandFactories empty='..tostring(AiBotUtilities.IsTableEmpty(tLandFactories))) end
            if AiBotUtilities.IsTableEmpty(tLandFactories) == false then
                iLandFactoriesHave = table.getn(tLandFactories)
            end
        end

        local aiBrain = oOptionalBrainOverride or ArmyBrains[tLZTeamData[AiBotMap.reftiClosestFriendlyAiBotBrainIndex]]

        if bDebugMessages == true then LOG(sFunctionRef..': Near start, iLandFactoriesHave='..iLandFactoriesHave..'; Highest air fac tech='..(aiBrain[AiBotEconomy.refiOurHighestAirFactoryTech] or 'nil')..'; bGoingSecondAir='..tostring(aiBrain[AiBotEconomy.refbGoingSecondAir] or false)..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored]..'; Focus on T1 spam='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbFocusOnT1Spam] or false)..'; oOptionalBrainOverride='..(oOptionalBrainOverride.Nickname or 'nil')..'; aiBrain='..(aiBrain.Nickname or 'nil')) end

        -- Dual Gap roles must decide this branch before the generic economy
        -- heuristics. Otherwise an air slot can be sent to land, while a navy
        -- or eco slot can open air production just because the team is short
        -- on aircraft.
        if aiBrain.AiBotDualGapPrimary == 'air' and iLandFactoriesHave > 0 then
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            return true
        elseif aiBrain.AiBotDualGapPrimary == 'land' or aiBrain.AiBotDualGapPrimary == 'eco'
                or (aiBrain.AiBotDualGapPrimary == 'navy'
                    and (GetGameTimeSeconds() < (aiBrain.AiBotDualGapCommitmentEnd or 360)
                        or (aiBrain[AiBotEconomy.refiOurHighestNavalFactoryTech] or 0) < 2)) then
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            return false
        end

        --Early game where ACU wants to go second air - build air fac if low on mass to avoid a case where we stall mass while trying to build 2 different factories at once
        if GetGameTimeSeconds() <= 240 then
            if bDebugMessages == true then LOG(sFunctionRef..': Mass stored for brain '..aiBrain.Nickname..'='..aiBrain:GetEconomyStored('MASS')..'; Net mass income='..aiBrain[AiBotEconomy.refiNetMassBaseIncome]..'; aiBrain[AiBotEconomy.refiGrossMassBaseIncome]='..aiBrain[AiBotEconomy.refiGrossMassBaseIncome]) end
            if aiBrain[AiBotEconomy.refiOurHighestAirFactoryTech] == 0 and aiBrain[AiBotEconomy.refbGoingSecondAir] and aiBrain:GetEconomyStored('MASS') <= 40 and aiBrain[AiBotEconomy.refiNetMassBaseIncome] < 0 and aiBrain[AiBotEconomy.refiGrossMassBaseIncome] < 2 and AiBotMap.iMapSize >= 512 and iLandFactoriesHave > 0 and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbFocusOnT1Spam]) and not(aiBrain[AiBotOverseer.refbPrioritiseLowTech]) then
                --We have a land fac and no air fac, and are in the early game; get the ACU and if it is still doing its initial build order, then check if it is trying to build a land or an air fac
                if bDebugMessages == true then LOG(sFunctionRef..': Want to go second air') end
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                return true
            end
        end

        --Air personality - get air; land personality - get land if have air
        if aiBrain[AiBotOverseer.refbPrioritiseAir] and iLandFactoriesHave > 0 and aiBrain[AiBotEconomy.refiOurHighestLandFactoryTech] > 0 then
            if bDebugMessages == true then LOG(sFunctionRef..': Assigned brain is air, so want to get air fac') end
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            return true
        elseif aiBrain[AiBotOverseer.refbPrioritiseLand] and aiBrain[AiBotEconomy.refiOurHighestAirFactoryTech] > 0 then
            if bDebugMessages == true then LOG(sFunctionRef..': Assigned brain is land, so want to get land fac') end
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            return false
        end


        --Recently failed to build anything at air fac, and either dont have low power or are on the same island as the nearest enemy base, or have dangerous enemies nearby, or are overflowing mass
        if GetGameTimeSeconds() - (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeLastHadNothingToBuildForAirFactory] or -100) <= 10 and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech] or 0) > 0
                and ((GetGameTimeSeconds() - (tLZTeamData[AiBotMap.subrefiTimeAirFacHadNothingToBuild] or -100) <= 5 or tLZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ]) or (not(HaveLowPower(iTeam) and GetGameTimeSeconds() - (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeLastHadNothingToBuildForAirFactory] or -100) <= 1.5)))
                and (tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ] or iLandFactoriesHave < 3 or NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeLand, tLZData[AiBotMap.subrefMidpoint]) == NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeLand, tLZTeamData[AiBotMap.reftClosestEnemyBase]) or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= math.min(0.5 + 0.1 * iLandFactoriesHave, 0.95)))
        then
            if bDebugMessages == true then LOG(sFunctionRef..': Recently failed to find anything to build for air factory so will get land factory instead, AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeLastHadNothingToBuildForAirFactory]='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeLastHadNothingToBuildForAirFactory] or 'nil')) end
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            return false
        else
            --Norush
            if AiBotOverseer.bNoRushActive and AiBotOverseer.iNoRushTimer - GetGameTimeSeconds() >= 30 then

                if bDebugMessages == true then LOG(sFunctionRef..': No rush mode is active, iLandFactories='..iLandFactoriesHave) end
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                if iLandFactoriesHave >= 1 then return true else return false end
            else
                if iLandFactoriesHave >= 1 and AiBotMap.bIsLowMexMap and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] <= 2 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech] == 0 then
                    if bDebugMessages == true then LOG(sFunctionRef..': low eco want air fac') end
                    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                    return true
                else
                    --Late game - get lots of air facs
                    if iLandFactoriesHave >= 1 and (not(AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive) or (AiBotUtilities.bQuietModActive and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiGunshipLosses] < math.max(20000, AiBotTeam.tTeamData[iTeam][AiBotTeam.refiGunshipKills] * 1.2))) and (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] >= 2 or (AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyLandExperimentals]) == false and (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] >= 1 or table.getn(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyLandExperimentals]) >= 2))) then
                        if bDebugMessages == true then LOG(sFunctionRef..': In late game, enemy has experimentals or we do, and we already have al and fac, so want to focus on air') end
                        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                        return true
                        --Also get lots of air facs if we have high gunship/bomber threat and lack air control
                    elseif iLandFactoriesHave >= 1 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurGunshipThreat] + AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurT1ToT3BomberThreat] + (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurExpBomberThreat] or 0) >= 15000 and not(TeamHasAirControl(iTeam)) and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech] >= 3 or (aiBrain[AiBotEconomy.refiOurHighestAirFactoryTech] == 2 and iLandFactoriesHave >= 2 and AiBotMap.iMapSize >= 512 and aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryAirFactory) < 2)) and (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] >= 1 or iLandFactoriesHave >= 3) and (not(AiBotUtilities.bLoudModActive) or iLandFactoriesHave >= 4) then
                        if bDebugMessages == true then LOG(sFunctionRef..': T3 air, lack air contorl, and have isgnificant gunship/bomber threat, so want more air facs') end
                        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                        return true
                    else

                        local iOurIsland = NavUtils.GetLabel(AiBotMap.refPathingTypeLand, tLZData[AiBotMap.subrefMidpoint])
                        if bDebugMessages == true then LOG(sFunctionRef..': Time='..GetGameTimeSeconds()..'; Is this core base='..tostring(tLZTeamData[AiBotMap.subrefLZbCoreBase] or false)..'; iOurIsland='..iOurIsland..'; Closest friendly base island='..NavUtils.GetLabel(AiBotMap.refPathingTypeLand, tLZTeamData[AiBotMap.reftClosestFriendlyBase])) end
                        if tLZTeamData[AiBotMap.subrefLZbCoreBase] or iOurIsland == NavUtils.GetLabel(AiBotMap.refPathingTypeLand, tLZTeamData[AiBotMap.reftClosestFriendlyBase]) then
                            --If are low on power and can path to enemy with land that isn't far away and dont have T2 air yet but do have t1 air then get land factory; also get land if air facs arent able to build air units and we have lots of mass
                            local iEnemyIsland = NavUtils.GetLabel(AiBotMap.refPathingTypeLand, tLZTeamData[AiBotMap.reftClosestEnemyBase])
                            local iOurPlateau = NavUtils.GetLabel(AiBotMap.refPathingTypeHover, tLZData[AiBotMap.subrefMidpoint])
                            local iEnemyPlateau = NavUtils.GetLabel(AiBotMap.refPathingTypeHover, tLZTeamData[AiBotMap.reftClosestEnemyBase])
                            local iLandFactoriesHave = 0
                            local iAirFactoriesForEveryLandFactory = 1
                            if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then
                                local tLandFactories = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryLandFactory, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                                if AiBotUtilities.IsTableEmpty(tLandFactories) == false then
                                    for iFactory, oFactory in tLandFactories do
                                        if AiBotUnitInfo.IsUnitValid(oFactory) and oFactory:GetFractionComplete() == 1 then iLandFactoriesHave = iLandFactoriesHave + 1 end
                                    end
                                end
                            end

                            if bDebugMessages == true then LOG(sFunctionRef..': iOurIsland='..iOurIsland..'; iEnemyIsland='..(iEnemyIsland or 'nil')..'; iOurPlateau='..iOurPlateau..'; iEnemyPlateau='..(iEnemyPlateau or 'nil')..'; air fac tech='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech]..'; subrefiTeamAverageEnergyPercentStored%='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored]..'; Dif between our cur gross E, and E when last unable to build from air fac='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] - (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnergyWhenAirFactoryLastUnableToBuildAir] or 0)) end
                            --If already ahve an air fac (or 5km map) then consider building land fac if we have fewer than 3 land facs or dont have full energy, or have less gross energy than when our air facs last failed ot build air:
                            if (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech] > 0 or AiBotMap.iMapSize < 512) and ((AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored] <= 0.9 and HaveLowPower(iTeam)) or (iLandFactoriesHave < 2 and (iLandFactoriesHave == 0 or not(tLZTeamData[AiBotMap.refbBaseInSafePosition]))) or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] <= (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnergyWhenAirFactoryLastUnableToBuildAir] or 0)) and
                                    --Also require 1 of the following:
                                    --Same island as enemy base with fewer than 4 land facs (3 if we have T2+ air on a >500 size map))
                                    ((iOurIsland == iEnemyIsland and iLandFactoriesHave < 4 and (AiBotMap.iMapSize < 512 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech] < 2 or (aiBrain[AiBotEconomy.refiOurHighestAirFactoryTech] < 2 or iLandFactoriesHave < 2 or (iLandFactoriesHave == 3 or not(aiBrain[AiBotOverseer.refbPrioritiseAir]) and aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryAirFactory) < 2)))) or
                                            --alternatively, same plateau as enemy, and low energy
                                            (iOurPlateau == iEnemyPlateau and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] <= (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnergyWhenAirFactoryLastUnableToBuildAir] or 0) and ((iLandFactoriesHave < 2 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.4) or (iLandFactoriesHave < 4 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.65)))) then
                                if bDebugMessages == true then LOG(sFunctionRef..': We want land fac1, subrefiHighestFriendlyAirFactoryTech='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech]..'; iMapSize='..AiBotMap.iMapSize..'; subrefiTeamAverageEnergyPercentStored='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored]..'; iLandFactoriesHave='..iLandFactoriesHave..'; refbBaseInSafePosition='..tostring(tLZTeamData[AiBotMap.refbBaseInSafePosition])..'; subrefiTeamGrossEnergy='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy]..'; refiEnergyWhenAirFactoryLastUnableToBuildAir='..AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnergyWhenAirFactoryLastUnableToBuildAir]) end
                                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                                return false
                            else
                                --Are in core base or we are in same island as core base
                                local iLandFactoriesWantedBeforeAir = 1

                                if bDebugMessages == true then LOG(sFunctionRef..': iLandFactoriesHave='..iLandFactoriesHave) end
                                if iLandFactoriesHave < 1 then
                                    if bDebugMessages == true then LOG(sFunctionRef..': We want land fac2') end
                                    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                                    return false
                                else
                                    --How many land factories do we want
                                    if not(iOurIsland == iEnemyIsland) then
                                        if not(iOurPlateau == iEnemyPlateau) and iLandFactoriesHave >= 2 then
                                            --cant path to enemy even with amphibious so land facs are only for engis, so want max of 2
                                            if bDebugMessages == true then LOG(sFunctionRef..': We want air fac1') end
                                            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                                            return true
                                        else
                                            --Cant path to enemy except with amphibious, so dont want lots of land factories
                                            iLandFactoriesWantedBeforeAir = 1
                                            --Exception if low gross power
                                            if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] <= 22 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] <= 22 * aiBrain[AiBotEconomy.refiBrainBuildRateMultiplier] and not(aiBrain[AiBotOverseer.refbPrioritiseNavy]) and not(aiBrain[AiBotOverseer.refbPrioritiseAir]) then
                                                iLandFactoriesWantedBeforeAir = 2
                                            end
                                            iAirFactoriesForEveryLandFactory = 5
                                            if bDebugMessages == true then LOG(sFunctionRef..': We cant path to enemy by land so eant lots if air relative to land, iLandFactoriesWantedBeforeAir before further adjustments='..iLandFactoriesWantedBeforeAir) end
                                        end
                                    else
                                        --Can path to enemy with land, base number of factories wanted on distance to enemy base
                                        local iEnemyBaseDist = AiBotUtilities.GetDistanceBetweenPositions(  tLZData[AiBotMap.subrefMidpoint], tLZTeamData[AiBotMap.reftClosestEnemyBase])
                                        --Campaign - enemy base location can be messed up, at higher tech levels treat base as furhter away so we get more air instead of land
                                        if AiBotMap.bIsCampaignMap and iEnemyBaseDist < 500 and AiBotMap.iMapSize >= 512 and iLandFactoriesHave >= 2 then
                                            if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech] >= 2 then
                                                iEnemyBaseDist = math.max(iEnemyBaseDist, AiBotMap.iMapSize * 0.75)
                                            end
                                        end
                                        if iEnemyBaseDist >= 500 then
                                            if AiBotMap.iMapSize < 512 and iEnemyBaseDist <= 512 then
                                                iLandFactoriesWantedBeforeAir = 4
                                                iAirFactoriesForEveryLandFactory = 1
                                            elseif iEnemyBaseDist <= 650 and AiBotMap.iMapSize <= 512 and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech] < 2 or aiBrain[AiBotEconomy.refiOurHighestAirFactoryTech] < 2 or AiBotMap.iMapSize < 512 or iLandFactoriesHave < 2) then
                                                iLandFactoriesWantedBeforeAir = 3
                                                iAirFactoriesForEveryLandFactory = 1
                                            elseif aiBrain[AiBotEconomy.refiOurHighestAirFactoryTech] == 2 and iLandFactoriesHave >= 2 and AiBotMap.iMapSize >= 512 then
                                                iLandFactoriesWantedBeforeAir = 2
                                                iAirFactoriesForEveryLandFactory = 1
                                            else
                                                iLandFactoriesWantedBeforeAir = 1
                                                iAirFactoriesForEveryLandFactory = 4
                                                if AiBotMap.iMapSize >= 1000 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech] >= 3 then iAirFactoriesForEveryLandFactory = 6 end
                                            end
                                        elseif iEnemyBaseDist >= 350 then
                                            iLandFactoriesWantedBeforeAir = 2
                                            if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech] <= 2 or AiBotMap.iMapSize < 512 then
                                                iAirFactoriesForEveryLandFactory = 1
                                            else
                                                iAirFactoriesForEveryLandFactory = 4
                                            end
                                        else
                                            iLandFactoriesWantedBeforeAir = 5 - aiBrain[AiBotEconomy.refiOurHighestAirFactoryTech]
                                            if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech] <= 1 and not(AiBotMap.bIsCampaignMap) then
                                                iAirFactoriesForEveryLandFactory = 0.25
                                                if AiBotMap.iMapSize == 256 and iEnemyBaseDist <= 210 then --Dont apply for <256 (e.g. winter duel) where if enemy goes T2 then T1 spam becomes very weak
                                                    iLandFactoriesWantedBeforeAir = 7
                                                elseif AiBotMap.iMapSize < 210 then --e.g. winter duel
                                                    iLandFactoriesWantedBeforeAir = 3 --will be increased to 4 below due to only being 1 AiBot player
                                                end
                                            else
                                                if iEnemyBaseDist <= 250 then
                                                    --Somtimes on campaign map thenearest enemy base is messed up
                                                    if AiBotMap.bIsCampaignMap then
                                                        if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech] >= 2 then
                                                            iAirFactoriesForEveryLandFactory = 1.25
                                                        else
                                                            iAirFactoriesForEveryLandFactory = 0.75
                                                        end
                                                    else
                                                        iAirFactoriesForEveryLandFactory = 0.5
                                                    end
                                                else
                                                    iAirFactoriesForEveryLandFactory = 3
                                                end
                                            end
                                        end
                                        if AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat] > 0 and not(TeamHasAirControl(iTeam)) then
                                            if AiBotMap.iMapSize <= 256 then
                                                iLandFactoriesWantedBeforeAir = math.max(math.min(2, iLandFactoriesWantedBeforeAir), iLandFactoriesWantedBeforeAir * 0.5)
                                                iAirFactoriesForEveryLandFactory = math.max(0.5, iAirFactoriesForEveryLandFactory)
                                            else
                                                iLandFactoriesWantedBeforeAir = 1
                                                iAirFactoriesForEveryLandFactory = math.min(math.max(iAirFactoriesForEveryLandFactory, 6), iAirFactoriesForEveryLandFactory * 1.5)
                                            end
                                        end
                                        if aiBrain[AiBotOverseer.refbPrioritiseNavy] then iAirFactoriesForEveryLandFactory = math.max(iAirFactoriesForEveryLandFactory, 1) end
                                    end
                                    if iAirFactoriesForEveryLandFactory > 0.5 and (AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive) and (not(AiBotUtilities.bQuietModActive) or AiBotTeam.tTeamData[iTeam][AiBotTeam.refiGunshipLosses] > math.max(20000, AiBotTeam.tTeamData[iTeam][AiBotTeam.refiGunshipKills] * 1.2)) then
                                        if NavUtils.GetLabel(AiBotMap.refPathingTypeLand, tLZTeamData[AiBotMap.reftClosestEnemyBase]) == tLZData[AiBotMap.subrefLZIslandRef] then
                                            --If enemy has significant AA threat then want to get land more than air, so apply more of a reduction
                                            local iEnemyNearbyAA = (AiBotTeam.tLandSubteamData[ArmyBrains[tLZTeamData[AiBotMap.reftiClosestFriendlyAiBotBrainIndex]].AiBotLandSubteam][AiBotTeam.refiEnemyGroundAAThreatNearOurSide] or 0)
                                            if iEnemyNearbyAA >= 8000 or (iEnemyNearbyAA >= 3000 and iEnemyNearbyAA * 3 >= AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurGunshipThreat] +  AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurT1ToT3BomberThreat] + (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurExpBomberThreat] or 0)) then
                                                iAirFactoriesForEveryLandFactory = 0.5
                                            else
                                                iAirFactoriesForEveryLandFactory = math.min(iAirFactoriesForEveryLandFactory, 1)
                                            end
                                            if bDebugMessages == true then LOG(sFunctionRef..': Can path to enemy with land, iEnemyNearbyAA='..iEnemyNearbyAA..'; iAirFactoriesForEveryLandFactory='..iAirFactoriesForEveryLandFactory) end
                                        else
                                            iAirFactoriesForEveryLandFactory = math.min(iAirFactoriesForEveryLandFactory, 2)
                                        end
                                        if AiBotUtilities.bQuietModActive then
                                            --If we have seraphim on team will want more air to support bombers
                                            local bHaveSeraphimOnTeam = false
                                            for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains] do
                                                if oBrain:GetFactionIndex() == AiBotUnitInfo.refFactionSeraphim then
                                                    bHaveSeraphimOnTeam = true
                                                    break
                                                end
                                            end
                                            if bHaveSeraphimOnTeam then iAirFactoriesForEveryLandFactory = iAirFactoriesForEveryLandFactory * 2 end
                                        end
                                        if not(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbHaveAirControl]) and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat] >= 12000 then
                                            iAirFactoriesForEveryLandFactory = iAirFactoriesForEveryLandFactory * 1.5
                                            --[[local iNearbyEnemyGroundAAThreat = 0
                                            local tbLandSubteams = {}
                                            for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains] do
                                                tbLandSubteams[oBrain.AiBotLandSubteam] = true
                                            end
                                            for iLandSubteam, _ in tbLandSubteams do
                                                iNearbyEnemyGroundAAThreat = iNearbyEnemyGroundAAThreat + (AiBotTeam.tLandSubteamData[iLandSubteam][AiBotTeam.refiEnemyGroundAAThreatNearOurSide] or 0)
                                            end
                                            if iNearbyEnemyGroundAAThreat > math.max(4000, AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurGunshipThreat] * 0.25, AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurAirAAThreat] * 0.08) + AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurGunshipThreat] + AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurT1ToT3BomberThreat] + AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurAirAAThreat] * 0.1 then
                                                iAirFactoriesForEveryLandFactory = math.min(1.5, iAirFactoriesForEveryLandFactory)
                                                if AiBotMap.iMapSize <= 1024 or AiBotUtilities.GetDistanceBetweenPositions(tLZTeamData[AiBotMap.reftClosestEnemyBase], tLZData[AiBotMap.subrefMidpoint]) <= 800 then
                                                    iAirFactoriesForEveryLandFactory = 1
                                                end
                                            end--]]
                                        end
                                    end
                                    if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] == 1 and not(aiBrain[AiBotMap.refbCanPathToEnemyBaseWithLand]) then
                                        iLandFactoriesWantedBeforeAir = iLandFactoriesWantedBeforeAir + 1
                                        iAirFactoriesForEveryLandFactory = iAirFactoriesForEveryLandFactory * 0.8
                                    end
                                    if iLandFactoriesHave >= 3 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech] >= 1 and AiBotMap.bIsCampaignMap then
                                        iAirFactoriesForEveryLandFactory = math.max(iAirFactoriesForEveryLandFactory, 1)
                                        iLandFactoriesWantedBeforeAir = math.min(iLandFactoriesWantedBeforeAir, 3)
                                    end
                                    if not(AiBotUtilities.bLoudModActive) and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiGunshipLosses] < math.max(20000, AiBotTeam.tTeamData[iTeam][AiBotTeam.refiGunshipKills] * 1.2) and iLandFactoriesWantedBeforeAir > 3 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiLowestFriendlyLandFactoryTech] >= 2 and (AiBotMap.iMapSize > 256 or iLandFactoriesWantedBeforeAir > 4 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiLowestFriendlyLandFactoryTech] >= 3) then
                                        iLandFactoriesWantedBeforeAir = math.max(3, iLandFactoriesWantedBeforeAir * 0.5)
                                        if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech] > 1 then
                                            iAirFactoriesForEveryLandFactory = math.max(iAirFactoriesForEveryLandFactory, 0.75)
                                        else
                                            iAirFactoriesForEveryLandFactory = math.max(iAirFactoriesForEveryLandFactory, 0.5)
                                        end
                                    end
                                    if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech] == 0 and iLandFactoriesWantedBeforeAir >= 2 then
                                        if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiLowestFriendlyLandFactoryTech] >= 2 or tLZTeamData[AiBotMap.refbBaseInSafePosition] then
                                            iLandFactoriesWantedBeforeAir = 1
                                            --If enemy has land combat units but no airforce then consider getting air fac earlier even on smaller maps - for simplicity will just do a count of units (could consider in future refining to cycle through all nearby zones)
                                        elseif iLandFactoriesWantedBeforeAir > 2 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech] == 0 and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirAAThreat] == 0 then
                                            local iEnemyLandCombatCount = 0
                                            local iEnemyGroundAACount = 0
                                            for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoEnemyBrains] do
                                                iEnemyLandCombatCount = iEnemyLandCombatCount + oBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryLandCombat)
                                                iEnemyGroundAACount = iEnemyGroundAACount + oBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryGroundAA)
                                            end
                                            if iEnemyLandCombatCount > iEnemyGroundAACount * 12 then
                                                iLandFactoriesWantedBeforeAir = 1
                                            end
                                        end
                                    end
                                    if iLandFactoriesHave >= 4 and AiBotMap.iMapSize >= 1000 and not(TeamHasAirControl(iTeam)) then iAirFactoriesForEveryLandFactory = iAirFactoriesForEveryLandFactory * 1.5 end

                                    if bDebugMessages == true then LOG(sFunctionRef..': iAirFactoriesForEveryLandFactory='..iAirFactoriesForEveryLandFactory..'; iLandFactoriesWantedBeforeAir='..iLandFactoriesWantedBeforeAir..'; iLandFactoriesHave='..iLandFactoriesHave..'; Our team AirAA threat='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurAirAAThreat]..'; Enemy AirAA threat='..AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirAAThreat]..'; Do we have air control='..tostring(TeamHasAirControl(iTeam))) end
                                    if iLandFactoriesHave < iLandFactoriesWantedBeforeAir then
                                        if bDebugMessages == true then LOG(sFunctionRef..': We want land fac3') end
                                        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                                        return false
                                    else
                                        --Have min number of land factories, now check how many air factories we have
                                        local iAirFactoriesHave = 0
                                        if (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech] or 0) > 0 and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then
                                            local tAirFactories = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryAirFactory, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                                            if AiBotUtilities.IsTableEmpty(tAirFactories) == false then
                                                iAirFactoriesHave = table.getn(tAirFactories)
                                            end
                                        end
                                        local iAirFactoriesWanted = math.ceil(iLandFactoriesHave * iAirFactoriesForEveryLandFactory)
                                        if iAirFactoriesWanted < 2 and AiBotMap.iMapSize >= 512 and iLandFactoriesHave >= 3 and not(aiBrain[AiBotOverseer.refbPrioritiseLand]) then iAirFactoriesWanted = 2 end
                                        if bDebugMessages == true then LOG(sFunctionRef..': iAirFactoriesWanted='..iAirFactoriesWanted..'; iAirFactoriesHave='..iAirFactoriesHave..'; In t1 spam mode='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbFocusOnT1Spam])) end
                                        if iAirFactoriesHave >= 1 and ZoneWantsT1Spam(tLZTeamData, iTeam) and (iAirFactoriesHave >= 2 or iAirFactoriesWanted < 2 or (AiBotMap.iMapSize < 512 and (aiBrain[AiBotEconomy.refiOurHighestAirFactoryTech] == 1 or iLandFactoriesHave < 4) and (iLandFactoriesHave < 5 or not(aiBrain:GetFactionIndex() == AiBotUnitInfo.refFactionCybran))) or iLandFactoriesHave < 3 or aiBrain[AiBotOverseer.refbPrioritiseLand]) then
                                            if bDebugMessages == true then LOG(sFunctionRef..': Want to focus on t1 spam so want more land facs') end
                                            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                                            return false
                                        elseif iAirFactoriesWanted > iAirFactoriesHave then
                                            --If we have 1 air fac, and want to save mass for mmls, then get land fac instead
                                            if iAirFactoriesHave > 0 and iLandFactoriesHave > 0 and iLandFactoriesHave < 7 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiLowestFriendlyLandFactoryTech] >= 2 and SaveMassForMMLOrMobileT3ArtiForFirebase(tLZData, tLZTeamData, NavUtils.GetLabel(AiBotMap.refPathingTypeHover, tLZData[AiBotMap.subrefMidpoint]), iTeam, TeamHasLowMass(iTeam)) then
                                                if bDebugMessages == true then LOG(sFunctionRef..': Want MMLs so will try and get more land facs instead of air') end
                                                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                                                return false
                                            else
                                                if bDebugMessages == true then LOG(sFunctionRef..': We want air fac2') end
                                                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                                                return true
                                            end
                                        else
                                            if bDebugMessages == true then LOG(sFunctionRef..': We want land fac4') end
                                            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                                            return false
                                        end
                                    end
                                end
                            end

                        else
                            --Dif island to nearest start position so presumably want land factories to take contorl of island/plateau
                            if bDebugMessages == true then LOG(sFunctionRef..': Different island to start position so want land factories to take control of the island, we want land fac5') end
                            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                            return false
                        end
                    end
                end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function GetThreatOfApproachingEnemyACUsAndNearestACU(tLZData, tLZTeamData, iPlateau, iLandZone, iTeam, iOptionalDistanceMod)
    --Will return the combat threat of any approaching enemy ACUs and the position of the nearest ACU (usfficiently in range); also updates the time of hte appraoching threat
        --For safe zones will consider if there is a friendly zone between us and the approaching ACU
    local sFunctionRef = 'GetThreatOfApproachingEnemyACUsAndNearestACU'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end

    local iTotalACUThreat = 0
    if bDebugMessages == true then LOG(sFunctionRef..': Time='..GetGameTimeSeconds()..'; Is table of enemy ACUs empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyACUs]))) end
    if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyACUs]) == false then
        local aiBrain = ArmyBrains[tLZTeamData[AiBotMap.reftiClosestFriendlyAiBotBrainIndex]]
        local tMidpoint = tLZData[AiBotMap.subrefMidpoint]
        local iDistAdjustMod = (iOptionalDistanceMod or 0)
        local iDistanceThreshold = math.max(math.min(AiBotUtilities.GetDistanceBetweenPositions(tLZTeamData[AiBotMap.reftClosestEnemyBase], tMidpoint) * 0.75, 250), 140) + iDistAdjustMod
        if AiBotMap.iMapSize > 256 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] >= 4 then iDistanceThreshold = math.max(iDistanceThreshold, 175) end
        if aiBrain[AiBotOverseer.refbPrioritiseDefence] then iDistanceThreshold = iDistanceThreshold + math.max(iDistanceThreshold * 0.35, 50) end
        if bDebugMessages == true then LOG(sFunctionRef..': iDistanceThreshold='..iDistanceThreshold..'; iMapSize='..AiBotMap.iMapSize..'; Gross mass='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]..'; Dist to closest enemy base='..AiBotUtilities.GetDistanceBetweenPositions(tLZTeamData[AiBotMap.reftClosestEnemyBase], tMidpoint)) end
        local tACUsInRange = {}
        local iNearestACUDist = 100000
        local oNearestACU
        local iCurDist
        local iWaterDistanceThreshold = math.min(iDistanceThreshold, 175) + iDistAdjustMod
        if aiBrain[AiBotOverseer.refbPrioritiseDefence] then iWaterDistanceThreshold = iWaterDistanceThreshold + 50 end
        function DoWePathThroughOtherCoreBaseFirst(oACU)
            if bDebugMessages == true then LOG(sFunctionRef..': ACU assigned plateua='..(oACU[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][1] or 'nil')..'; iPlateau='..iPlateau..'; Nav utils plateau='..(NavUtils.GetLabel(AiBotMap.refPathingTypeHover, oACU:GetPosition()) or 'nil')) end
            if not((oACU[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][1] or NavUtils.GetLabel(AiBotMap.refPathingTypeHover, oACU:GetPosition())) == iPlateau) then
                if bDebugMessages == true then LOG(sFunctionRef..': enemy ACU is in a different plateau, or not detected yet, is oACU[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam] nil='..tostring(oACU[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam] == nil)) end
                --Ignore ACU as not in same plateau
                return true
            elseif oACU[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2] == iLandZone then
                --ACU is already in this zone
                if bDebugMessages == true then LOG(sFunctionRef..': enemy ACU is in the same land zone') end
                return false
                --if ACU is underwater consider it as an approaching threat, but at a lower distance threshold - dont bother with trying to figure out if we path through a core base first (as more risk anyway with water that enemy can go around a core base)
            elseif AiBotUnitInfo.IsUnitUnderwater(oACU) then
                if bDebugMessages == true then LOG(sFunctionRef..': ACU is underwater, iCurDist='..iCurDist..'; iWaterDistanceThreshold='..iWaterDistanceThreshold) end
                if iCurDist <= iWaterDistanceThreshold then
                    return false
                else
                    return true
                end
            elseif not(NavUtils.GetLabel(AiBotMap.refPathingTypeLand, oACU:GetPosition()) == tLZData[AiBotMap.subrefLZIslandRef]) then
                if bDebugMessages == true then LOG(sFunctionRef..': enemy ACU is in a different island') end
                return true
            else
                local iACULandZone = oACU[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2]
                if not(oACU[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2]) then
                    local iACUPlateau
                    iACUPlateau, iACULandZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oACU:GetPosition())
                end
                if not(tLZData[AiBotMap.subrefLZPathingToOtherLZEntryRef][iACULandZone]) and iACULandZone then
                    AiBotMap.ConsiderAddingTargetLandZoneToDistanceFromBaseTable(iPlateau, iLandZone, iACULandZone, tLZData[AiBotMap.subrefMidpoint])
                end
                if not(tLZData[AiBotMap.subrefLZPathingToOtherLZEntryRef][iACULandZone]) then
                    if bDebugMessages == true then LOG(sFunctionRef..': iACULandZOne='..(iACULandZone or 'nil')..'; dont have any land pathing from there to this zone, to be safe will assume ACU can reach us') end
                    --To be safe will assume ACU is a threat
                    return false
                else
                    local iPathingRef = tLZData[AiBotMap.subrefLZPathingToOtherLZEntryRef][iACULandZone]
                    if not(tLZData[AiBotMap.subrefLZPathingToOtherLandZones][iPathingRef]) then
                        --To be safe will assume ACU is a threat
                        AiBotUtilities.ErrorHandler('Likely error - we have a pathing ref but no data')
                        if bDebugMessages == true then LOG(sFunctionRef..': iACULandZOne='..iACULandZone..'; We have a reference but no actual pathing from there to this zone, to be safe will assume ACU can reach us, iPathingRef='..iPathingRef..'; tLZData[AiBotMap.subrefLZPathingToOtherLandZones]='..repru(tLZData[AiBotMap.subrefLZPathingToOtherLandZones])) end
                        return false
                    else
                        for _, iLandZoneRef in tLZData[AiBotMap.subrefLZPathingToOtherLandZones][iPathingRef][AiBotMap.subrefLZPath] do
                            if not(iLandZoneRef == iLandZone) then
                                local tPathingLZTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZoneRef][AiBotMap.subrefLZTeamData][iTeam]
                                if bDebugMessages == true then LOG(sFunctionRef..': enemy ACU owned by '..oACU:GetAIBrain().Nickname..' would be pathing through iLandZoneRef='..iLandZoneRef..' to get to us at iLandZone='..iLandZone..'; is this a core base='..tostring(tPathingLZTeamData[AiBotMap.subrefLZbCoreBase])) end
                                if tPathingLZTeamData[AiBotMap.subrefLZbCoreBase] then
                                    return true
                                elseif AiBotUtilities.IsTableEmpty(tPathingLZTeamData[AiBotMap.subrefLZThreatAllyStructureDFByRange]) == false then
                                    local iThreatInZone = 0
                                    for iRange, iThreat in tPathingLZTeamData[AiBotMap.subrefLZThreatAllyStructureDFByRange] do
                                        if iRange > oACU[AiBotUnitInfo.refiDFRange] then
                                            iThreatInZone = iThreatInZone + iThreat
                                        end
                                    end
                                    if iThreatInZone >= 2000 then
                                        return true
                                    end
                                end
                            end
                        end
                    end
                end
                --tLZData[AiBotMap.subrefLZPathingToOtherLandZones][tLZData[AiBotMap.subrefLZPathingToOtherLZEntryRef][iClosestLZRef]][AiBotMap.subrefLZPath][1]
            end
        end
        if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyACUs]) == false then
            for iACU, oACU in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyACUs] do
                if AiBotUnitInfo.IsUnitValid(oACU) then
                    iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), tMidpoint)
                    if bDebugMessages == true then LOG(sFunctionRef..': Considering enemy ACU '..oACU.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oACU)..' owned by '..oACU:GetAIBrain().Nickname..'; iCurDist Distance to midpoint='..iCurDist..'; iDistanceThreshold='..iDistanceThreshold) end
                    if iCurDist <= iDistanceThreshold then
                        --Consider whether we pass through another core base first
                        if iCurDist <= 90 + iDistAdjustMod or tLZTeamData[AiBotMap.subrefMexCountByTech][3] >= 2 or (iCurDist <= 120 + iDistAdjustMod and not(tLZTeamData[AiBotMap.refbBaseInSafePosition])) or (aiBrain[AiBotOverseer.refbPrioritiseDefence] and iCurDist <= 180 + iDistAdjustMod) or not(DoWePathThroughOtherCoreBaseFirst(oACU)) then
                            table.insert(tACUsInRange, oACU)
                            if bDebugMessages == true then LOG(sFunctionRef..': Adding ACU as an in range enemy unit') end
                            if iCurDist < iNearestACUDist then
                                iNearestACUDist = iCurDist
                                oNearestACU = oACU
                            end
                        end
                    end
                end
            end
        end
        iTotalACUThreat = AiBotUnitInfo.GetCombatThreatRating(tACUsInRange, true)
        if bDebugMessages == true then LOG(sFunctionRef..': iTotalACUThreat='..iTotalACUThreat) end
        if iTotalACUThreat > 0 and tLZTeamData[AiBotMap.subrefLZbCoreBase] then
            if not(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftCoreLZsTimeOfApproachingACUByPlateauAndZone]) then AiBotTeam.tTeamData[iTeam][AiBotTeam.reftCoreLZsTimeOfApproachingACUByPlateauAndZone] = {} end
            if not(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftCoreLZsTimeOfApproachingACUByPlateauAndZone][iPlateau]) then AiBotTeam.tTeamData[iTeam][AiBotTeam.reftCoreLZsTimeOfApproachingACUByPlateauAndZone][iPlateau] = {} end
            AiBotTeam.tTeamData[iTeam][AiBotTeam.reftCoreLZsTimeOfApproachingACUByPlateauAndZone][iPlateau][iLandZone] = GetGameTimeSeconds()
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            if oNearestACU then return iTotalACUThreat, oNearestACU end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return iTotalACUThreat, nil
end

function SaveMassForMMLOrMobileT3ArtiForFirebase(tLZData, tLZTeamData, iPlateau, iTeam, bHaveLowMass)
    --Returns x and y; x is true if want to build MMLs or T3 mobile arti to deal with a firebase; y is true if need T3 (e.g. dealing with ravagers)
    --If we have low mass then will prioritise building MML with what little mass we have, unless enemy has long range units (like ravagers and fatboys)
    local sFunctionRef = 'SaveMassForMMLOrMobileT3ArtiForFirebase'
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    local bSaveMassForFirebase = false
    local bNeedT3 = false

    if bDebugMessages == true then LOG(sFunctionRef..': Near start of code, bHaveLowMass='..tostring(bHaveLowMass)..'; Is table of LR enemy DF units empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoLongRangeEnemyDFUnits]))..'; Highest firneldy land fac tech='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyLandFactoryTech]..'; T3 mex count='..tLZTeamData[AiBotMap.subrefMexCountByTech][3]..'; Mass stored='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored]) end
    if bHaveLowMass then
        --MML for enemy firebase, when enemy lacks fatboy/ravagers
        if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoLongRangeEnemyDFUnits]) and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyLandFactoryTech] < 3 or tLZTeamData[AiBotMap.subrefMexCountByTech][3] == 0 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored] <= 300) then
            --Are there T2 arti in range?
            if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits]) == false then
                if bDebugMessages == true then LOG(sFunctionRef..': Number of T2 arti in range='..table.getn(tLZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits])) end
                if table.getn(tLZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits]) <= 6 then --If enemy has 7+ T2 arti then probably reached the point where MMLs wont cut it even in very large numbers
                    bSaveMassForFirebase = true
                end
            else
                if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftEnemyFirebasesInRange]) == false then
                    bSaveMassForFirebase = true
                else
                    --Is closest ACU an ACU with T2 and no gun?
                    local bNearbyGuncom = false
                    local bNearbyT2ACU = false
                    if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyACUs]) == false then
                        local iDistThreshold = 220
                        if AiBotMap.iMapSize <= 256 then iDistThreshold = 180 end
                        local AiBotACU = import('/lua/AiBot/AI/AiBotACU.lua')
                        for iACU, oACU in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyACUs] do
                            if AiBotUnitInfo.IsUnitValid(oACU) then
                                if bDebugMessages == true then LOG(sFunctionRef..': Considering enemy ACU owned by brain '..oACU:GetAIBrain().Nickname..'; ACU DF range='..(oACU[AiBotUnitInfo.refiDFRange] or 0)..'; ACU unit state='..AiBotUnitInfo.GetUnitState(oACU)..'; Dist from ACU to midpoint='..AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), tLZData[AiBotMap.subrefMidpoint])) end
                                if (oACU[AiBotUnitInfo.refiDFRange] or 0) >= 26 then
                                    if AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), tLZData[AiBotMap.subrefMidpoint]) <= iDistThreshold then
                                        if bDebugMessages == true then LOG(sFunctionRef..': enemy has nearby guncom') end
                                        bNearbyGuncom = true
                                        break
                                    end
                                    --If enemy ACU is upgrading fairnly nearby then assume it is upgrading to get T2 to be prudent
                                elseif not(bNearbyT2ACU) and (oACU:HasEnhancement('AdvancedEngineering') or oACU:HasEnhancement('T3Engineering') or ((oACU[AiBotACU.refiUpgradeCount] or 0) == 0 and oACU:IsUnitState('Upgrading'))) then
                                    if AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), tLZData[AiBotMap.subrefMidpoint]) <= iDistThreshold then
                                        if bDebugMessages == true then LOG(sFunctionRef..': Enemy Has nearby T2 ACU') end
                                        bNearbyT2ACU = true
                                    end
                                end
                            end
                        end
                        if bNearbyT2ACU and not(bNearbyGuncom) then
                            bSaveMassForFirebase = true
                        end
                    end
                end
            end
            --T3 mobile arti for if enemy has nearby ravagers and we havent built many experimentals
        elseif AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoLongRangeEnemyDFUnits]) == false and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] <= 1 then
            --Do we have ravagers in this or adjacent zone, but not fatboy or megalith?
            --First check if enemy has any ravagers, or a constructed fatboy
            local bEnemyHasRavagerSomewhere = false
            local bEnemyHasFatboySomewhere = false
            for iUnit, oUnit in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoLongRangeEnemyDFUnits] do
                if not(oUnit.Dead) then

                    if not(bEnemyHasRavagerSomewhere) and (oUnit[AiBotUnitInfo.refiDFRange] or 0) >= 60 and EntityCategoryContains(AiBotUnitInfo.refCategoryPD, oUnit.UnitId) then
                        bEnemyHasRavagerSomewhere = true
                        if bEnemyHasFatboySomewhere then break end
                    end
                    if not(bEnemyHasFatboySomewhere) and (oUnit[AiBotUnitInfo.refiDFRange] or 0) >= 80 and oUnit:GetFractionComplete() == 1 and EntityCategoryContains(AiBotUnitInfo.refCategoryLandExperimental, oUnit.UnitId) then
                        bEnemyHasFatboySomewhere = true
                        if bEnemyHasRavagerSomewhere then break end
                    end
                end
            end
            if bEnemyHasRavagerSomewhere and not(bEnemyHasFatboySomewhere) then
                local bHaveNearbyRavager = false
                function CheckIfZoneHasRavagers(tZoneTeamData)
                    if tZoneTeamData[AiBotMap.subrefiNearbyEnemyLongRangeDFThreat] > 0 and AiBotUtilities.IsTableEmpty(tZoneTeamData[AiBotMap.subrefoNearbyEnemyLongRangeDFThreats]) == false then
                        for iUnit, oUnit in tZoneTeamData[AiBotMap.subrefoNearbyEnemyLongRangeDFThreats] do
                            if not(oUnit.Dead) and oUnit[AiBotUnitInfo.refiDFRange] >= 60 and EntityCategoryContains(AiBotUnitInfo.refCategoryStructure, oUnit.UnitId) then
                                return true
                            end
                        end
                    end
                    return false
                end
                CheckIfZoneHasRavagers(tLZTeamData)
                if not(bHaveNearbyRavager) and AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                    for _, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
                        local tAdjLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ]
                        local tAdjLZTeamData = tAdjLZData[AiBotMap.subrefLZTeamData][iTeam]
                        CheckIfZoneHasRavagers(tAdjLZTeamData)
                        if bHaveNearbyRavager then break end
                    end
                end
                if bHaveNearbyRavager then
                    --Exception - very high LC for t3 mobile arti, suggesting enemy is able to kill them, or campaign map with T3 land but no T3 mobile arti count
                    local iArtiLC = GetTeamLifetimeBuildCount(iTeam, AiBotUnitInfo.refCategoryIndirect * categories.TECH3)
                    if iArtiLC == 0 and (AiBotOverseer.bUnitRestrictionsArePresent or AiBotMap.bIsCampaignMap) then
                        --Do nothing - we might not be able to build t3 arti
                    elseif iArtiLC >= 20 and iArtiLC >= 10 + 10 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] then
                        --Do nothing - enemy might be countering with t2 arti as well
                    elseif tLZTeamData[AiBotMap.refbBaseInSafePosition] and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] >= 3 and tLZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeDFThreat] == 0 then
                        --Do nothing - in an air slot so want to prioritise air instead, and leave t3 mobile arti to other zones
                    else
                        bSaveMassForFirebase = true
                        bNeedT3 = true
                    end
                end
            end
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': end of code, bSaveMassForFirebase='..tostring(bSaveMassForFirebase)) end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return bSaveMassForFirebase, bNeedT3
end

function IsLocationInNoRushArea(tLocation)
    for iStart, tStart in AiBotOverseer.reftNoRushAiBotStartPoints do
        if AiBotUtilities.GetDistanceBetweenPositions(tLocation, tStart) < AiBotOverseer.iNoRushRange then
            return true
        end
    end
    return false
end

function IsLocationInNoRushArea(tLocation)
    local sFunctionRef = 'IsLocationInNoRushArea'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end

    local bInNoRush = false
    for iStart, tStart in AiBotOverseer.reftNoRushAiBotStartPoints do
        if AiBotUtilities.GetDistanceBetweenPositions(tLocation, tStart) <= AiBotOverseer.iNoRushRange then
            if bDebugMessages == true then LOG(sFunctionRef..': Dist to tStart '..repru(tStart)..' is '..AiBotUtilities.GetDistanceBetweenPositions(tLocation, tStart)..' so are inside norush range') end
            bInNoRush = true
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return bInNoRush
end

function NoRushPreventingHydroOrMex(tLZOrWZData, bMexNotHydro)
    --If norush is active then returns true if all unbuilt hydro points (mex points if bMexNotHydro is true) in this LZ/WZ are outside the norush radius of the nearest allied base
    local sFunctionRef = 'NoRushPreventingHydroOrMex'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end

    local sResourceRef
    if bMexNotHydro then sResourceRef = AiBotMap.subrefMexUnbuiltLocations
    else sResourceRef = AiBotMap.subrefHydroUnbuiltLocations
    end

    if bDebugMessages == true then LOG(sFunctionRef..': Is table of hydro or mex unbuilt locations empty='..tostring(AiBotUtilities.IsTableEmpty(tLZOrWZData[sResourceRef]))..'; bMexNotHydro='..tostring(bMexNotHydro or false)) end
    if AiBotUtilities.IsTableEmpty(tLZOrWZData[sResourceRef]) == false then
        local bAllResourceOutsidePlayableArea = true
        for iEntry, tResource in tLZOrWZData[sResourceRef] do
            if bDebugMessages == true then LOG(sFunctionRef..': tResource='..repru(tResource)..'; Norush range='..AiBotOverseer.iNoRushRange..'; repru of AiBotOverseer.reftNoRushAiBotStartPoints='..repru(AiBotOverseer.reftNoRushAiBotStartPoints)) end
            if IsLocationInNoRushArea(tResource) then
                bAllResourceOutsidePlayableArea = false
                break
            end
        end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        return bAllResourceOutsidePlayableArea
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return false
end

function IsLocationInPlayableArea(tLocation)
    if tLocation[1] > AiBotMap.rMapPlayableArea[1] and  tLocation[1] < AiBotMap.rMapPlayableArea[3] and tLocation[3] > AiBotMap.rMapPlayableArea[2] and  tLocation[3] < AiBotMap.rMapPlayableArea[4] then
        return true
    else
        return false
    end
end

function IsLocationInMap(tLocation)
    --NOT the playable area, just the map itself, e.g. for air units so can ignore updating their assigtned zone if they are outside the map entirely
    if tLocation[1] < 0 or tLocation[3] < 0 or ((tLocation[1] > AiBotMap.iMapSize or tLocation[3] > AiBotMap.iMapSize) and (tLocation[1] > AiBotMap.rMapPlayableArea[3] or tLocation[3] > AiBotMap.rMapPlayableArea[4])) then
        return false
    else
        return true
    end
end

function DoesACUHaveValidOrder(oACU)
    --Checks if either hte ACU has no last order, or the last order is to build something that it cant build
    local sFunctionRef = 'DoesACUHaveValidOrder'
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local tLastOrders = oACU[AiBotOrders.reftiLastOrders]
    if bDebugMessages == true then LOG(sFunctionRef..': tLastOrders='..reprs(tLastOrders)) end
    if not(tLastOrders) then
        if bDebugMessages == true then LOG(sFunctionRef..': Last orders is empty') end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        return false
    elseif AiBotUtilities.IsTableEmpty(tLastOrders) then
        if bDebugMessages == true then LOG(sFunctionRef..': Table of last orders is empty') end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        return false
    else
        local tLastOrder = tLastOrders[oACU[AiBotOrders.refiOrderCount]]
        if tLastOrder[AiBotOrders.subrefiOrderType] == AiBotOrders.refiOrderIssueBuild then
            if bDebugMessages == true then LOG(sFunctionRef..': Last order was to build somethingw ith blueprint '..(tLastOrder[AiBotOrders.subrefsOrderBlueprint] or 'nil')..'; Can build='..tostring(oACU:CanBuild(tLastOrder[AiBotOrders.subrefsOrderBlueprint]))) end
            if oACU:CanBuild(tLastOrder[AiBotOrders.subrefsOrderBlueprint]) then
                --We can build last order, but are we trying to build a mex somewhere that already has a completed mex?
                if bDebugMessages == true then LOG(sFunctionRef..': We can build the blueprint, is last order to build a mex?='..tostring(EntityCategoryContains(AiBotUnitInfo.refCategoryMex, tLastOrder[AiBotOrders.subrefsOrderBlueprint]))) end
                if EntityCategoryContains(AiBotUnitInfo.refCategoryMex, tLastOrder[AiBotOrders.subrefsOrderBlueprint]) then
                    if bDebugMessages == true then LOG(sFunctionRef..': We are trying to build a mex, Last position='..repru(tLastOrder[AiBotOrders.subreftOrderPosition])..'; CanBuildOnMexLocation='..tostring(CanBuildOnMexLocation(tLastOrder[AiBotOrders.subreftOrderPosition]))..'; playable area='..repru(AiBotMap.rMapPlayableArea)..'; Dist to ACU='..AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), tLastOrder[AiBotOrders.subreftOrderPosition])..'; In playable area='..tostring(AiBotMap.InPlayableArea(tLastOrder[AiBotOrders.subreftOrderPosition]))) end
                    if AiBotMap.InPlayableArea(tLastOrder[AiBotOrders.subreftOrderPosition]) then
                        if CanBuildOnMexLocation(tLastOrder[AiBotOrders.subreftOrderPosition]) then
                            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                            return true
                        else
                            --Cant build the mex, is it because there is a mex there?
                            local tUnitsNearPosition = GetUnitsInRect(AiBotUtilities.GetRectAroundLocation(tLastOrder[AiBotOrders.subreftOrderPosition], 1.8))
                            local bBlockedByCompletedMexOnOurTeam = false
                            if AiBotUtilities.IsTableEmpty(tUnitsNearPosition) == false then
                                local tMexesNearPosition = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryMex, tUnitsNearPosition)
                                if AiBotUtilities.IsTableEmpty(tMexesNearPosition) == false then
                                    for iMex, oMex in tMexesNearPosition do
                                        if oMex:GetFractionComplete() == 1 and IsAlly(oMex:GetAIBrain():GetArmyIndex(), oACU:GetAIBrain():GetArmyIndex()) then
                                            bBlockedByCompletedMexOnOurTeam = true
                                            break
                                        end
                                    end
                                end
                            end
                            if bDebugMessages == true then LOG(sFunctionRef..': Trying to build a mex, bBlockedByCompletedMexOnOurTeam='..tostring(bBlockedByCompletedMexOnOurTeam)) end
                            if bBlockedByCompletedMexOnOurTeam then
                                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                                return false
                            else
                                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                                return true
                            end
                        end
                    else
                        --Not in playable area
                        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                        return false
                    end
                else
                    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                    return true
                end
            else
                --Cant build last order
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                return false
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return true
end

function DoWeWantToSynchroniseMMLShots(iPlateau, iLandZone, tLZData, tLZTeamData, iTeam, iFriendlyBestMobileIndirectRange, iEnemyBestDFRange, iAvailableMMLThreat, oClosestUnitFromAllFirebases)
    --Consider synchronising shots with MML if we have enough to warrant it and they are faced with non-Aeon TMD
    local sFunctionRef = 'DoWeWantToSynchroniseMMLShots'
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    local bConsiderSpecialMMLLogic = false
    if bDebugMessages == true then LOG(sFunctionRef..': Start of code, time='..GetGameTimeSeconds()..'; iPlateau '..iPlateau..'; iLandZOne '..iLandZone..'; tLZTeamData[AiBotMap.subrefiTimeOfMMLFiringNearTMDOrShield]='..(tLZTeamData[AiBotMap.subrefiTimeOfMMLFiringNearTMDOrShield] or 'nil')..'; iAvailableMMLThreat='..iAvailableMMLThreat..'; oClosestUnitFromAllFirebases='..(oClosestUnitFromAllFirebases.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oClosestUnitFromAllFirebases) or 'nil')) end
    if iAvailableMMLThreat >= 200 and (tLZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeDFThreat] or 0) == 0 and (iFriendlyBestMobileIndirectRange or 0) > (iEnemyBestDFRange or 0) and iFriendlyBestMobileIndirectRange > (tLZTeamData[AiBotMap.subrefLZThreatEnemyBestMobileIndirectRange] or 0) then
        local bFiredRecentlyNearTMDOrShield = false
        if GetGameTimeSeconds() - (tLZTeamData[AiBotMap.subrefiTimeOfMMLFiringNearTMDOrShield] or -100) <= 30 then bFiredRecentlyNearTMDOrShield = true
        elseif oClosestUnitFromAllFirebases then
            local tFirebaseLZData, tFirebaseLZTeamData = AiBotMap.GetLandOrWaterZoneData(oClosestUnitFromAllFirebases:GetPosition(), true, iTeam)
            if GetGameTimeSeconds() - (tFirebaseLZTeamData[AiBotMap.subrefiTimeOfMMLFiringNearTMDOrShield] or -100) <= 30 then bFiredRecentlyNearTMDOrShield = true end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': bFiredRecentlyNearTMDOrShield='..tostring(bFiredRecentlyNearTMDOrShield)..'; Time since last fired='..GetGameTimeSeconds() - (tLZTeamData[AiBotMap.subrefiTimeOfMMLFiringNearTMDOrShield] or -100)) end
        if bFiredRecentlyNearTMDOrShield then
            if iAvailableMMLThreat >= 1000 and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits]) == false then
                bConsiderSpecialMMLLogic = true
                if bDebugMessages == true then LOG(sFunctionRef..': Have significant number of MMLs, and enemy has t2 arti, so even if they have aeon tmd will still synchronise shots (so can better prioritise what units to target') end
            else
                local bEnemyHasAeonTMD = false --also includes loyalists and naval TMD
                local bEnemyHasNonAeonTMD = false
                function UpdateNearbyTMD(iAdjLZ)
                    local tAdjLZTeamData
                    if iAdjLZ == iLandZone then tAdjLZTeamData = tLZTeamData else tAdjLZTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam] end
                    if AiBotUtilities.IsTableEmpty(tAdjLZTeamData[AiBotMap.subrefTEnemyUnits]) == false then
                        local tZoneTMD = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryTMD + categories.ANTIMISSILE * categories.MOBILE, tAdjLZTeamData[AiBotMap.subrefTEnemyUnits])
                        if AiBotUtilities.IsTableEmpty(tZoneTMD) == false then
                            bEnemyHasNonAeonTMD = true
                            if AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(categories.AEON + categories.ANTIMISSILE * categories.MOBILE, tZoneTMD)) == false then
                                bEnemyHasAeonTMD = true
                            end
                        end
                    end
                end
                UpdateNearbyTMD(iLandZone)
                if not(bEnemyHasAeonTMD) then
                    if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                        for iEntry, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
                            UpdateNearbyTMD(iAdjLZ)
                            if bEnemyHasAeonTMD then break end
                        end
                    end
                end
                if bDebugMessages == true then LOG(sFunctionRef..': bEnemyHasAeonTMD='..tostring(bEnemyHasAeonTMD)..'; bEnemyHasNonAeonTMD='..tostring(bEnemyHasNonAeonTMD)) end
                if not(bEnemyHasAeonTMD) and ((iAvailableMMLThreat >= 500 and (AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits]) == false or (tLZTeamData[AiBotMap.subrefLZThreatEnemyBestStructureDFRange] or 0) >= 40)) or bEnemyHasNonAeonTMD) then
                    bConsiderSpecialMMLLogic = true
                end
            end
        end
    end

    if bDebugMessages == true then LOG(sFunctionRef..': End of code, bConsiderSpecialMMLLogic='..tostring(bConsiderSpecialMMLLogic)) end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return bConsiderSpecialMMLLogic
end

function IsTargetNearActiveNukeTarget(tTarget, iTeam, iDistThreshold, iOptionalTimeThreshold)
    --Returns true if are within iDistThreshold of an active nuke target
    local sFunctionRef = 'IsTargetNearActiveNukeTarget'
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local bNearTarget = false
    if bDebugMessages == true then LOG(sFunctionRef..': Time='..GetGameTimeSeconds()..'; Is table of recently fired nuke launchers empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoRecentlyFiredAlliedNukeLaunchers]))) end
    if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoRecentlyFiredAlliedNukeLaunchers]) == false then
        local iLauncherCount = table.getn(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoRecentlyFiredAlliedNukeLaunchers])
        for iCurLauncher = iLauncherCount, 1, -1 do
            local oLauncher = AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoRecentlyFiredAlliedNukeLaunchers][iCurLauncher]
            if bDebugMessages == true then LOG(sFunctionRef..': Considering oLauncher='..oLauncher.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oLauncher)..'; Is launcher still valid='..tostring(AiBotUnitInfo.IsUnitValid(oLauncher))..'; Active nuke target='..repru(oLauncher[AiBotBuilding.reftActiveNukeTarget])) end
            if not(AiBotUnitInfo.IsUnitValid(oLauncher)) or not(oLauncher[AiBotBuilding.reftActiveNukeTarget]) then
                table.remove(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoRecentlyFiredAlliedNukeLaunchers], iCurLauncher)
            else
                if bDebugMessages == true then LOG(sFunctionRef..': Launcher target='..repru(oLauncher[AiBotBuilding.reftActiveNukeTarget])..'; tTarget='..repru(tTarget)..'; Dist='..AiBotUtilities.GetDistanceBetweenPositions(oLauncher[AiBotBuilding.reftActiveNukeTarget], tTarget)..'; iDistThreshold='..iDistThreshold) end
                if AiBotUtilities.GetDistanceBetweenPositions(oLauncher[AiBotBuilding.reftActiveNukeTarget], tTarget) <= iDistThreshold then
                    bNearTarget = true
                    break
                end
            end

        end
    end
    if not(bNearTarget) and AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefNukeLaunchLocations]) == false then
        --Cycle through nuke targets from the last 60s on our team as well (since looking at the above ignores non-AiBot teammates, while just looking at the reftoRecentlyFiredAlliedNukeLaunchers table ignores nukes that are about to fire but havent yet fired)
        local iTimeThreshold = GetGameTimeSeconds() - (iOptionalTimeThreshold or 60)
        for iTimeLaunched, tNukeTarget in AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefNukeLaunchLocations] do
            if bDebugMessages == true then LOG(sFunctionRef..': Considering launch target with iTimeLaunched='..iTimeLaunched..'; iTimeThreshold='..iTimeThreshold..'; Dist between here and tTarget='..AiBotUtilities.GetDistanceBetweenPositions(tTarget, tNukeTarget)) end
            if iTimeLaunched >= iTimeThreshold and AiBotUtilities.GetDistanceBetweenPositions(tTarget, tNukeTarget) <= iDistThreshold then
                bNearTarget = true
                break
            end
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': End of code, tTarget='..repru(tTarget)..'; bNearTarget='..tostring(bNearTarget)) end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return bNearTarget
end

function IsTableOfUnitsStillValid(tUnits, bInvalidIfFullHealth)
    --bInvalidIfFullHealth - e.g. if have a table of units to repair, set this to true
    local sFunctionRef = 'IsTableOfUnitsStillValid'
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if AiBotUtilities.IsTableEmpty(tUnits) == false then
        local iEntryCount = table.getn(tUnits)
        for iCurEntry = iEntryCount, 1, -1 do
            local oUnit = tUnits[iCurEntry]
            --if bDebugMessages == true then LOG(sFunctionRef..': oUnit='..(oUnit.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oUnit) or 'nil')..'; Is unit valid='..tostring(AiBotUnitInfo.IsUnitValid(oUnit))..'; Is oUnit.GetHealth nil='..tostring(oUnit.GetHealth == nil)) end
            if not(AiBotUnitInfo.IsUnitValid(oUnit)) or (bInvalidIfFullHealth and AiBotUnitInfo.GetUnitHealthPercent(oUnit) == 1) then
                if bDebugMessages == true then LOG(sFunctionRef..': Removing unit '..(oUnit.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oUnit) or 'nil')..' at time '..GetGameTimeSeconds()..'; Is unit valid='..tostring(AiBotUnitInfo.IsUnitValid(oUnit))..'; bInvalidIfFullHealth='..tostring(bInvalidIfFullHealth or false)..'Unit.Dead='..tostring(oUnit.Dead or false)) end
                table.remove(tUnits, iCurEntry)
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': Do we still have a table of valid units? is it empty='..tostring(AiBotUtilities.IsTableEmpty(tUnits))) end
        if AiBotUtilities.IsTableEmpty(tUnits) == false then
            return true
        end
    end
    return false
end

function IsPositionCloseToZoneEdge(iPlateauOrZero, iLandOrWaterZone, iMaxDistToEdgeOfAdjacentZone, tStartPoint)
    --returns true if are within iMaxDistToEdgeOfAdjacentZone of the edge of iLandOrWaterZone, i.e. if this is positive, then will return true if are anywhere in that zone, or outside it by iMaxDistToEdgeOfAdjacentZone; if is a negative number then must be inside the zone by the negativenumber amount
    --Only an approximation - does a square around the outer edges of the zone to estimate
    local tLZOrWZData

    local tMinPosition, tMaxPosition
    if iPlateauOrZero == 0 then
        tLZOrWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iLandOrWaterZone]][AiBotMap.subrefPondWaterZones][iLandOrWaterZone]
        tMinPosition = AiBotMap.GetPositionFromPathingSegments(tLZOrWZData[AiBotMap.subrefWZMinSegX], tLZOrWZData[AiBotMap.subrefWZMinSegZ])
        tMaxPosition = AiBotMap.GetPositionFromPathingSegments(tLZOrWZData[AiBotMap.subrefWZMaxSegX], tLZOrWZData[AiBotMap.subrefWZMaxSegZ])
    else
        tLZOrWZData = AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iLandOrWaterZone]
        tMinPosition = AiBotMap.GetPositionFromPathingSegments(tLZOrWZData[AiBotMap.subrefLZMinSegX], tLZOrWZData[AiBotMap.subrefLZMinSegZ])
        tMaxPosition = AiBotMap.GetPositionFromPathingSegments(tLZOrWZData[AiBotMap.subrefLZMaxSegX], tLZOrWZData[AiBotMap.subrefLZMaxSegX])
    end
    local iMinX = tMinPosition[1]
    local iMaxX = tMaxPosition[1]
    local iMinZ = tMinPosition[3]
    local iMaxZ = tMaxPosition[3]
    --Really could simplify the below into just one formula, but separating it out makes it slightl yeasier to conceptualise
    if iMaxDistToEdgeOfAdjacentZone > 0 then
        --Want to be outside the box
        if tStartPoint[1] >= iMinX - iMaxDistToEdgeOfAdjacentZone and tStartPoint[1] <= iMaxX + iMaxDistToEdgeOfAdjacentZone then
            if tStartPoint[3] >= iMinZ - iMaxDistToEdgeOfAdjacentZone and tStartPoint[3] <= iMaxZ + iMaxDistToEdgeOfAdjacentZone then
                return true
            end
        end
    else
        --Wnat to be inside the zone box
        if tStartPoint[1] >= iMinX + iMaxDistToEdgeOfAdjacentZone and tStartPoint[1] <= iMaxX - iMaxDistToEdgeOfAdjacentZone then
            if tStartPoint[3] >= iMinZ + iMaxDistToEdgeOfAdjacentZone and tStartPoint[3] <= iMaxZ - iMaxDistToEdgeOfAdjacentZone then
                return true
            end
        end
    end
    return false
end

function WantToAttackWithNavyEvenIfOutranged(tWZData, tWZTeamData, iTeam, iNearbyFriendlySubThreat, iCurZoneAndAdjacentAlliedSubmersibleThreat, iAdjacentEnemyAntiNavyThreat, iAdjacentAlliedCombatThreat, iAdjacentEnemyCombatThreat, bConsideringSubmarinesNotSurface, iOptionalThreatAbsolutePercentIncrease, iEnemyNearbySubmersibleThreat, iAvailableAntiNavyThreat, iCommonZoneTargetSurfaceThreat, bNearbyEnemiesAreHostileCivilians)
    --iOptionalThreatAbsolutePercentIncrease - will increase enemy threat factors by this (absolute increase), e.g. set to 0.1 and instead of wanting 1.3 * enemy threat to attack, will want 1.4 * enemy threat
    --NOTE (v283 and earlier) - adjacent zone threats may include current zone, need to rework calculation of these amounts now that have access to common zone target data
    local sFunctionRef = 'WantToAttackWithNavyEvenIfOutranged'
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local bAreInScenario2 = false
    if AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDontHaveBuildingsOrACUInPlayableArea] then bAreInScenario2 = true
    else
        local iModMod = (iOptionalThreatAbsolutePercentIncrease or 0)
        if not(bConsideringSubmarinesNotSurface) and AiBotUtilities.IsTableEmpty(tWZTeamData[AiBotMap.subreftEnemyFirebasesInRange]) == false then
            iModMod = iModMod + 0.75
            local iRoughSurfaceThreat = iAdjacentAlliedCombatThreat + tWZTeamData[AiBotMap.subrefWZTThreatAllyCombatTotal] - iCurZoneAndAdjacentAlliedSubmersibleThreat
            if iRoughSurfaceThreat > 6000 then iModMod = iModMod - 0.5 * math.min(1, (iRoughSurfaceThreat / 30000)) end
        end
        if bConsideringSubmarinesNotSurface and AiBotUtilities.bQuietModActive then
            --Destroyers do well vs subs in QUIET (e.g. 8k UEF destroyers beat 13.5k Aeon subs testing 2025-05-11) so increase threshold in QUIET
            iModMod = iModMod + 0.2
        end
        local iEnemyAntiNavyMod = 1.5 + iModMod
        local iEnemyCombatModHigh = 1.3 + iModMod
        local iEnemyCombatModLow = 1.1 + iModMod
        if bDebugMessages == true then LOG(sFunctionRef..': Near start, bConsideringSubmarinesNotSurface='..tostring(bConsideringSubmarinesNotSurface)..'; iAdjacentAlliedCombatThreat='..iAdjacentAlliedCombatThreat..'; iCurZoneAndAdjacentAlliedSubmersibleThreat='..iCurZoneAndAdjacentAlliedSubmersibleThreat..'; iAdjacentEnemyCombatThreat='..iAdjacentEnemyCombatThreat..'; iEnemyCombatModHigh='..iEnemyCombatModHigh..'; tWZTeamData[AiBotMap.subrefWZTThreatAllyCombatTotal]='..(tWZTeamData[AiBotMap.subrefWZTThreatAllyCombatTotal] or 0)..'; iEnemyCombatModLow='..iEnemyCombatModLow..'; iAdjacentEnemyAntiNavyThreat='..iAdjacentEnemyAntiNavyThreat..'; iEnemyAntiNavyMod='..iEnemyAntiNavyMod..'; iNearbyFriendlySubThreat='..iNearbyFriendlySubThreat) end
        if (bConsideringSubmarinesNotSurface and (iNearbyFriendlySubThreat >= iAdjacentEnemyAntiNavyThreat or iNearbyFriendlySubThreat >= 20000) and ((tWZTeamData[AiBotMap.subrefWZThreatAlliedSubmersible] or 0) * 0.8 + iCurZoneAndAdjacentAlliedSubmersibleThreat >= 40000 or ((tWZTeamData[AiBotMap.subrefWZThreatAlliedSubmersible] or 0) * 0.8 + iCurZoneAndAdjacentAlliedSubmersibleThreat > ((tWZTeamData[AiBotMap.subrefWZThreatEnemyAntiNavy] or 0) + iAdjacentEnemyAntiNavyThreat) * iEnemyAntiNavyMod or (iCurZoneAndAdjacentAlliedSubmersibleThreat + (tWZTeamData[AiBotMap.subrefWZThreatAlliedSubmersible] or 0) * 0.8 > (tWZTeamData[AiBotMap.subrefWZThreatEnemyAntiNavy] or 0) + iAdjacentEnemyAntiNavyThreat and iAdjacentAlliedCombatThreat > iAdjacentEnemyCombatThreat * iEnemyCombatModHigh)))) or
                --Surface level consideration - want tobe similar to sub so we dont end up attacking with subs and not surface if reason for attacking with subs is our surface threat
                (not(bConsideringSubmarinesNotSurface) and ((iAdjacentAlliedCombatThreat - iCurZoneAndAdjacentAlliedSubmersibleThreat) > iAdjacentEnemyCombatThreat * iEnemyCombatModHigh or (tWZTeamData[AiBotMap.subrefWZTThreatAllyCombatTotal] + (iCommonZoneTargetSurfaceThreat or 0) - iCurZoneAndAdjacentAlliedSubmersibleThreat) > iAdjacentEnemyCombatThreat * iEnemyCombatModLow))  then
            if bDebugMessages == true then LOG(sFunctionRef..': Main scenario 2 condition satisfied') end
            bAreInScenario2 = true
        elseif tWZTeamData[AiBotMap.subrefWZbCoreBase] then
            --Consider attacking if naval fac is vulnerable, or we have slightly more threat
            if  iAdjacentAlliedCombatThreat > iAdjacentEnemyCombatThreat then
                if bDebugMessages == true then LOG(sFunctionRef..': We have significantly more threat than enemy so want to attack') end
                bAreInScenario2 = true
            else
                --Are in core zone, and have enemies either in this zone ro an adjacent one that are in range of our naval fac; if enemies are in this zone still attack; if they are in adjacent zone then only attack if nearest enemy is almost in range of our naval fac
                if AiBotUtilities.IsTableEmpty(tWZTeamData[AiBotMap.reftoNearestCombatEnemies]) == false then
                    --check if are close to being in range of our naval factory

                    local tFriendlyNavalFac
                    if tWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits] == false then tFriendlyNavalFac = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryNavalFactory, tWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) end
                    if bDebugMessages == true then LOG(sFunctionRef..': Is tWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits] empty='..tostring(AiBotUtilities.IsTableEmpty(tWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]))..'; Is tFriendlyNavalFac empty='..tostring(AiBotUtilities.IsTableEmpty(tFriendlyNavalFac))..'; refbHostileImmobileCombatCiviliansInZone='..tostring(tWZTeamData[AiBotMap.refbHostileImmobileCombatCiviliansInZone])..'; bNearbyEnemiesAreHostileCivilians='..tostring(bNearbyEnemiesAreHostileCivilians or false)) end
                    --Only consider if we have no naval fac if enemy doesnt have significantly larger threat
                    if AiBotUtilities.IsTableEmpty(tFriendlyNavalFac) then
                        if ((bConsideringSubmarinesNotSurface and (iNearbyFriendlySubThreat >= iAdjacentEnemyAntiNavyThreat * 0.8 or iNearbyFriendlySubThreat >= 10000) and (iCurZoneAndAdjacentAlliedSubmersibleThreat >= 20000 or iCurZoneAndAdjacentAlliedSubmersibleThreat > ((tWZTeamData[AiBotMap.subrefWZThreatEnemyAntiNavy] or 0) + iAdjacentEnemyAntiNavyThreat) * math.min(0.8, iEnemyAntiNavyMod))) or
                                --Surface level consideration - want tobe similar to sub so we dont end up attacking with subs and not surface if reason for attacking with subs is our surface threat
                                (not(bConsideringSubmarinesNotSurface) and ((iAdjacentAlliedCombatThreat - iCurZoneAndAdjacentAlliedSubmersibleThreat) > iAdjacentEnemyCombatThreat * math.min(0.8, iEnemyCombatModHigh) or (tWZTeamData[AiBotMap.subrefWZTThreatAllyCombatTotal] + (iCommonZoneTargetSurfaceThreat or 0) - iCurZoneAndAdjacentAlliedSubmersibleThreat) > iAdjacentEnemyCombatThreat * math.min(0.8, iEnemyCombatModLow)))) then
                            --Greater search range as dont know how close to midpoint the naval fac build location would be
                            local tEnemyUnitsToConsider
                            if bNearbyEnemiesAreHostileCivilians or tWZTeamData[AiBotMap.refbHostileImmobileCombatCiviliansInZone] then
                                tEnemyUnitsToConsider = {}
                                for iEnemy, oEnemy in tWZTeamData[AiBotMap.reftoNearestCombatEnemies] do
                                    if not(oEnemy[AiBotUnitInfo.refbHostileImmobileCivilian]) then
                                        table.insert(tEnemyUnitsToConsider, oEnemy)
                                    end
                                end
                            else
                                tEnemyUnitsToConsider = tWZTeamData[AiBotMap.reftoNearestCombatEnemies]
                            end
                            if AiBotUtilities.IsTableEmpty(tEnemyUnitsToConsider) then
                                if tWZTeamData[AiBotMap.refbHostileImmobileCombatCiviliansInZone] then tWZTeamData[AiBotMap.refbHostileImmobileCombatCiviliansInZone] = false end
                            elseif CloseToEnemyUnit(tWZData[AiBotMap.subrefMidpoint], tEnemyUnitsToConsider, 30, iTeam, true) then
                                if bDebugMessages == true then LOG(sFunctionRef..': Enemy has units almost in range of our core zone midpoint so will attack') end
                                bAreInScenario2 = true
                            end
                        else
                            if bDebugMessages == true then LOG(sFunctionRef..': We lack a naval factory, and enemy has significantly greater threat, so wont attack') end
                        end
                    else
                        --Cycle through each naval fac and see if enemy is close
                        local tEnemyUnitsToConsider
                        if bNearbyEnemiesAreHostileCivilians or tWZTeamData[AiBotMap.refbHostileImmobileCombatCiviliansInZone] then
                            tEnemyUnitsToConsider = {}
                            for iEnemy, oEnemy in tWZTeamData[AiBotMap.reftoNearestCombatEnemies] do
                                if not(oEnemy[AiBotUnitInfo.refbHostileImmobileCivilian]) then
                                    table.insert(tEnemyUnitsToConsider, oEnemy)
                                end
                            end
                        else
                            tEnemyUnitsToConsider = tWZTeamData[AiBotMap.reftoNearestCombatEnemies]
                        end
                        if AiBotUtilities.IsTableEmpty(tEnemyUnitsToConsider) then
                            if tWZTeamData[AiBotMap.refbHostileImmobileCombatCiviliansInZone] then tWZTeamData[AiBotMap.refbHostileImmobileCombatCiviliansInZone] = false end
                        else
                            for iNavalFac, oNavalFac in tFriendlyNavalFac do
                                if CloseToEnemyUnit(oNavalFac:GetPosition(), tEnemyUnitsToConsider, 15, iTeam, true) then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Enemy has units almost in range of our naval fac so will attack') end
                                    bAreInScenario2 = true
                                    break
                                end
                            end
                        end
                    end
                end
            end

        end
    end
    if bAreInScenario2 and not(bConsideringSubmarinesNotSurface) then
        --Adjust if enemy has significant submersible threat and we dont have enough antinavy threat, or if enemy has nearby firebase and we dont have a decent force
        if iEnemyNearbySubmersibleThreat > iAvailableAntiNavyThreat and iEnemyNearbySubmersibleThreat * 5 > iAdjacentAlliedCombatThreat and (iEnemyNearbySubmersibleThreat > 500 or iEnemyNearbySubmersibleThreat * 2 > iAdjacentAlliedCombatThreat) then
            bAreInScenario2 = false
        elseif AiBotUtilities.IsTableEmpty(tWZTeamData[AiBotMap.subreftEnemyFirebasesInRange]) == false then
            if AiBotUtilities.IsTableEmpty(tWZTeamData[AiBotMap.subreftEnemyFirebasesInRange]) == false and math.max(iAdjacentAlliedCombatThreat, (iCommonZoneTargetSurfaceThreat or 0)) + tWZTeamData[AiBotMap.subrefWZTThreatAllyCombatTotal] <= 6000 and tWZTeamData[AiBotMap.subrefWZBestAlliedDFRange] < 100 then
                bAreInScenario2 = false
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return bAreInScenario2
end


--NOTE: REFER TO GetNumberOfUnitsMeetingCategoryUnderConstructionInLandOrWaterZone(tLZTeamData, iCategoryWanted, bAllConstructionNotFactory) WHICH IS MORE VERSATILE
function GetNumberOfUnitsCurrentlyBeingBuiltOfCategoryInZone(tLZTeamData, iCategory)

    local iCount = 0
    if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then
        local tFactories = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryFactory,tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
        if AiBotUtilities.IsTableEmpty(tFactories) == false then
            local sBeingBuilt
            for iFactory, oFactory in tFactories do
                sBeingBuilt = oFactory[AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefsOrderBlueprint]
                if sBeingBuilt and EntityCategoryContains(iCategory, sBeingBuilt) then
                    if AiBotUnitInfo.IsUnitValid(oFactory) and oFactory.GetWorkProgress then
                        if oFactory:GetWorkProgress() > 0 or AiBotUnitInfo.IsUnitValid(oFactory:GetFocusUnit()) then
                            iCount = iCount + 1
                        end
                    end
                end
            end
        end
    end
    return iCount

end

function IsNearbyStructureThatWeCanReachWithIndirect(tLZData, tLZTeamData, iTeam)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'IsNearbyStructureThatWeCanReachWithIndirect'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local bWantIndirectReinforcements = false

    local iAngleToMidpoint = AiBotUtilities.GetAngleFromAToB(tLZTeamData[AiBotMap.refoNearestStructureInOtherPlateauIfNoEnemiesHere]:GetPosition(), tLZData[AiBotMap.subrefMidpoint])
    local iDistToMidpoint = AiBotUtilities.GetDistanceBetweenPositions(tLZTeamData[AiBotMap.refoNearestStructureInOtherPlateauIfNoEnemiesHere]:GetPosition(), tLZData[AiBotMap.subrefMidpoint])
    local tMoveTowardsMidpoint = AiBotUtilities.MoveInDirection(tLZTeamData[AiBotMap.refoNearestStructureInOtherPlateauIfNoEnemiesHere]:GetPosition(), iAngleToMidpoint, math.min(70, iDistToMidpoint), false, false, false)
    local iCurLZIslandRef = tLZData[AiBotMap.subrefLZIslandRef]
    if not(iCurLZIslandRef) then
        iCurLZIslandRef = NavUtils.GetLabel(AiBotMap.refPathingTypeLand, tLZData[AiBotMap.subrefMidpoint]) --We dont record island refs for all plateaus hence the redundancy
        if iCurLZIslandRef then tLZData[AiBotMap.subrefLZIslandRef] = iCurLZIslandRef end
    end

    if bDebugMessages == true then LOG(sFunctionRef..': Nearest structure='..tLZTeamData[AiBotMap.refoNearestStructureInOtherPlateauIfNoEnemiesHere].UnitId..AiBotUnitInfo.GetUnitLifetimeCount(tLZTeamData[AiBotMap.refoNearestStructureInOtherPlateauIfNoEnemiesHere])..' at position '..repru(tLZTeamData[AiBotMap.refoNearestStructureInOtherPlateauIfNoEnemiesHere]:GetPosition())..'; This LZ midpoint='..repru(tLZData[AiBotMap.subrefMidpoint])..'; iAngleToMidpoint='..iAngleToMidpoint..'; iDistToMidpoint='..iDistToMidpoint..'; tMoveTowardsMidpoint='..repru(tMoveTowardsMidpoint)..'; Island pathing of tMoveTowardsMidpoint='..(NavUtils.GetLabel(AiBotMap.refPathingTypeLand, tMoveTowardsMidpoint) or -1)..'; Island ref of LZ='..(tLZData[AiBotMap.subrefLZIslandRef] or 'nil')..'; iCurLZIslandRef='..(iCurLZIslandRef or 'nil')) end
    if (NavUtils.GetLabel(AiBotMap.refPathingTypeLand, tMoveTowardsMidpoint) or -1) == iCurLZIslandRef then
        --Can we build T3 mobile arti?
        if not(AiBotMap.bIsCampaignMap or AiBotOverseer.bUnitRestrictionsArePresent) then
            bWantIndirectReinforcements = true
        else
            --local oFirstAiBotBrain = AiBotTeam.GetFirstActiveAiBotBrain(iTeam)
            if ArmyBrains[tLZTeamData[AiBotMap.reftiClosestFriendlyAiBotBrainIndex]].GetCurrentUnits and ArmyBrains[tLZTeamData[AiBotMap.reftiClosestFriendlyAiBotBrainIndex]]:GetCurrentUnits(AiBotUnitInfo.refCategoryIndirect * categories.TECH3) > 0 then
                bWantIndirectReinforcements = true
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': bWantIndirectReinforcements after checking for nearby structure='..tostring(bWantIndirectReinforcements)) end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return bWantIndirectReinforcements
end

function GetNumberOfUnderConstructionUnitsOfCategoryInOtherCoreZones(tLZTeamData, iTeam, iCategory, iOptionalMinConstruction)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'GetNumberOfUnderConstructionUnitsOfCategoryInOtherCoreZones'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local iUnderConstructionInOtherZones = 0
    local tUnitsOfCategory
    for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains] do
        local tStartLZData, tStartLZTeamData = AiBotMap.GetLandOrWaterZoneData(AiBotMap.PlayerStartPoints[oBrain:GetArmyIndex()], true, iTeam)
        if not(tStartLZTeamData == tLZTeamData) then
            if AiBotUtilities.IsTableEmpty(tStartLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then
                tUnitsOfCategory = EntityCategoryFilterDown(iCategory, tStartLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                if bDebugMessages == true then LOG(sFunctionRef..': Is table of units of cateogyr empty for brain '..oBrain.Nickname..'='..tostring(AiBotUtilities.IsTableEmpty(tUnitsOfCategory))) end
                if AiBotUtilities.IsTableEmpty(tUnitsOfCategory) == false then
                    for iUnit, oUnit in tUnitsOfCategory do
                        if AiBotUnitInfo.IsUnitValid(oUnit) and oUnit:GetAIBrain().AiBotAI and oUnit:GetFractionComplete() < 1 then
                            if not(iOptionalMinConstruction) or oUnit:GetFractionComplete() >= iOptionalMinConstruction then
                                iUnderConstructionInOtherZones = iUnderConstructionInOtherZones + 1
                            end
                        end
                    end
                end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return iUnderConstructionInOtherZones
end

function GetEnemyOmniCoverageOfZone(iPlateauOrZero, iLandOrWaterZone, iTeam)
    local tLZOrWZData
    if iPlateauOrZero == 0 then

        tLZOrWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iLandOrWaterZone]][AiBotMap.subrefPondWaterZones][iLandOrWaterZone]
    else tLZOrWZData = AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iLandOrWaterZone]
    end
    local iEnemyOmniCoverage = 0
    if (tLZOrWZData[AiBotMap.refiAllOmniCoverage] or 0) > 0 then
        local iCurOmniCoverage = 0
        if IsTableOfUnitsStillValid(tLZOrWZData[AiBotMap.reftoAllOmniRadar]) then
            for iUnit, oUnit in tLZOrWZData[AiBotMap.reftoAllOmniRadar] do
                if not(oUnit:GetAIBrain().AiBotTeam == iTeam) then
                    iCurOmniCoverage = (oUnit:GetBlueprint().Intel.OmniRadius or 0) - AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tLZOrWZData[AiBotMap.subrefMidpoint])
                    if iCurOmniCoverage > iEnemyOmniCoverage then
                        iEnemyOmniCoverage = iCurOmniCoverage
                    end
                end
            end
        else
            tLZOrWZData[AiBotMap.refiAllOmniCoverage] = 0
        end
    end
    return iEnemyOmniCoverage
end

function GetEnemyT3ArtiEquivalent(iTeam, iNovaxFactor, iNonArtiGameEnderFactor, bApplyFractionComplete, iOptionalMinFractionComplete)
    local iT3ArtiEquivalent = 0
    local iBaseValue
    if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyArtiAndExpStructure]) == false then
        if IsTableOfUnitsStillValid(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyArtiAndExpStructure], false) then
            for iUnit, oUnit in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyArtiAndExpStructure] do
                iBaseValue = 0
                if EntityCategoryContains(AiBotUnitInfo.refCategoryFixedT3Arti, oUnit.UnitId) then
                    iBaseValue = 1
                elseif EntityCategoryContains(AiBotUnitInfo.refCategoryNovaxCentre, oUnit.UnitId) then
                    iBaseValue = iNovaxFactor
                elseif EntityCategoryContains(categories.ARTILLERY * categories.EXPERIMENTAL, oUnit.UnitId) then
                    iBaseValue = 3
                elseif EntityCategoryContains(AiBotUnitInfo.refCategoryGameEnder, oUnit.UnitId) then
                    iBaseValue = iNonArtiGameEnderFactor
                end
                if iBaseValue > 0 then
                    if not(iOptionalMinFractionComplete) or oUnit:GetFractionComplete() >= iOptionalMinFractionComplete then
                        if bApplyFractionComplete then iT3ArtiEquivalent = iT3ArtiEquivalent + iBaseValue * oUnit:GetFractionComplete()
                        else iT3ArtiEquivalent = iT3ArtiEquivalent + iBaseValue
                        end
                    end
                end
            end
        end
    end
    if IsTableOfUnitsStillValid(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyMobileSatellites]) then
        local iNovaxCount = 0
        for iUnit, oUnit in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyMobileSatellites] do
            iNovaxCount = iNovaxCount + 1
        end
        iT3ArtiEquivalent = math.max(iT3ArtiEquivalent, iNovaxCount * iNovaxFactor)
    end
    return iT3ArtiEquivalent
end

function GetMexesNotNearPlayerStartingZone()
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'GetMexesNotNearPlayerStartingZone'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local iMexesNotInStartZone = 0
    if bDebugMessages == true then LOG(sFunctionRef..': is table of mass poitns empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotMap.tMassPoints))) end
    if AiBotUtilities.IsTableEmpty(AiBotMap.tMassPoints) == false then
        if bDebugMessages == true then LOG(sFunctionRef..': Total mass points='..table.getn(AiBotMap.tMassPoints)..'; AiBotMap.PlayerStartPoints='..repru(AiBotMap.PlayerStartPoints)) end
        local tbStartPointPlateauAndZones = {}
        local iCurPlateauOrZero, iCurLandOrWaterZone
        for iIndex, tStartPoint in AiBotMap.PlayerStartPoints do
            iCurPlateauOrZero, iCurLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(tStartPoint)
            if not(tbStartPointPlateauAndZones[iCurPlateauOrZero]) then tbStartPointPlateauAndZones[iCurPlateauOrZero] = {} end
            tbStartPointPlateauAndZones[iCurPlateauOrZero][iCurPlateauOrZero] = true
            if bDebugMessages == true then LOG(sFunctionRef..': recording start point for index '..iIndex..'; tStartPoint='..repru(tStartPoint)) end
        end

        for iMex, tMex in AiBotMap.tMassPoints do
            iCurPlateauOrZero, iCurLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(tMex)
            if bDebugMessages == true then LOG(sFunctionRef..': Considering tMex='..repru(tMex)..'; tbStartPointPlateauAndZones[iCurPlateauOrZero][iCurPlateauOrZero]='..tostring(tbStartPointPlateauAndZones[iCurPlateauOrZero][iCurPlateauOrZero] or false)) end
            if not(tbStartPointPlateauAndZones[iCurPlateauOrZero][iCurLandOrWaterZone]) then
                iMexesNotInStartZone = iMexesNotInStartZone + 1
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return iMexesNotInStartZone
end

function GetNearbyACUForAirFacBomberSnipe(oFactory, iTeam)
    if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.toActiveSnipeTargets]) == false then
        for iACU, oACU in AiBotTeam.tTeamData[iTeam][AiBotTeam.toActiveSnipeTargets] do
            if AiBotUnitInfo.IsUnitValid(oACU) and (oACU[AiBotUnitInfo.refiRecentBomberSnipeAttempts] or 0) == 0 then
                return oACU
            end
        end
    end
end

function BrainIsUpgradingNavalHQ(aiBrain)
    if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.subreftTeamUpgradingHQs]) == false then
        for iUpgrading, oUpgrading in AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.subreftTeamUpgradingHQs] do
            if not(oUpgrading.Dead) and oUpgrading:GetAIBrain() == aiBrain and EntityCategoryContains(AiBotUnitInfo.refCategoryNavalHQ, oUpgrading.UnitId) then
                return true
            end
        end
    end
    return false
end

function CheckIfNeedMoreEngineersOrSnipeUnitsBeforeUpgrading(oFactory)
    --Returns true if we want more engineers (e.g. for more power or nearby unclaimed mexes) before upgrading
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'CheckIfNeedMoreEngineersOrSnipeUnitsBeforeUpgrading'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    local bWantMoreEngineers = false
    oFactory[AiBotFactory.refbWantMoreEngineersBeforeUpgrading] = false

    if EntityCategoryContains(AiBotUnitInfo.refCategoryFactory,oFactory.UnitId) then
        local iFactoryTechLevel = AiBotUnitInfo.GetUnitTechLevel(oFactory)
        if bDebugMessages == true then LOG(sFunctionRef..': Considering factory '..oFactory.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oFactory)..'; Total build count='..(oFactory[AiBotFactory.refiTotalBuildCount] or 0)..'; iFactoryTechLevel='..iFactoryTechLevel..'; Time='..GetGameTimeSeconds()) end
        local aiBrain = oFactory:GetAIBrain()
        if not(aiBrain[AiBotOverseer.refbCloseToUnitCap]) and iFactoryTechLevel < 3 then
            local iTeam = aiBrain.AiBotTeam
            local tLZOrWZData, tLZOrWZTeamData = AiBotMap.GetLandOrWaterZoneData(oFactory:GetPosition(), true, iTeam)
            if tLZOrWZTeamData[AiBotMap.subrefLZFortify] and iFactoryTechLevel < 2 and AiBotMap.bIsCampaignMap then
                if bDebugMessages == true then LOG(sFunctionRef..': Campaign where we want to fortify zone so want to upgrade asap to T2') end
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                return false
            end
            local iBuildCountAdjust = 0
            if iFactoryTechLevel == 2 then

                --Want to build more units at a T2 factory if we outtech the enemy, unless dealing with air fac in a safe location
                if bDebugMessages == true then LOG(sFunctionRef..': T2 factory - build more units if we outtech enemy, unless air fac in safe location, Highest friendly fac tech='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]..'; Map size='..AiBotMap.iMapSize..'; Enemy ground tech='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyGroundTech]..'; Enemy air tech='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyAirTech]..'; Enemy naval tech='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyNavyTech]) end
                if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] <= 2 and AiBotMap.iMapSize <= 1000 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] > math.max(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyGroundTech], AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyAirTech], AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyNavyTech]) then
                    --We outtech enemy and have decent mass and power, so want more factories to make use of our advantage, if enemy base is relatively near
                    if AiBotUtilities.GetDistanceBetweenPositions(tLZOrWZTeamData[AiBotMap.reftClosestEnemyBase], tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase]) <= 550 and NavUtils.GetTerrainLabel(tLZOrWZTeamData[AiBotMap.reftClosestEnemyBase]) == NavUtils.GetTerrainLabel(tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase]) then
                        if not(tLZOrWZTeamData[AiBotMap.refbBaseInSafePosition]) or (AiBotMap.iMapSize <= 512 and not(EntityCategoryContains(AiBotUnitInfo.refCategoryAirFactory, oFactory.UnitId))) then
                            if bDebugMessages == true then LOG(sFunctionRef..': Increasing units want to build by 4') end
                            iBuildCountAdjust = 4
                        end
                    end
                end
                --Also want to build more units if we want production over tech
                if AiBotTeam.tAirSubteamData[aiBrain.AiBotAirSubteam][AiBotTeam.refbNoAvailableTorpsForEnemies] then
                    if bDebugMessages == true then LOG(sFunctionRef..': Want torp bombers so increasing number of units to build') end
                    iBuildCountAdjust = iBuildCountAdjust + 10
                end
            end
            if aiBrain[AiBotOverseer.refbPrioritiseLowTech] then iBuildCountAdjust = iBuildCountAdjust + math.max(10, iBuildCountAdjust * 0.5)
            elseif aiBrain[AiBotOverseer.refbPrioritiseHighTech] then iBuildCountAdjust = iBuildCountAdjust - math.max(5, math.min(10, iBuildCountAdjust * 0.5))
            end
            --Naval fac and this brain doesnt have any upgrading to T2 yet, and enemy has torps or T2 navy
            if EntityCategoryContains(AiBotUnitInfo.refCategoryNavalFactory, oFactory.UnitId) and iFactoryTechLevel == 1 then
                local bUpgradingHQForBrain = false
                local bUpgradingNavalHQForBrain = false
                if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftTeamUpgradingHQs]) == false then
                    for iHQ, oHQ in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftTeamUpgradingHQs] do
                        if AiBotUnitInfo.IsUnitValid(oHQ) and oHQ:GetAIBrain() == aiBrain then
                            if EntityCategoryContains(AiBotUnitInfo.refCategoryNavalFactory, oHQ.UnitId) then
                                bUpgradingHQForBrain = true
                                bUpgradingNavalHQForBrain = true
                            elseif AiBotUnitInfo.GetUnitTechLevel(oHQ) <= iFactoryTechLevel then
                                bUpgradingHQForBrain = true
                            end

                        end
                    end
                end
                if bDebugMessages == true then LOG(sFunctionRef..': bUpgradingHQForBrain='..tostring(bUpgradingHQForBrain)..'; bUpgradingNavalHQForBrain='..tostring(bUpgradingNavalHQForBrain)) end
                if not(bUpgradingHQForBrain) or (not(bUpgradingNavalHQForBrain) and not(HaveLowMass(aiBrain)) and not(HaveLowPower(aiBrain.AiBotTeam)))  then
                    if AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyTorpBombersThreat] > 0 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyNavyTech] > iFactoryTechLevel then
                        iBuildCountAdjust = iBuildCountAdjust - math.max(20, iBuildCountAdjust * 0.5)
                    else
                        iBuildCountAdjust = iBuildCountAdjust - math.max(10, iBuildCountAdjust * 0.25)
                    end
                elseif not(bUpgradingNavalHQForBrain) and (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyTorpBombersThreat] > 0 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyNavyTech] > iFactoryTechLevel) then
                    iBuildCountAdjust = iBuildCountAdjust - math.max(8,  iBuildCountAdjust * 0.2)
                end
                if bDebugMessages == true then LOG(sFunctionRef..': Naval fac, bUpgradingHQForBrain='..tostring(bUpgradingHQForBrain)..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyTorpBombersThreat]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyTorpBombersThreat]..'; iBuildCountAdjust='..iBuildCountAdjust) end
            end

            if (oFactory[AiBotFactory.refiTotalBuildCount] or 0) <= 25 - iFactoryTechLevel * 5 + iBuildCountAdjust or ((oFactory[AiBotFactory.refiTotalBuildCount] or 0) <= 30 + iBuildCountAdjust and GetLifetimeBuildCount(oFactory:GetAIBrain(), AiBotUnitInfo.refCategoryEngineer * AiBotUnitInfo.ConvertTechLevelToCategory(iFactoryTechLevel)) <= math.max(5, aiBrain[AiBotEconomy.refiGrossMassBaseIncome] * 3 / iFactoryTechLevel) + iBuildCountAdjust) then
                if bDebugMessages == true then LOG(sFunctionRef..': iTeam='..iTeam..'; Brain='..aiBrain.Nickname..'; Want BP='..tostring(tLZOrWZTeamData[AiBotMap.subrefTbWantBP] or false)..'; Engineer lifetime build count for brain='..GetLifetimeBuildCount(aiBrain, AiBotUnitInfo.refCategoryEngineer)..'; Mexes in zone='..(tLZOrWZData[AiBotMap.subrefLZOrWZMexCount] or 0)) end
                if tLZOrWZTeamData[AiBotMap.subrefTbWantBP] then
                    --If are in core zone and T1 and have T3 of this factory type, then just upgrade
                    if not(iFactoryTechLevel == 1 and tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase] and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] >= 3 and ((EntityCategoryContains(AiBotUnitInfo.refCategoryLandFactory, oFactory.UnitId) and aiBrain[AiBotEconomy.refiOurHighestLandFactoryTech] >= 3) or (EntityCategoryContains(AiBotUnitInfo.refCategoryAirFactory, oFactory.UnitId) and aiBrain[AiBotEconomy.refiOurHighestAirFactoryTech] >= 3))) then

                        --Do we have enough energy?
                        local tiMinEnergyByTech = {[0]=20,[1]=20,[2]=60,[3]=60,[4]=90}
                        local iMinEnergyWanted = (tiMinEnergyByTech[iFactoryTechLevel] or 60)
                        local bHaveLowPower = HaveLowPower(iTeam)
                        local bHaveLowMass = HaveLowMass(aiBrain)

                        if not(EntityCategoryContains(AiBotUnitInfo.refCategoryLandFactory, oFactory.UnitId)) then iMinEnergyWanted = iMinEnergyWanted * 2 end
                        iMinEnergyWanted = iMinEnergyWanted * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] *  (aiBrain[AiBotEconomy.refiBrainBuildRateMultiplier] or 1)
                        if bHaveLowPower and not(bHaveLowMass) and aiBrain:GetEconomyStoredRatio('MASS') >= 0.3 then
                            iMinEnergyWanted = iMinEnergyWanted * 1.5
                            if aiBrain:GetEconomyStoredRatio('MASS') >= 0.6 then iMinEnergyWanted = iMinEnergyWanted * 1.5 end
                        end
                        if tLZOrWZTeamData[AiBotMap.refbBaseInSafePosition] and EntityCategoryContains(AiBotUnitInfo.refCategoryAirFactory, oFactory.UnitId) then
                            if iFactoryTechLevel == 1 and aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome] >= 45 then
                                iMinEnergyWanted = iMinEnergyWanted * 0.6
                            elseif iFactoryTechLevel == 2 and aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome] >= 90 then
                                iMinEnergyWanted = iMinEnergyWanted * 0.6
                            else
                                iMinEnergyWanted = iMinEnergyWanted * 0.85
                            end
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': iMinEnergyWanted='..iMinEnergyWanted..'; Gross energy='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy]..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy]='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy] or false)..'; tLZOrWZTeamData[AiBotMap.refbAdjZonesWantEngiForUnbuiltMex]='..tostring(tLZOrWZTeamData[AiBotMap.refbAdjZonesWantEngiForUnbuiltMex] or false)..'; T2 engi lifetime count='..GetLifetimeBuildCount(aiBrain, AiBotUnitInfo.refCategoryEngineer * categories.TECH2)..'; Mass gross income='..aiBrain[AiBotEconomy.refiGrossMassBaseIncome]) end
                        if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] < iMinEnergyWanted or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy] or (iFactoryTechLevel == 2 and aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome] <= 150 and aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryT2Power + AiBotUnitInfo.refCategoryT3Power) == 0) or (bHaveLowPower and not(bHaveLowMass) and aiBrain:GetEconomyStoredRatio('MASS') >= 0.3 and GetLifetimeBuildCount(aiBrain, AiBotUnitInfo.refCategoryEngineer * AiBotUnitInfo.ConvertTechLevelToCategory(iFactoryTechLevel) + AiBotUnitInfo.refCategoryEngineer*categories.TECH3) < iBuildCountAdjust + math.min(12, math.max(4, aiBrain[AiBotEconomy.refiGrossMassBaseIncome] * 1.5))) then
                            AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTooLittleEnergyForUpgrade] = true
                            if bDebugMessages == true then LOG(sFunctionRef..': Dont have enough power to upgrade') end
                            bWantMoreEngineers = true
                        elseif tLZOrWZTeamData[AiBotMap.refbAdjZonesWantEngiForUnbuiltMex] then
                            if bDebugMessages == true then LOG(sFunctionRef..': Have adj zones wanting engineer for mex') end
                            bWantMoreEngineers = true
                        elseif (oFactory[AiBotFactory.refiTotalBuildCount] or 0) <= iBuildCountAdjust + 10 then

                            local iMinBuildCountWanted = iBuildCountAdjust
                            local iOurHighestTech = 1
                            if GetGameTimeSeconds() - (oFactory[AiBotFactory.refiTimeSinceLastFailedToGetOrder] or -100) <= 1 then
                                if bDebugMessages == true then LOG(sFunctionRef..': Recently failed to get order so dont want to wait to build more units') end
                                iMinBuildCountWanted = 0
                            else

                                if EntityCategoryContains(AiBotUnitInfo.refCategoryAirFactory, oFactory.UnitId) then
                                    if not(tLZOrWZTeamData[AiBotMap.refbBaseInSafePosition]) or tLZOrWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] > 10 or tLZOrWZTeamData[AiBotMap.refiEnemyAirToGroundThreat] > 0 then
                                        if iFactoryTechLevel >= iOurHighestTech then
                                            iOurHighestTech = aiBrain[AiBotEconomy.refiOurHighestAirFactoryTech]
                                            iMinBuildCountWanted = iMinBuildCountWanted + 1
                                            if tLZOrWZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ] then iMinBuildCountWanted = iMinBuildCountWanted + 5 end
                                            if bDebugMessages == true then LOG(sFunctionRef..': Highest air fac tech so increasing build count min wanted') end
                                        elseif tLZOrWZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ] then
                                            if bDebugMessages == true then LOG(sFunctionRef..': Enemies in adj LZ so increasing build count wanted') end
                                            iMinBuildCountWanted = iMinBuildCountWanted + 2
                                        end
                                    end
                                elseif EntityCategoryContains(AiBotUnitInfo.refCategoryLandFactory, oFactory.UnitId) then
                                    iOurHighestTech = aiBrain[AiBotEconomy.refiOurHighestLandFactoryTech]
                                    if iFactoryTechLevel >= iOurHighestTech then   iMinBuildCountWanted = iMinBuildCountWanted + 5 end
                                    if tLZOrWZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ] then iMinBuildCountWanted = iMinBuildCountWanted + 5 end
                                elseif EntityCategoryContains(AiBotUnitInfo.refCategoryNavalFactory, oFactory.UnitId) then
                                    iOurHighestTech = aiBrain[AiBotEconomy.refiOurHighestNavalFactoryTech]
                                    iMinBuildCountWanted = iMinBuildCountWanted + 3
                                end
                            end
                            if bDebugMessages == true then LOG(sFunctionRef..': iMinBuildCountWanted='..iMinBuildCountWanted..'; iBuildCountAdjust='..iBuildCountAdjust..'; Lifetime engi count='..GetLifetimeBuildCount(aiBrain, AiBotUnitInfo.refCategoryEngineer)..'; iOurHighestTech (if we calculated it)='..iOurHighestTech) end
                            if (oFactory[AiBotFactory.refiTotalBuildCount] or 0) < iMinBuildCountWanted then
                                bWantMoreEngineers = true
                            elseif GetLifetimeBuildCount(aiBrain, AiBotUnitInfo.refCategoryEngineer) <= ((tLZOrWZData[AiBotMap.subrefLZOrWZMexCount] or 0) + 1) * 1.5 then
                                bWantMoreEngineers = true
                            end
                        end
                    end
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': For larger maps on LOUD/QUIET will consider override to delay upgrade, bWantMoreEngineers='..tostring(bWantMoreEngineers)..'; LOUD active='..tostring(AiBotUtilities.bLoudModActive)..'; Map size='..AiBotMap.iMapSize) end
            --Redundancy for if we lost our HQ - if we have rebuilt with t3 mexes then want to be upgrading factories asap
            if tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][3] > 0 and (oFactory[AiBotFactory.refiTotalBuildCount] or 0) >= 3 and (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] > 0 or AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyLandExperimentals]) == false or AiBotTeam.tTeamData[iTeam][AiBotTeam.refbEnemyHasHeavyLandT3] or AiBotTeam.tTeamData[iTeam][AiBotTeam.iEnemyT3MAAActiveCount] >= 2) then
                bWantMoreEngineers = false
                if bDebugMessages == true then LOG(sFunctionRef..': Have t3 mex and either we or opponent has experimental, and factory has built a few units') end
            elseif not(bWantMoreEngineers) and (AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive) and not(aiBrain[AiBotOverseer.refbPrioritiseHighTech]) then
                --LOUD favours slightly slower upgrades in favour of getting more mexes, so aim to have at least 3 mexes of a higher tech level first
                local bWantMoreMexes = true
                local iLifetimeCount = math.min(4, AiBotUnitInfo.GetUnitLifetimeCount(oFactory))
                if oFactory[AiBotFactory.refiTotalBuildCount] >= 60 + iBuildCountAdjust then
                    bWantMoreMexes = false
                elseif iFactoryTechLevel == 1 and (tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][3] > 0 or (tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][2] >= math.min(3, (tLZOrWZData[AiBotMap.subrefLZOrWZMexCount] or 0)) and (tLZOrWZData[AiBotMap.subrefLZOrWZMexCount] >= 2 + iLifetimeCount or aiBrain[AiBotEconomy.refiGrossMassBaseIncome] >= 6 + iLifetimeCount))) then
                    bWantMoreMexes = false
                elseif tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][3] >= math.min(3, (tLZOrWZData[AiBotMap.subrefLZOrWZMexCount] or 0)) and (tLZOrWZData[AiBotMap.subrefLZOrWZMexCount] >= 2 + iLifetimeCount or aiBrain[AiBotEconomy.refiGrossMassBaseIncome] >= 10 + 2 * iLifetimeCount) then
                    bWantMoreMexes = false
                    --Cases where enemy has better tech than us, and we have the highest tech
                elseif tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase] and iFactoryTechLevel >= aiBrain[AiBotEconomy.refiOurHighestFactoryTechLevel] and aiBrain[AiBotEconomy.refiOurHighestFactoryTechLevel] < AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyGroundTech] and (AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subreftoActiveUpgrades]) or AiBotUtilities.IsTableEmpty(EntityCategoryContains(AiBotUnitInfo.refCategoryFactory * AiBotUnitInfo.ConvertTechLevelToCategory(iFactoryTechLevel), tLZOrWZTeamData[AiBotMap.subreftoActiveUpgrades]))) and
                        ((iFactoryTechLevel == 2 and tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][3] >= 1 and (tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][3] >= 2 or aiBrain[AiBotEconomy.refiGrossMassBaseIncome] >= 10)) or
                                (iFactoryTechLevel == 1 and (tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][3] >= 1 or tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][2] >= 3))) then
                    bWantMoreMexes = false
                    if bDebugMessages == true then LOG(sFunctionRef..': ENemy has better tech than us so want to upgrade even if we dont have as many mexes as we would like') end
                elseif iFactoryTechLevel == 1 and AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftTeamUpgradingHQs]) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] == 1 and aiBrain[AiBotEconomy.refiGrossMassBaseIncome] >= 6 and aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome] >= 100 and oFactory[AiBotFactory.refiTotalBuildCount] >= 15 and (aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome] >= 120 or aiBrain[AiBotEconomy.refiGrossMassBaseIncome] >= 8) then
                    if bDebugMessages == true then LOG(sFunctionRef..': We have enough mass and energy for this brain that we want to consider getting T2') end
                    bWantMoreMexes = false
                end
                if bWantMoreMexes then
                    if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.5 and tLZOrWZTeamData[AiBotMap.subrefiActiveMexUpgrades] >= (tLZOrWZData[AiBotMap.subrefLZOrWZMexCount] or 0) and GetGameTimeSeconds() - AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeOfLastEnergyStall] >= 40 + 20 * iLifetimeCount then
                        bWantMoreMexes = false
                    elseif EntityCategoryContains(AiBotUnitInfo.refCategoryNavalFactory, oFactory.UnitId) and ((tLZOrWZData[AiBotMap.subrefLZOrWZMexCount] or 0) == 0 or (tLZOrWZTeamData[AiBotMap.subrefWZbCoreBase] and (oFactory[AiBotFactory.refiTotalBuildCount] >= 20 and aiBrain[AiBotEconomy.refiGrossMassBaseIncome] >= 8 * iFactoryTechLevel))) then
                        if bDebugMessages == true then LOG(sFunctionRef..': Naval factory, is core base='..tostring(tLZOrWZTeamData[AiBotMap.subrefWZbCoreBase])..'; Brain mass income gross='..aiBrain[AiBotEconomy.refiGrossMassBaseIncome]..'; iFactoryTechLevel='..iFactoryTechLevel..'; subrefbDangerousEnemiesInAdjacentWZ='..tostring(tLZOrWZTeamData[AiBotMap.subrefbDangerousEnemiesInAdjacentWZ] or false)..'; Team fgrigate+sub build count='..GetTeamLifetimeBuildCount(iTeam, AiBotUnitInfo.refCategoryFrigate + AiBotUnitInfo.refCategorySubmarine)) end
                        if tLZOrWZTeamData[AiBotMap.subrefWZbCoreBase] and
                                ((oFactory[AiBotFactory.refiTotalBuildCount] >= 20 or aiBrain[AiBotEconomy.refiGrossMassBaseIncome] >= 7 * iFactoryTechLevel or (iFactoryTechLevel == 1 and aiBrain[AiBotEconomy.refiGrossMassBaseIncome] >= 4 and (oFactory[AiBotFactory.refiTotalBuildCount] >= 6 or GetLifetimeBuildCount(aiBrain, AiBotUnitInfo.refCategoryNavalSurface + AiBotUnitInfo.refCategorySubmarine) >= 6) and not(tLZOrWZTeamData[AiBotMap.subrefbDangerousEnemiesInAdjacentWZ]) and not(BrainIsUpgradingNavalHQ(aiBrain))))
                                        or (iFactoryTechLevel == 1 and oFactory[AiBotFactory.refiTotalBuildCount] > 0 and not(tLZOrWZTeamData[AiBotMap.subrefbDangerousEnemiesInAdjacentWZ]) and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyTorpBombersThreat] > 0 and aiBrain[AiBotEconomy.refiGrossMassBaseIncome] >= 3.5 + 1 * aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryNavalFactory - categories.TECH1) and not(BrainIsUpgradingNavalHQ(aiBrain)))) then
                            bWantMoreMexes = false
                        elseif not(tLZOrWZTeamData[AiBotMap.subrefWZbCoreBase]) and (oFactory[AiBotFactory.refiTotalBuildCount] >= 40 or aiBrain[AiBotEconomy.refiGrossMassBaseIncome] >= 10 * iFactoryTechLevel) then
                            bWantMoreMexes = false
                        end
                    end
                end
                if bDebugMessages == true then LOG(sFunctionRef..': LOUD/QUIET - considering if want to hold off  on factory upgrade until we have more mexes, oFactory='..oFactory.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oFactory)..'; bWantMoreMexes='..tostring(bWantMoreMexes)..'; tLZOrWZData[AiBotMap.subrefLZOrWZMexCount]='..(tLZOrWZData[AiBotMap.subrefLZOrWZMexCount] or 'nil')..'; WZ core base='..tostring(tLZOrWZTeamData[AiBotMap.subrefWZbCoreBase] or false)..'; Factory build count='..oFactory[AiBotFactory.refiTotalBuildCount]..'; Dangerous enemies in adj WZ='..tostring(tLZOrWZTeamData[AiBotMap.subrefbDangerousEnemiesInAdjacentWZ])..'; Enemy torp bomber threat='..AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyTorpBombersThreat]..'; Brain is upgrading naval HQ='..tostring(BrainIsUpgradingNavalHQ(aiBrain))) end
                if bWantMoreMexes then
                    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                    return true
                end
            end
        end

        if not(bWantMoreEngineers) then
            if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.toActiveSnipeTargets]) == false and EntityCategoryContains(AiBotUnitInfo.refCategoryAirFactory, oFactory.UnitId) then
                local oACUToSnipe = GetNearbyACUForAirFacBomberSnipe(oFactory, aiBrain.AiBotTeam)

                if oACUToSnipe then
                    if bDebugMessages == true then LOG(sFunctionRef..': Want to do an ACU snipe') end
                    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                    return true
                end
            elseif aiBrain[AiBotOverseer.refbBomberSnipe] and AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.toBomberSnipeTargets]) == false and EntityCategoryContains(AiBotUnitInfo.refCategoryAirFactory - categories.UEF - categories.AEON - categories.TECH1, oFactory.UnitId) then
                --Havea  T2+ cybran or sera factory and want to do a t2 air snipe
                if bDebugMessages == true then LOG(sFunctionRef..': Want to do a t2 air snipe') end
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                return true
            end
        end

        if bDebugMessages == true then LOG(sFunctionRef..': End of code, bWantMoreEngineers='..tostring(bWantMoreEngineers or false)) end --here since lower down means not a factory
    end
    if bWantMoreEngineers and AiBotMap.bIsCampaignMap then
        --FA M5 - strange case where we are restricted from building T1-T2 engineers for fletcher, so want to check not relevant
        local sEngineerBlueprint = AiBotFactory.GetBlueprintThatCanBuildOfCategory(oFactory:GetAIBrain(), AiBotUnitInfo.refCategoryEngineer, oFactory)
        if not(sEngineerBlueprint) then bWantMoreEngineers = false end
    end
    oFactory[AiBotFactory.refbWantMoreEngineersBeforeUpgrading] = bWantMoreEngineers
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return bWantMoreEngineers
end

function GetPowerInsteadOfHydroEvenIfHydroAvailable(iTeam, tLZData, tLZTeamData, iPlateau, iLandZone, bHaveLowMass, bHaveLowPower)
    if not(tLZTeamData[AiBotMap.subrefLZbCoreBase]) or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] <= 7 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] or bHaveLowMass or not(bHaveLowPower) or table.getn(tLZData[AiBotMap.subrefHydroLocations]) <= 2 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] == 1 then
        return false
    end
    return true
end

function GetHighestTechInZone(iTeam, tLZTeamData)
    local iHighestTech = 1
    if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] > 1 and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then
        local tFactoriesAndEngineersInZone = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryAllHQFactories + AiBotUnitInfo.refCategoryEngineer - categories.TECH1, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
        if AiBotUtilities.IsTableEmpty(tFactoriesAndEngineersInZone) == false then
            for iUnit, oUnit in tFactoriesAndEngineersInZone do
                if AiBotUnitInfo.IsUnitValid(oUnit) and oUnit:GetFractionComplete() == 1 then
                    iHighestTech = math.max(iHighestTech, AiBotUnitInfo.GetUnitTechLevel(oUnit))
                    if iHighestTech >= 3 then break end
                end
            end
        end
    end
    return iHighestTech
end

function ApplyAiBotToOtherAI(aiBrain)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ApplyAiBotToOtherAI'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    if bDebugMessages == true then LOG(sFunctionRef..': aiBrain.BrainType='..(aiBrain.BrainType or 'nil')..'; aiBrain nickname='..(aiBrain.Nickname or 'nil')..'; Is civilian='..tostring(IsCivilianBrain(aiBrain))..'; Is scenario type skirmish='..tostring(ScenarioInfo.type == "skirmish")..'; DoesAINicknameContainAiBot='..tostring(AiBotUtilities.DoesAINicknameContainAiBot(aiBrain.Nickname))) end
    -- Human armies are never inferred from a nickname, shared-army option,
    -- campaign rule, or cheat setting.  The only valid human activation is
    -- the authenticated admin callback, which marks the brain as requested.
    if aiBrain.BrainType == 'Human' then
        local adminPlayers = ScenarioInfo.Options and ScenarioInfo.Options.AiBotAdminPlayers
        local isAuthorizedRequest = aiBrain.AiBotAdminRequested == true
            and type(adminPlayers) == 'table'
            and adminPlayers[aiBrain.Nickname] == true
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        return isAuthorizedRequest
    elseif AiBotUtilities.DoesAINicknameContainAiBot(aiBrain.Nickname) then
        if bDebugMessages == true then LOG(sFunctionRef..': Have AiBot in the name so will apply AiBot logic to the brain') end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        return true
    elseif not(AiBotOrders.bDontConsiderCombinedArmy) and aiBrain.BrainType == 'Human' then
        if bDebugMessages == true then LOG(sFunctionRef..': Have shared armies so treating brain as human') end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        return true
    else
        local iCampaignAISetting = ScenarioInfo.Options.CampAI
        local refiNone = 1
        local refiAllies = 2
        local refiEnemies = 3
        local refiAlliesAndEnemies = 4
        local bIsEnemyOfSomeone = false
        if not(iCampaignAISetting == refiNone) then
            --Hostile brains in campaign (i.e. non-player brains) should return true to the IsCivilianBrain check if theyve not yet been set as being a AiBotAI brain
            if (aiBrain.BrainType == "AI" or not(aiBrain.BrainType)) and not(ScenarioInfo.type == "skirmish") then
                --Do we have any brains that are hostile to this?

                local bEnemyOfPlayer = false
                local bAllyOfPlayerWithEnemy = false
                --FAF requires a humna player to be in the player 1 slot; therefore look for a human player and if cant find one then pick the brain with a braintype (since looks like this can be nil for some campaign missions for the built in AI)
                local oFirstPlayer
                for iBrain, oBrain in ArmyBrains do
                    if oBrain.BrainType == 'Human' then oFirstPlayer = oBrain break end
                end
                if not(oFirstPlayer) then
                    for iBrain, oBrain in ArmyBrains do
                        if aiBrain.BrainType then
                            oFirstPlayer = oBrain break
                        end
                    end
                end

                local bEnemyOfPlayerAlly = false
                local bEnemyOfPlayerEnemy = false

                if IsEnemy(oFirstPlayer:GetArmyIndex(), aiBrain:GetArmyIndex()) then
                    bEnemyOfPlayer = true
                    bIsEnemyOfSomeone = true
                elseif IsAlly(oFirstPlayer:GetArmyIndex(), aiBrain:GetArmyIndex()) then
                    --Check there is a brain this is an enemy of
                    for iBrain, oBrain in ArmyBrains do
                        if IsEnemy(aiBrain:GetArmyIndex(), oBrain:GetArmyIndex()) then
                            bIsEnemyOfSomeone = true
                            bAllyOfPlayerWithEnemy = true
                            break
                        end
                    end
                else
                    --Not ally or enemy of player; if enemy of the same faction the player is enemy of, then still consider an ally

                    for iBrain, oBrain in ArmyBrains do
                        if IsEnemy(aiBrain:GetArmyIndex(), oBrain:GetArmyIndex()) then
                            if IsEnemy(oFirstPlayer:GetArmyIndex(), oBrain:GetArmyIndex()) then
                                bEnemyOfPlayerEnemy = true
                            elseif IsAlly(oFirstPlayer:GetArmyIndex(), oBrain:GetArmyIndex()) then
                                bEnemyOfPlayerAlly = true
                            end
                            bIsEnemyOfSomeone = true
                        end
                    end
                end
                if not(bIsEnemyOfSomeone) then
                    for iBrain, oBrain in ArmyBrains do
                        if IsEnemy(aiBrain:GetArmyIndex(), oBrain:GetArmyIndex()) then
                            bIsEnemyOfSomeone = true
                            break
                        end
                    end
                end
                if bDebugMessages == true then LOG(sFunctionRef..': Considering brain, bIsEnemyOfSomeone='..tostring(bIsEnemyOfSomeone)..'; bEnemyOfPlayer='..tostring(bEnemyOfPlayer)..'; bAllyOfPlayerWithEnemy='..tostring(bAllyOfPlayerWithEnemy)..'; bEnemyOfPlayerAlly='..tostring(bEnemyOfPlayerAlly)..'; bEnemyOfPlayerEnemy='..tostring(bEnemyOfPlayerEnemy)) end
                local bUseAiBotAI = false
                if bEnemyOfPlayer and (iCampaignAISetting == refiEnemies or iCampaignAISetting == refiAlliesAndEnemies) then
                    bUseAiBotAI = true
                    if aiBrain.CampaignAI then aiBrain.HostileCampaignAI = true end
                elseif (bAllyOfPlayerWithEnemy or (bIsEnemyOfSomeone and not(bEnemyOfPlayer) and not(bEnemyOfPlayerAlly) and bEnemyOfPlayerEnemy)) and (iCampaignAISetting == refiAllies or iCampaignAISetting == refiAlliesAndEnemies) then
                    bUseAiBotAI = true
                end


                if bUseAiBotAI then
                    --override for brackman on FA M5 so we dont control the megalith:
                    if aiBrain.Nickname == 'Brackman' and ScenarioInfo.Brackman and ScenarioInfo.Fletcher and ScenarioInfo.Hex5 then
                        bUseAiBotAI = false
                    end
                    if aiBrain.Nickname == 'Dostya' and ScenarioInfo.Wreckage_Holding and ScenarioInfo.FauxUEF and ScenarioInfo.Symbiont and ScenarioInfo.Aeon then
                        --override for Dostya on SC Cybran M1 sine she starts with an ACU but isn't hostile to UEF or Aeon:
                        bUseAiBotAI = false
                    end
                end

                --[[for iBrain, oBrain in ArmyBrains do
                    if not(oBrain == aiBrain) then
                        if bDebugMessages == true then LOG(sFunctionRef..': Considering if oBrain '..oBrain.Nickname..' is an enemy to aiBrain '..aiBrain.Nickname..'; IsEnemy='..tostring(IsEnemy(iBrainIndex, oBrain:GetArmyIndex()))) end

                        if IsEnemy(oBrain:GetArmyIndex(), iBrainIndex) then bHaveEnemy = true end
                        --if IsAlly(oBrain:GetArmyIndex(), iBrainIndex) then bHaveAlly = true end
                    end
                end--]]
                --Removedl ogic re IsAlly, since even if it is an ally to one of us if it has no enemies there's nothign to attack
                if bDebugMessages == true then LOG(sFunctionRef..': oFirstPlayer='..(oFirstPlayer.Nickname or 'nil')..'; bUseAiBotAI='..tostring(bUseAiBotAI)..'; bEnemyofPlayer='..tostring(bEnemyOfPlayer)..'; bAllyOfPlayerWithEnemy='..tostring(bAllyOfPlayerWithEnemy)) end
                if bUseAiBotAI then --or bHaveAlly then
                    if bDebugMessages == true then LOG(sFunctionRef..': Will apply AiBot override to the brain') end
                    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                    return true
                else
                    if bDebugMessages == true then LOG(sFunctionRef..': Brain doesnt meet the ally or enemy settings so wont give AiBot logic to it') end
                end
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': Wont apply AiBot override to the brain '..aiBrain.Nickname..'; iCampaignAISetting='..(iCampaignAISetting or 'nil')..'; refiNone='..refiNone) end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function HaveSentOrderToRunAwayFromLocationToAvoid(oUnit, tLocationsToAvoid, iDistanceThreshold)
    --If are close to a location to avoid then gives the unit an order to run in the opposite direction
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'HaveSentOrderToRunAwayFromLocationToAvoid'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    for iLocation, tLocation in tLocationsToAvoid do
        if bDebugMessages == true then LOG(sFunctionRef..': Dist from unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' at position '..repru(oUnit:GetPosition())..' to tLocation='..repru(tLocation)..'='..AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tLocation)..'; iDistanceThreshold='..iDistanceThreshold) end
        if AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tLocation) <= iDistanceThreshold then
            local tLocationToMoveTo = AiBotUtilities.MoveInDirection(oUnit:GetPosition(), AiBotUtilities.GetAngleFromAToB(tLocation, oUnit:GetPosition()), 5, true, false, AiBotMap.bIsCampaignMap)
            AiBotOrders.IssueTrackedMove(oUnit, tLocationToMoveTo, 1, false, 'AvdAr', false)
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            return true
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return false
end

function GetCurrentAiBotUnitsOfCategoryInTeam(iCategory, iTeam)
    local iCount = 0
    for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains] do
        iCount = iCount + oBrain:GetCurrentUnits(iCategory)
    end
    return iCount
end

function WantMoreEngineersToAssistMexUpgradeAsPriority(tLZOrWZTeamData, iTeam)
    if tLZOrWZTeamData[AiBotMap.subrefTbWantBP] and (tLZOrWZTeamData[AiBotMap.subrefiActiveMexUpgrades] or 0) >= 2 and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass]) and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy]) and not(tLZOrWZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ]) and not(tLZOrWZTeamData[AiBotMap.subrefbDangerousEnemiesInAdjacentWZ]) and AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.reftLZEnemyAirUnits]) then
        local iEngineersWantedInZone = 7 + 3 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]
        if AiBotOverseer.IsTeamBoomMode(iTeam) then iEngineersWantedInZone = iEngineersWantedInZone + 3 end
        local tEngineersInZone
        if AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then tEngineersInZone = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryEngineer, tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) end
        local iEngineersInZone = 0
        if AiBotUtilities.IsTableEmpty(tEngineersInZone) == false then
            iEngineersInZone = table.getn(tEngineersInZone)
        end
        if iEngineersInZone < iEngineersWantedInZone then
            --Check we dont already have 3+ engineers under construction
            local iUnderConstruction = GetNumberOfUnitsMeetingCategoryUnderConstructionInLandOrWaterZone(tLZOrWZTeamData, AiBotUnitInfo.refCategoryEngineer, false)
            if iUnderConstruction < 1 + tLZOrWZTeamData[AiBotMap.subrefiActiveMexUpgrades] then
                return true
            end
        end
    end
    return false
end

function GetHighestOtherTeamT3MexCount(iTeam)
    local iHighestCount = 0
    for iCurTeam = 1, AiBotTeam.iTotalTeamCount do
        if not(iCurTeam == iTeam) then
            iHighestCount = math.max(iHighestCount, (AiBotTeam.tTeamData[iCurTeam][AiBotTeam.refiMexCountByTech][3] or 0))
        end
    end
    return iHighestCount
end

function GetHighestOtherTeamT2AndT3MexCount(iTeam)
    local iHighestCount = 0
    for iCurTeam = 1, AiBotTeam.iTotalTeamCount do
        if not(iCurTeam == iTeam) then
            iHighestCount = math.max(iHighestCount, (AiBotTeam.tTeamData[iCurTeam][AiBotTeam.refiMexCountByTech][3] or 0) + (AiBotTeam.tTeamData[iCurTeam][AiBotTeam.refiMexCountByTech][2] or 0))
        end
    end
    return iHighestCount
end

function HaveTemplateSpaceForGameEnder(iCategoryWanted, tLZOrWZData, tLZOrWZTeamData, tbEngineersOfFactionOrNilIfAlreadyAssigned, iTeam)
    --Returns true if we have space for a gameender of iCategoryWanted using the special shielding template logic
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'HaveTemplateSpaceForGameEnder'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if not(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbUnableToBuildArtiOrGameEnders]) then

        --First check if we have that size available generally (without using backup template)
        local iSmallestSizeNeeded = 22
        --if tbEngineersOfFactionOrNilIfAlreadyAssigned[AiBotUnitInfo.refFactionUEF] or tbEngineersOfFactionOrNilIfAlreadyAssigned[AiBotUnitInfo.refFactionSeraphim] then iSmallestSizeNeeded = 20 end
        if AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subrefBuildLocationsBySizeAndSegment][iSmallestSizeNeeded]) == false then
            for iSegmentX, tSubtable in tLZOrWZTeamData[AiBotMap.subrefBuildLocationsBySizeAndSegment][iSmallestSizeNeeded] do
                for iSegmentZ, bValid in tSubtable do
                    if bValid then
                        if bDebugMessages == true then LOG(sFunctionRef..': Have valid size '..iSmallestSizeNeeded..' for iSegmentX='..iSegmentX..'Z'..iSegmentZ) end
                        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                        return true
                    end
                end
            end
        end

        --Do we have any active locations?
        local bActiveLocationButDoesntWantEngineers = false
        if AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.reftActiveGameEnderTemplates]) == false then
            for iEntry, tSubtable in tLZOrWZTeamData[AiBotMap.reftActiveGameEnderTemplates] do
                if bDebugMessages == true then LOG(sFunctionRef..': Have active gameender template, does it no longer need engineers='..tostring(tSubtable[AiBotMap.subrefGEbDontNeedEngineers] or false)) end
                if not(tSubtable[AiBotMap.subrefGEbDontNeedEngineers]) then
                    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                    return true
                else
                    bActiveLocationButDoesntWantEngineers = true
                end
            end
        end



        --We dont have any locations large enough that are free, check if we have a recorded template, and if so are we already using it
        if bDebugMessages == true then LOG(sFunctionRef..': Is table of gameender tempalte backup locations empty='..tostring(AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefGameEnderTemplateBackupLocationSizeAndSegment]))) end
        if AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefGameEnderTemplateBackupLocationSizeAndSegment]) == false then
            --Check the active location doesn't cross into this location
            local bRecordedIsAlreadyUsed = false
            if bDebugMessages == true then LOG(sFunctionRef..': Checking if this location overlaps with an existing active template, bActiveLocationButDoesntWantEngineers='..tostring(bActiveLocationButDoesntWantEngineers or false)) end
            if bActiveLocationButDoesntWantEngineers then
                if bDebugMessages == true then LOG(sFunctionRef..': tLZOrWZData[AiBotMap.subrefGameEnderTemplateBackupLocationSizeAndSegment]='..repru(tLZOrWZData[AiBotMap.subrefGameEnderTemplateBackupLocationSizeAndSegment])) end
                local tBackupMidpoint = AiBotMap.GetPositionFromPathingSegments(tLZOrWZData[AiBotMap.subrefGameEnderTemplateBackupLocationSizeAndSegment][AiBotMap.subrefiSegX], tLZOrWZData[AiBotMap.subrefGameEnderTemplateBackupLocationSizeAndSegment][AiBotMap.subrefiSegZ])

                for iEntry, tSubtable in tLZOrWZTeamData[AiBotMap.reftActiveGameEnderTemplates] do
                    if bDebugMessages == true then LOG(sFunctionRef..': tBackupMidpoint='..repru(tBackupMidpoint)..'; tSubtable midpoint='..repru(tSubtable[AiBotMap.subrefGEMidpoint])..'; Subtable size='..tSubtable[AiBotMap.subrefGESize]..'; Abs X dif='..math.abs(tSubtable[AiBotMap.subrefGEMidpoint][1] - tBackupMidpoint[1])..'; Abs Z dif='..math.abs(tSubtable[AiBotMap.subrefGEMidpoint][3] - tBackupMidpoint[3])) end
                    if math.abs(tSubtable[AiBotMap.subrefGEMidpoint][1] - tBackupMidpoint[1]) <= tSubtable[AiBotMap.subrefGESize] and math.abs(tSubtable[AiBotMap.subrefGEMidpoint][3] - tBackupMidpoint[3]) <= tSubtable[AiBotMap.subrefGESize] then
                        bRecordedIsAlreadyUsed = true
                        break
                    end

                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': bRecordedIsAlreadyUsed='..tostring(bRecordedIsAlreadyUsed or false)) end
            if not(bRecordedIsAlreadyUsed) then
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                return true
            end
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': Coudlnt find any suitable locations, returning false') end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return false
end

function HaveActiveGameEnderTemplateLogic(tLZOrWZTeamData, bOptionalOnlyTrueIfNeedUEFOrSeraEngineers)
    if AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.reftActiveGameEnderTemplates]) == false then
        for iTemplate, tSubtable in tLZOrWZTeamData[AiBotMap.reftActiveGameEnderTemplates] do
            if not(tSubtable[AiBotMap.subrefGEbDontNeedEngineers]) then
                if not(bOptionalOnlyTrueIfNeedUEFOrSeraEngineers) then
                    return true
                else
                    --Only return true if this location has 2+ arti slots, and fewer than 7 shields (i.e. it wants UEF/Sera engineers)
                    if (tSubtable[AiBotMap.subrefiCyclesWaitingForEngineer] or 0) > 0 or (table.getn(tSubtable[AiBotMap.subrefGEArtiLocations]) > 1 and (AiBotUtilities.IsTableEmpty(tSubtable[AiBotMap.subrefGEShieldUnits]) or table.getn(tSubtable[AiBotMap.subrefGEShieldUnits]) >= 3)) then
                        return true
                    end
                end
            end
        end
    end
    return false
end

function WillBlockTemplateLocation(tLZTeamData, iCurSegmentX, iCurSegmentZ, iBuildingAdjustedRadius)
    if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftActiveGameEnderTemplates]) == false then
        local tBasePosition = AiBotMap.GetPositionFromPathingSegments(iCurSegmentX, iCurSegmentZ)
        local iDistancethreshold
        for iTemplate, tSubtable in tLZTeamData[AiBotMap.reftActiveGameEnderTemplates] do
            iDistancethreshold = tSubtable[AiBotMap.subrefGESize] + iBuildingAdjustedRadius
            if math.abs(tSubtable[AiBotMap.subrefGEMidpoint][1] - tBasePosition[1]) <= iDistancethreshold and math.abs(tSubtable[AiBotMap.subrefGEMidpoint][3] - tBasePosition[3]) then
                return true
            end
        end
    end
    return false
end

function WantT3MAAInsteadOfT2(oFactory, iTeam)
    if AiBotUnitInfo.GetUnitTechLevel(oFactory) == 3 and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyAirTech] >= 3 or AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat] >= 3000) and (oFactory:GetAIBrain():GetCurrentUnits(AiBotUnitInfo.refCategoryMAA) >= 20 or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiAlliedMAAThreat] >= 1000 and AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoEnemyAirToGround]) == false and AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(categories.TECH3 * AiBotUnitInfo.refCategoryBomber, AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoEnemyAirToGround])) == false) and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat] > 0 and oFactory:GetAIBrain():GetCurrentUnits(AiBotUnitInfo.refCategoryMAA - categories.TECH3) >  oFactory:GetAIBrain():GetCurrentUnits(AiBotUnitInfo.refCategoryMAA * categories.TECH3) * 2) then
        return true
    end
    return false
end

function PrioritiseSniperBots(tLZData, iTeam, tLZTeamData, iPlateau, iLandZone, bHaveAeonOrSeraFactoryInZoneOverride)
    --Returns true if we want to prioritise building sniperbots as a counter to enemy land experimentals or powerful enemy guncom
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'PrioritiseSniperBots'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if bDebugMessages == true then
        LOG(sFunctionRef..': Stat of code, subrefiNearbyEnemyLongRangeDFThreat='..tLZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeDFThreat] or 'nil'..'; time='..GetGameTimeSeconds())
        if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyLandExperimentals]) == false then LOG(sFunctionRef..': Enemy has land exp, is table of enemy mega and fatboy empty='..tostring(AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(AiBotUnitInfo.refCategoryMegalith + AiBotUnitInfo.refCategoryFatboy,AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyLandExperimentals]))))
        else LOG(sFunctionRef..': Enemy has no land exp')
        end
    end
    if tLZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeDFThreat] < 2600 then --If enemy has lots of sniperbots then we probably lose in a fight (if we check for them), but main purpose of this is ravagers since they now outrange sniperbots in FAF, so better off going for t3 mobile arti
        local bDangerousExperimentalOrACUThreat = false
        local bEnemyHasLongRangeThreat = false
        --Get if enemy has land experiemntals but lacks megalith or fatboy; also get if enemy has dangerous ACU
        if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyLandExperimentals]) == false then
            if AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(AiBotUnitInfo.refCategoryMegalith + AiBotUnitInfo.refCategoryFatboy,AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyLandExperimentals])) then
                bEnemyHasLongRangeThreat = true
            else
                --Dont get if enemy has t2 arti near this zone
                if bDebugMessages == true then LOG(sFunctionRef..': Is table of enemy nearby t2 arti empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits]))) end
                if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits]) then
                    local aiBrain = ArmyBrains[tLZTeamData[AiBotMap.reftiClosestFriendlyAiBotBrainIndex]]
                    local iLandSubteam = aiBrain.AiBotLandSubteam
                    if bDebugMessages == true then LOG(sFunctionRef..': Number of T3 aeon and sera factories on team='..((AiBotTeam.tLandSubteamData[iLandSubteam][AiBotTeam.subrefFactoriesByTypeFactionAndTech][AiBotFactory.refiFactoryTypeLand][AiBotUnitInfo.refFactionAeon][3] or 0) + (AiBotTeam.tLandSubteamData[iLandSubteam][AiBotTeam.subrefFactoriesByTypeFactionAndTech][AiBotFactory.refiFactoryTypeLand][AiBotUnitInfo.refFactionSeraphim][3] or 0)..'; Is table of aeon and sera factories in this zone empty='..tostring(AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(AiBotUnitInfo.refCategoryLandFactory * categories.AEON + AiBotUnitInfo.refCategoryLandFactory * categories.SERAPHIM, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]))))) end
                    if bHaveAeonOrSeraFactoryInZoneOverride or ((AiBotTeam.tLandSubteamData[iLandSubteam][AiBotTeam.subrefFactoriesByTypeFactionAndTech][AiBotFactory.refiFactoryTypeLand][AiBotUnitInfo.refFactionAeon][3] or 0) + (AiBotTeam.tLandSubteamData[iLandSubteam][AiBotTeam.subrefFactoriesByTypeFactionAndTech][AiBotFactory.refiFactoryTypeLand][AiBotUnitInfo.refFactionSeraphim][3] or 0) > 0 and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false and AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(AiBotUnitInfo.refCategoryLandFactory * categories.AEON + AiBotUnitInfo.refCategoryLandFactory * categories.SERAPHIM, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])) == false) then
                        local bEnemyHasLandExpOnSameIsland = false
                        for iUnit, oUnit in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyLandExperimentals] do
                            if AiBotUnitInfo.IsUnitValid(oUnit) and NavUtils.GetLabel(AiBotMap.refPathingTypeLand, oUnit:GetPosition()) == (tLZData[AiBotMap.subrefLZIslandRef] or 0) then
                                bEnemyHasLandExpOnSameIsland = true
                                break
                            end
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': bEnemyHasLandExpOnSameIsland='..tostring(bEnemyHasLandExpOnSameIsland or false)..'; LC sniperbot='..GetTeamLifetimeBuildCount(iTeam, AiBotUnitInfo.refCategorySniperBot)..'; Active brain count='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]) end
                        if bEnemyHasLandExpOnSameIsland then
                            bDangerousExperimentalOrACUThreat = true
                            if bDebugMessages == true then LOG(sFunctionRef..': Enemy has experimental that we want to try and beat, if in QUIET will check if it is fast') end
                            if AiBotUtilities.bQuietModActive then
                                for iUnit, oUnit in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyLandExperimentals] do
                                    if not(oUnit.Dead) then
                                        if (oUnit[AiBotUnitInfo.refiDFRange] or 0) >= 55 or (oUnit:GetBlueprint().Physics.MaxSpeed or 0) > 2.5 then --2.5 is speed of monkeylord or ythotha in faf
                                            bDangerousExperimentalOrACUThreat = false
                                            if bDebugMessages == true then LOG(sFunctionRef..': Enemy experimental is either too fast or too long range to risk sniperbots') end
                                            break
                                        end
                                    end
                                end
                            end
                        end
                    end
                else
                    bEnemyHasLongRangeThreat = true
                end
            end
        end
        --Does enemy have a dangerous ACU instead that is nearby, and we likely have the eco to get T3 land?
        if not(bDangerousExperimentalOrACUThreat) and AiBotTeam.tTeamData[iTeam][AiBotTeam.refbEnemyHasDangerousACU] and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 10 and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 30 or tLZTeamData[AiBotMap.subrefMexCountByTech][3] > 0 or tLZTeamData[AiBotMap.subrefMexCountByTech][2] >= 4) and not(bEnemyHasLongRangeThreat) and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits]) then
            local iACUThreat, oACU = GetThreatOfApproachingEnemyACUsAndNearestACU(tLZData, tLZTeamData, iPlateau, iLandZone, iTeam, 100)
            if bDebugMessages == true then LOG(sFunctionRef..': Deciding if have approaching ACU threat with a +100 dist mod, iACUThreat='..iACUThreat..'; Build tech='..(oACU[import('/lua/AiBot/AI/AiBotACU.lua').refiBuildTech] or 'nil')..'; Closest brain land fac tech='..ArmyBrains[tLZTeamData[AiBotMap.reftiClosestFriendlyAiBotBrainIndex]][AiBotEconomy.refiOurHighestLandFactoryTech]) end
            if iACUThreat >= 2500 then
                if (not(EntityCategoryContains(categories.UEF, oACU.UnitId)) or oACU[import('/lua/AiBot/AI/AiBotACU.lua').refiBuildTech] or 0) < 3 or ArmyBrains[tLZTeamData[AiBotMap.reftiClosestFriendlyAiBotBrainIndex]][AiBotEconomy.refiOurHighestLandFactoryTech] < 3 then
                    --Check the closest ACU isnt a UEF T3 ACU (since they can build ravagers that counter sniperbots)
                    bDangerousExperimentalOrACUThreat = true
                    if bDebugMessages == true then LOG(sFunctionRef..': Enemy has dangerous ACU that we want to try and beat') end
                elseif bDebugMessages == true then LOG(sFunctionRef..': Dangerous ACU but it can build ravagers so dont want sniperbots')
                end
            end
        end
        if bDangerousExperimentalOrACUThreat then
            if bDebugMessages == true then LOG(sFunctionRef..': Considering prioroitising sniperbots if we havent built lots, lifetime count='..GetTeamLifetimeBuildCount(iTeam, AiBotUnitInfo.refCategorySniperBot)) end
            --We have access to Aeon/Seraphim tech, and enemy has land experimentals but not a megalith or fatboy; prioritise sniperbots if we have a build count of less than 20
            if GetTeamLifetimeBuildCount(iTeam, AiBotUnitInfo.refCategorySniperBot) <= 13 + 7 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] then
                --If we arent far behind on air and enemy lacks much in the way of T3 MAA then dont prioritise sniperbots since air likely better
                if bDebugMessages == true then LOG(sFunctionRef..': Is team far behind on air='..tostring(TeamIsFarBehindOnAir(iTeam))..'; Our gunship threat='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurGunshipThreat]..'; Enemy T3 MAA count='..AiBotTeam.tTeamData[iTeam][AiBotTeam.iEnemyT3MAAActiveCount]..'; Gunship losses='..AiBotTeam.tTeamData[iTeam][AiBotTeam.refiGunshipLosses]..'; Gunship kills='..AiBotTeam.tTeamData[iTeam][AiBotTeam.refiGunshipKills]) end
                if TeamIsFarBehindOnAir(iTeam) or AiBotTeam.tTeamData[iTeam][AiBotTeam.iEnemyT3MAAActiveCount] >= 12 or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurGunshipThreat] <= 20000 and AiBotTeam.tTeamData[iTeam][AiBotTeam.iEnemyT3MAAActiveCount] >= 4) or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurGunshipThreat] <= 5000 or AiBotTeam.tTeamData[iTeam][AiBotTeam.refiGunshipLosses] > math.max(10000, AiBotTeam.tTeamData[iTeam][AiBotTeam.refiGunshipKills] * 1.5) then
                    if bDebugMessages == true then LOG(sFunctionRef..': Want sniperbots') end
                    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                    return true
                end
            end
        end
    else
        if ArmyBrains[tLZTeamData[AiBotMap.reftiClosestFriendlyAiBotBrainIndex]][AiBotEconomy.refiOurHighestLandFactoryTech] < 3 then
            if bDebugMessages == true then LOG(sFunctionRef..': Enemy has LR threat so we want to get T3 land, so will return true even though we wont want to build sniperbots from it') end
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            return true
        elseif bDebugMessages == true then LOG(sFunctionRef..': Enemy LR threat too high and we already have T3 land')
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': Dont want sniperbots') end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return false
end

function GetNumberOfUnitsOfCategoryInAdjacentLandZones(tLZData, iPlateau, iTeam, iCategory, bIncludeOnlyConstructed, bReturnOnceOnlyOneUnit)
    --Only considers adjacent land zones, not the current zone; assumes dealing with land zone
    local iCount = 0
    if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
        for _, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
            local tAdjLZTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam]
            if AiBotUtilities.IsTableEmpty(tAdjLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then
                local tUnitsOfCategory
                if iCategory then tUnitsOfCategory = EntityCategoryFilterDown(iCategory, tAdjLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                else tUnitsOfCategory = tAdjLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]
                end
                if AiBotUtilities.IsTableEmpty(tUnitsOfCategory) == false then
                    for iUnit, oUnit in tUnitsOfCategory do
                        if AiBotUnitInfo.IsUnitValid(oUnit) then
                            if not(bIncludeOnlyConstructed) or oUnit:GetFractionComplete() == 1 then
                                iCount = iCount + 1
                                if bReturnOnceOnlyOneUnit then return iCount end
                            end
                        end
                    end
                end
            end
        end
    end
    return iCount
end


function AreAnyOfTableOfUnitsInAdjacentLandZone(tUnits, iPlateau, iLandZone, tLZData, tLZTeamData, iTeam)
    if AiBotUtilities.IsTableEmpty(tUnits) == false then --redundancy
        local tbZonesWithUnits = {}
        local iCurPlateau, iCurLZ
        for iUnit, oUnit in tUnits do
            iCurPlateau = oUnit[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][1]
            if iCurPlateau == iPlateau then
                iCurLZ = oUnit[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2]
                if not(tbZonesWithUnits[iCurLZ]) then tbZonesWithUnits[iCurLZ] = true end
            end
        end
        if AiBotUtilities.IsTableEmpty(tbZonesWithUnits) == false then
            if tbZonesWithUnits[iLandZone] then
                return true
            elseif AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                for _, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
                    if tbZonesWithUnits[iAdjLZ] then
                        return true
                    end
                end

            end
        end
    end
    return false
end

function HaveEngineersOrFactoriesInZone(tLZOrWZTeamData)
    local bHaveEngiOrFactory = false
    if AiBotUtilities.IsTableEmpty(tLZOrWZTeamData) == false then
        for iUnit, oUnit in tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits] do
            if EntityCategoryContains(AiBotUnitInfo.refCategoryEngineer + AiBotUnitInfo.refCategoryFactory, oUnit.UnitId) then
                if AiBotUnitInfo.IsUnitValid(oUnit) and oUnit:GetFractionComplete() == 1 then
                    return true
                end
            end
        end
    end
    return false
end


function HaveSignificantEnemyThreatWithinRange(tLZData, tLZTeamData, iPlateau, iTeam, iSearchDistance, tStartPoint, iEnemyMassTotalThreshold, iOptionalSearchCategory, tOptionalAdditionalUnits, bOnlyIncludeDFUnits, bIncludeEnemyCombatRange, iOptionalSpeedThreshold, iOptionalMinEnemyMassRequiredUnlessInRange, bIgnoreReductionIfJustInsideSearchDistance)
    --Essentially a much more cpu intesnive version of getunitsaroundpoint, that will make use of AiBot's memory of where units are; will search current zone and adjacent zones; can also pass it tOptionalAdditionalUnits for further away units
    --iEnemyMassTotalThreshold - if >= this in mass then returns true, otherwise returns false
    --iOptionalSpeedThreshold - if specified, then will ignore units that are slower than this unless they are close to being in combat range
    --iOptionalMinEnemyMassRequiredUnlessInRange - will ignore units with less mass than this unless they are almost in range
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'HaveSignificantEnemyThreatWithinRange'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local iCumulativeUnitValue = 0
    local iCurDist
    local bSignificantEnemyThreat = false
    function ConsiderUnitTable(tUnits)
        if AiBotUtilities.IsTableEmpty(tUnits) == false then
            local tUnitTable
            if iOptionalSearchCategory then tUnitTable = EntityCategoryFilterDown(iOptionalSearchCategory, tUnits)
            else tUnitTable = tUnits
            end
            if AiBotUtilities.IsTableEmpty(tUnitTable) == false then
                local aiBrain = ArmyBrains[tLZTeamData[AiBotMap.reftiClosestFriendlyAiBotBrainIndex]]
                for iUnit, oUnit in tUnitTable do
                    if AiBotUnitInfo.IsUnitValid(oUnit) and (not(bOnlyIncludeDFUnits) or oUnit[AiBotUnitInfo.refiDFRange] > 0) then
                        iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tStartPoint)
                        if bDebugMessages == true then LOG(sFunctionRef..': Considering enemy oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; iCurDist='..iCurDist..'; refiCombatRange='..oUnit[AiBotUnitInfo.refiCombatRange]..'; MassCost='..(oUnit[AiBotUnitInfo.refiUnitMassCost] or 'nil')..'; bIncludeEnemyCombatRange='..tostring(bIncludeEnemyCombatRange)) end
                        if iCurDist <= iSearchDistance or (bIncludeEnemyCombatRange and iCurDist - oUnit[AiBotUnitInfo.refiCombatRange] <= iSearchDistance) then
                            if iCurDist <= 5 + oUnit[AiBotUnitInfo.refiCombatRange] or ((not(iOptionalMinEnemyMassRequiredUnlessInRange) or (oUnit[AiBotUnitInfo.refiUnitMassCost] or AiBotUnitInfo.GetUnitMassCost(oUnit)) >= iOptionalMinEnemyMassRequiredUnlessInRange) and
                                    --Speed check - if enemy has a splash or laser ACU then want to run slightly sooner than normal even if we are faster than it
                                    (not(iOptionalSpeedThreshold) or iCurDist <= 5 + oUnit[AiBotUnitInfo.refiCombatRange] or oUnit:GetBlueprint().Physics.MaxSpeed >= iOptionalSpeedThreshold or iCurDist <= 10 + oUnit[AiBotUnitInfo.refiCombatRange] and ((oUnit[AiBotUnitInfo.refiUnitMassCost] or AiBotUnitInfo.GetUnitMassCost(oUnit)) >= 4500 or (oUnit[AiBotUnitInfo.refiDFMassThreatOverride] and oUnit[AiBotUnitInfo.refiDFMassThreatOverride] >= 4500))))
                                    then
                                --Also ignore scouts generally (although should be negligible impact on threat)
                                if not(iOptionalMinEnemyMassRequiredUnlessInRange) or (oUnit[AiBotUnitInfo.refiUnitMassCost] or AiBotUnitInfo.GetUnitMassCost(oUnit)) >= math.min(iOptionalMinEnemyMassRequiredUnlessInRange, 20) then
                                    --Reduce increase if unit is only just in range and we aren't worried about enemy rushing us with army
                                    if not(bIgnoreReductionIfJustInsideSearchDistance) and iCurDist > iSearchDistance - 8 and oUnit[AiBotUnitInfo.refiCombatRange] < iSearchDistance - 8 and (not(bIncludeEnemyCombatRange) or iCurDist - oUnit[AiBotUnitInfo.refiCombatRange] > iSearchDistance - 8) and (iCurDist > iSearchDistance - 2.5 or (not(AiBotUnitInfo.CanSeeUnit(aiBrain, oUnit)) and AiBotUnitInfo.GetUnitSpeed(oUnit) > (iOptionalSpeedThreshold or 1.5) and AiBotUtilities.GetAngleDifference(AiBotUtilities.GetAngleFromAToB(oUnit:GetPosition(), tStartPoint), AiBotUnitInfo.GetUnitFacingAngle(oUnit)) <= 50)) then
                                        --Reduce the value significantly
                                        iCumulativeUnitValue = iCumulativeUnitValue + 0.3 * math.max((oUnit[AiBotUnitInfo.refiUnitMassCost] or AiBotUnitInfo.GetUnitMassCost(oUnit)), (AiBotUnitInfo.tUnitThreatByIDAndType[oUnit.UnitId]['1000000'] or 0))
                                        if bDebugMessages == true then LOG(sFunctionRef..': Will only recognise 30% of this unit') end
                                    else
                                        iCumulativeUnitValue = iCumulativeUnitValue + math.max((oUnit[AiBotUnitInfo.refiUnitMassCost] or AiBotUnitInfo.GetUnitMassCost(oUnit)), (AiBotUnitInfo.tUnitThreatByIDAndType[oUnit.UnitId]['1000000'] or 0))
                                    end
                                    if bDebugMessages == true then LOG(sFunctionRef..': iCumulativeUnitValue after considering oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'='..iCumulativeUnitValue..'; iEnemyMassTotalThreshold='..iEnemyMassTotalThreshold..'; AiBotUnitInfo.tUnitThreatByIDAndType[oUnit.UnitId]='..(AiBotUnitInfo.tUnitThreatByIDAndType[oUnit.UnitId]['1000000'] or 'nil')) end
                                    if iCumulativeUnitValue >= iEnemyMassTotalThreshold then
                                        bSignificantEnemyThreat = true
                                        if bDebugMessages == true then LOG(sFunctionRef..': Enoguh targets of interest so will return true') end
                                        break
                                    end
                                end
                            end
                        end
                    end
                end
            end
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': Considering enemy units in the base LZ, iSearchDistance='..iSearchDistance..'; iEnemyMassTotalThreshold='..iEnemyMassTotalThreshold) end
    ConsiderUnitTable(tLZTeamData[AiBotMap.subrefTEnemyUnits])
    if bSignificantEnemyThreat then
        if bDebugMessages == true then LOG(sFunctionRef..': Have significant threat after just considering enemy units in LZTeamData') end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        return true
    end
    if tOptionalAdditionalUnits then  ConsiderUnitTable(tOptionalAdditionalUnits) end
    if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
        if bSignificantEnemyThreat then
            if bDebugMessages == true then LOG(sFunctionRef..': Have significant threat after just considering tOptionalAdditionalUnits') end
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            return true
        end
        for _, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
            if bDebugMessages == true then LOG(sFunctionRef..': Considering enemy units in the adjacent landzone='..iAdjLZ) end
            ConsiderUnitTable(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefTEnemyUnits])
            if bSignificantEnemyThreat then
                if bDebugMessages == true then LOG(sFunctionRef..': Have significant units') end
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                return true
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return false
end

function ACULikelyToWantCombatUpgradeOrShield(oACU)
    --used to decide if we want to go down combat path of upgrades for ACU, or if enemy has novax such that we want more defence for acu
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ACULikelyToWantCombatUpgradeOrShield'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    if bDebugMessages == true then LOG(sFunctionRef..'; Start of code, ACU health%='..AiBotUnitInfo.GetUnitHealthPercent(oACU)..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDangerousForACUs]='..tostring(AiBotTeam.tTeamData[oACU:GetAIBrain().AiBotTeam][AiBotTeam.refbDangerousForACUs])..'; aiBrain[AiBotMap.refbCanPathToEnemyBaseWithAmphibious]='..tostring(oACU:GetAIBrain()[AiBotMap.refbCanPathToEnemyBaseWithAmphibious])..'; Time='..GetGameTimeSeconds()) end
    --Cybran and Aeon - if have RAS then dont replace with shield
    if (oACU:HasEnhancement('ResourceAllocationAdvanced') or oACU:HasEnhancement('ResourceAllocation')) and EntityCategoryContains(categories.CYBRAN + categories.AEON, oACU.UnitId) and (AiBotUnitInfo.GetUnitHealthPercent(oACU) >= 0.8 or not(AiBotTeam.tTeamData[oACU:GetAIBrain().AiBotTeam][AiBotTeam.refbAssassinationOrSimilar])) then
        if bDebugMessages == true then LOG(sFunctionRef..': We already have RAS so dont want to get stealth/shield for cybran/aeon') end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        return false
    elseif AiBotUnitInfo.GetUnitHealthPercent(oACU) < 0.7 then
        if bDebugMessages == true then LOG(sFunctionRef..': ACU damaged so returning true to use in combat') end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        return true
    else
        local aiBrain = oACU:GetAIBrain()
        local iTeam = aiBrain.AiBotTeam
        if AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyNovaxCount] > 0 then
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            return true
        elseif GetGameTimeSeconds() <= 1200 then
            if aiBrain[AiBotMap.refbCanPathToEnemyBaseWithAmphibious] then
                if not(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDangerousForACUs]) then
                    --If enemy has dangerous ACU that is on the same plateau as us then go defensive
                    if AiBotTeam.tTeamData[iTeam][AiBotTeam.refbEnemyHasDangerousACU] and AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyACUs]) == false then
                        local iOurPlateau = NavUtils.GetLabel(AiBotMap.refPathingTypeHover, oACU:GetPosition())
                        local AiBotACU = import('/lua/AiBot/AI/AiBotACU.lua')
                        for iEnemyACU, oEnemyACU in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyACUs] do
                            if iOurPlateau == NavUtils.GetLabel(AiBotMap.refPathingTypeHover, oEnemyACU:GetPosition()) and oEnemyACU[AiBotACU.refiUpgradeCount] >= 2 then
                                if bDebugMessages == true then LOG(sFunctionRef..': Enemy has dangerous ACU on the team, and one of the ACUs on this plateau has 2+ upgrades so assuming it is dangerous') end
                                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                                return true
                            end
                        end
                    end

                    --How close is nearest enemy base to our nearest friendly base (dont want to do based on ACU position as ACU might retreat to get upgrade then the upgrade changes as a result of htis flag
                    local tLZOrWZData, tLZOrWZTeamData = AiBotMap.GetLandOrWaterZoneData(oACU:GetPosition(), true, iTeam)
                    if not(tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase]) then
                        tLZOrWZData, tLZOrWZTeamData = AiBotMap.GetLandOrWaterZoneData(AiBotMap.GetPlayerStartPosition(aiBrain), true, iTeam)
                    end
                    local iDistBetweenBases = AiBotUtilities.GetDistanceBetweenPositions(tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase], tLZOrWZTeamData[AiBotMap.reftClosestEnemyBase])
                    if bDebugMessages == true then LOG(sFunctionRef..': iDistBetweenBases='..iDistBetweenBases..'; aiBrain[AiBotMap.refbCanPathToEnemyBaseWithLand]='..tostring(aiBrain[AiBotMap.refbCanPathToEnemyBaseWithLand])..'; Cur T3 mex='..aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryT3Mex)) end
                    if iDistBetweenBases <= 300 or (aiBrain[AiBotMap.refbCanPathToEnemyBaseWithLand] and iDistBetweenBases <= 500) then
                        if aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryT3Mex) < 3 then
                            --Check start LZ isnt in a safe position
                            local tStartLZOrWZData, tStartLZOrWZTeamData = AiBotMap.GetLandOrWaterZoneData(AiBotMap.GetPlayerStartPosition(aiBrain), true, iTeam)
                            if bDebugMessages == true then LOG(sFunctionRef..': tStartLZOrWZTeamData[AiBotMap.refbBaseInSafePosition]='..tostring(tStartLZOrWZTeamData[AiBotMap.refbBaseInSafePosition])) end
                            if not(tStartLZOrWZTeamData[AiBotMap.refbBaseInSafePosition]) then
                                if bDebugMessages == true then LOG(sFunctionRef..': Likely we will want to use ACU in combat, returning true') end
                                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                                return true
                            end
                        end
                    end
                end
            end

        end
    end
        if bDebugMessages == true then LOG(sFunctionRef..': Unlikely we will want to use ACU in combat, returning false') end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        return false
end

function AdjacentToPacifistZone(iPlateauOrZero, iLandOrWaterZone)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'AdjacentToPacifistZone'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local tLZOrWZData
    if iPlateauOrZero == 0 then
        tLZOrWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iLandOrWaterZone]][AiBotMap.subrefPondWaterZones][iLandOrWaterZone]
    else
        tLZOrWZData = AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iLandOrWaterZone]
    end
    if bDebugMessages == true then LOG(sFunctionRef..': Near start, iPlateauOrZero='..(iPlateauOrZero or 'nil')..'; iLandOrWaterZone='..(iLandOrWaterZone or 'nil')..'; Is tLZOrWZData empty='..tostring(AiBotUtilities.IsTableEmpty(tLZOrWZData))) end
    if tLZOrWZData[AiBotMap.subrefbPacifistArea] then
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        return true
    else
        AiBotAir.RecordOtherLandAndWaterZonesByDistance(tLZOrWZData)
        if AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefOtherLandAndWaterZonesByDistance]) == false then
            for iEntry, tSubtable in tLZOrWZData[AiBotMap.subrefOtherLandAndWaterZonesByDistance] do
                if tSubtable[AiBotMap.subrefiDistance] > 200 then break end
                local tAltLZOrWZData
                local iCurLZOrWZRef = tSubtable[AiBotMap.subrefiLandOrWaterZoneRef]
                if tSubtable[AiBotMap.subrefbIsWaterZone] then
                    tAltLZOrWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iCurLZOrWZRef]][AiBotMap.subrefPondWaterZones][iCurLZOrWZRef]
                else
                    tAltLZOrWZData = AiBotMap.tAllPlateaus[tSubtable[AiBotMap.subrefiPlateauOrPond]][AiBotMap.subrefPlateauLandZones][iCurLZOrWZRef]
                end
                if tAltLZOrWZData[AiBotMap.subrefbPacifistArea] then
                    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                    return true
                end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function DoesAINicknameContainAiBot(sNickname, bOnlyAiBotEasy)
    return AiBotUtilities.DoesAINicknameContainAiBot(sNickname, bOnlyAiBotEasy)
end

function HaveEcoToSupportGETemplate(iTeam)
    if AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive then
        if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 250*math.min(10, (2* AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] + 4)) and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] >= math.max(2, AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]) then
            return true
        end
    else
        if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 250*math.min(4, (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] * 1.5)) and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] >= 1 then
            return true
        end
    end
    return false
end

function GiveAttackMoveAsWeaponStuck(oUnit)
    --Currently intended for DF units such as ACU (battleships manually added some logic already before did this so at some poitn could look to combine if wanted to be consistent, e.g. in event is an issue with below approach)
    --For LOUD games due to LOUD changes making it much harder for units to kite
    if AiBotUtilities.bLoudModActive and (oUnit[AiBotUnitInfo.refbAttackMoveInsteadOfKiting] or (oUnit[AiBotUnitInfo.refiTimeBetweenDFShots] and GetGameTimeSeconds() - (oUnit[AiBotUnitInfo.refiLastWeaponEvent] or 0) >= 4 + oUnit[AiBotUnitInfo.refiTimeBetweenDFShots])) then
        if not(oUnit[AiBotUnitInfo.refbAttackMoveInsteadOfKiting]) then
            oUnit[AiBotUnitInfo.refbAttackMoveInsteadOfKiting] = true
            AiBotUtilities.DelayChangeVariable(oUnit, AiBotUnitInfo.refbAttackMoveInsteadOfKiting, false, 25)
        end
        return true
    end
end

function GroundAttackTargetUnitInsteadOfAttackMove(oUnit, oEnemyToFocusOn)
    if (AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive) and (oUnit[AiBotUnitInfo.refiDFRange] or 0) > 0 and (oUnit[AiBotUnitInfo.refiAntiNavyRange] or 0) == 0 and ((oEnemyToFocusOn:GetFractionComplete() < 1 and EntityCategoryContains(categories.AEON, oEnemyToFocusOn.UnitId)) or EntityCategoryContains(AiBotUnitInfo.refCategoryTorpedoLauncher, oEnemyToFocusOn.UnitId)) and AiBotUtilities.GetDistanceBetweenPositions(oEnemyToFocusOn:GetPosition(), oUnit:GetPosition()) <= oUnit[AiBotUnitInfo.refiCombatRange] then
        return true
    end
end

function DoesWaterZoneHaveUnitsThatCounterTorpDefence(tWZTeamData, iOptionalAlliedCumulativeCombatThreatToReturn)
    if iOptionalAlliedCumulativeCombatThreatToReturn then iOptionalAlliedCumulativeCombatThreatToReturn = iOptionalAlliedCumulativeCombatThreatToReturn + (tWZTeamData[AiBotMap.subrefWZTThreatAllyCombatTotal] or 0) end
    local bEnemyHasLongRangeOrHover = false
    if tWZTeamData[AiBotMap.subrefbWZOnlyHoverEnemies] or ((((tWZTeamData[AiBotMap.subrefWZBestEnemyAntiNavyRange] or 0) >= 50 and (tWZTeamData[AiBotMap.subrefWZBestEnemyAntiNavyRange] > 50 or tWZTeamData[AiBotMap.subrefWZBestEnemySubmersibleRange] >= 50)) or (tWZTeamData[AiBotMap.subrefWZBestEnemyDFRange] or 0) >= 50) and (not(AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive) or math.max((tWZTeamData[AiBotMap.subrefWZBestEnemyAntiNavyRange] or 0), (tWZTeamData[AiBotMap.subrefWZBestEnemyDFRange] or 0)) >= 64)) then
        bEnemyHasLongRangeOrHover = true
    else
        local iEnemyCombatThreat = (tWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0)
        if iEnemyCombatThreat > 15 and AiBotUtilities.IsTableEmpty(tWZTeamData[AiBotMap.subrefTEnemyUnits]) == false then
            local tEnemyHover = EntityCategoryFilterDown(categories.HOVER - categories.ENGINEER, tWZTeamData[AiBotMap.subrefTEnemyUnits])
            if AiBotUtilities.IsTableEmpty(tEnemyHover) == false then
                if not(AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive) then
                    bEnemyHasLongRangeOrHover = true
                elseif tWZTeamData[AiBotMap.subrefWZThreatEnemySubmersible] == 0 then
                    --More detailed check due to how much better torp launchers are
                    bEnemyHasLongRangeOrHover = true
                else
                    local iHoverThreat = AiBotUnitInfo.GetMassCostOfUnits(tEnemyHover, true)
                    if iHoverThreat > 500 or iHoverThreat * 2 > tWZTeamData[AiBotMap.subrefWZThreatEnemySubmersible] then
                        bEnemyHasLongRangeOrHover = true
                    end

                end
            end
        end
    end
    return bEnemyHasLongRangeOrHover, iOptionalAlliedCumulativeCombatThreatToReturn
end

function IsUnitLongRangeThreat(oUnit)
    if (oUnit[AiBotUnitInfo.refiDFRange] or 0) > 50 and ((oUnit[AiBotUnitInfo.refiDFRange] or 0) >= 72 or EntityCategoryContains(AiBotUnitInfo.refCategoryPD , oUnit.UnitId) or (oUnit[AiBotUnitInfo.refiUnitMassCost] or AiBotUnitInfo.GetUnitMassCost(oUnit)) >= 15000 and oUnit[AiBotUnitInfo.refiDFRange] >= 60) and EntityCategoryContains(AiBotUnitInfo.refCategoryLandCombat + AiBotUnitInfo.refCategoryPD + AiBotUnitInfo.refCategoryNavalSurface, oUnit.UnitId) and (oUnit[AiBotUnitInfo.refiUnitMassCost] or AiBotUnitInfo.GetUnitMassCost(oUnit)) >= 600 and not(oUnit.UnitId == 'url0402') then
        return true
        --Indirectfire arti non-building threats
    elseif (oUnit[AiBotUnitInfo.refiIndirectRange] or 0) >= 65 and (oUnit[AiBotUnitInfo.refiIndirectRange] or 0) <= 240 and not(EntityCategoryContains(categories.SILO + AiBotUnitInfo.refCategoryMissileShip + AiBotUnitInfo.refCategoryMML, oUnit.UnitId)) then
        return true
    end
end

