function DoesTableContainUnderConstructionUnits(tUnits)
    for iUnit, oUnit in tUnits do
        if oUnit:GetFractionComplete() < 1 then return true end
    end
    return false
end

function BuildingWasBeingBuiltButCanBeReclaimedNow(oUnit)
    --Crude way of estimating if a building is no longer being constructed, and hence can be
    if oUnit:GetFractionComplete() < 1 and EntityCategoryContains(AiBotUnitInfo.refCategoryStructure * AiBotUnitInfo.refCategoryReclaimable, oUnit.UnitId) then
        local aiBrain = oUnit:GetAIBrain()
        local iTeam = aiBrain.AiBotTeam
        local rRect = AiBotUtilities.GetRectAroundLocation(oUnit:GetPosition(), 25) --A hive can build from 25 away
        local tUnitsInRect = GetUnitsInRect(rRect)
        if AiBotUtilities.IsTableEmpty(tUnitsInRect) == false then
            for iRectUnit, oRectUnit in tUnitsInRect do
                if oRectUnit:GetAIBrain().AiBotTeam == iTeam and oRectUnit:GetFractionComplete() == 1 then
                    if oRectUnit:IsUnitState('Repairing') or oRectUnit:IsUnitState('Building') then
                        return false
                    end
                end
            end
        end
    end
    return true
end

function EnemyZoneHasTooMuchAAForBaseBomber(tTargetLZTeamData, tTargetLZData, oBomber)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'EnemyZoneHasTooMuchAAForBaseBomber'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if bDebugMessages == true then LOG(sFunctionRef..': enemy groundAA threat='..(tTargetLZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] or 'nil')..'; Is table of enemy units empty='..tostring(AiBotUtilities.IsTableEmpty(tTargetLZTeamData[AiBotMap.subrefTEnemyUnits]))) end
    if tTargetLZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] >= 400 then --set quite high as building under construction can have relatively high threat
        if bDebugMessages == true then LOG(sFunctionRef..': Too much groundAA threat') end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        return true
    elseif AiBotUtilities.IsTableEmpty(tTargetLZTeamData[AiBotMap.subrefTEnemyUnits]) == false then
        local tEnemyGroundAA = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryGroundAA, tTargetLZTeamData[AiBotMap.subrefTEnemyUnits])
        if bDebugMessages == true then LOG(sFunctionRef..': Is tEnemyGroundAA empty='..tostring(AiBotUtilities.IsTableEmpty(tEnemyGroundAA))) end
        if AiBotUtilities.IsTableEmpty(tEnemyGroundAA) == false then
            local iFractionCompleteThreshold
            local iDistToZone = AiBotUtilities.GetDistanceBetweenPositions(oBomber:GetPosition(), tTargetLZData[AiBotMap.subrefMidpoint])
            if iDistToZone >= 250 then
                iFractionCompleteThreshold = 0.1
            elseif iDistToZone <= 80 then
                iFractionCompleteThreshold = 0.75
            else
                iFractionCompleteThreshold = 0.3 + (0.75-0.1) * (iDistToZone - 80) / 175
            end
            if bDebugMessages == true then LOG(sFunctionRef..': iDistToZone='..iDistToZone..'; iFractionCompleteThreshold='..iFractionCompleteThreshold) end
            for iAA, oAA in tEnemyGroundAA do
                if AiBotUnitInfo.IsUnitValid(oAA) then
                    if bDebugMessages == true then LOG(sFunctionRef..': oAA='..oAA.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oAA)..'; Fraction complete='..oAA:GetFractionComplete()..'; iFractionCompleteThreshold='..iFractionCompleteThreshold) end
                    --Buildigns can do damage faster and with a better range, so want to abort sooner when they are close to completion
                    if oAA:GetFractionComplete() >= iFractionCompleteThreshold or (oAA:GetFractionComplete() >= math.max(0.1, iFractionCompleteThreshold - 0.15) and EntityCategoryContains(AiBotUnitInfo.refCategoryStructure, oAA.UnitId)) then
                        if bDebugMessages == true then LOG(sFunctionRef..': AA almost complete so too much AA') end
                        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                        return true
                    end
                end
            end
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': No AA so returning false') end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return false
end

function GetBestMobileDFRangeInZone(tLZTeamData)
    local iBestRange = 0
    if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFByRange]) == false then
        for iRange, iThreat in tLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFByRange] do
            if iRange > iBestRange and iThreat > 0 then iBestRange = iRange end
        end
    end
    return iBestRange
end

function GetNearbyEnemyAirToGroundThreat(tStartLZOrWZData, tStartLZOrWZTeamData, iTeam, iSearchRadius, iOptionalAbortThreshold)
    --iOptionalAbortThreshold - if is more than this then will the threat value
    local iNearbyAirToGround = (tStartLZOrWZTeamData[AiBotMap.refiEnemyAirToGroundThreat] or 0)
    if iOptionalAbortThreshold and iNearbyAirToGround > iOptionalAbortThreshold then return iNearbyAirToGround end
    AiBotAir.RecordOtherLandAndWaterZonesByDistance(tStartLZOrWZData)

    if AiBotUtilities.IsTableEmpty(tStartLZOrWZData[AiBotMap.subrefOtherLandAndWaterZonesByDistance]) == false then
        local iOtherPlateauOrZero, iOtherLZOrWZ
        for iEntry, tPathingDetails in tStartLZOrWZData[AiBotMap.subrefOtherLandAndWaterZonesByDistance] do
            if tPathingDetails[AiBotMap.subrefiDistance] > iSearchRadius then
                break
            end
            iOtherPlateauOrZero = tPathingDetails[AiBotMap.subrefiPlateauOrPond]
            iOtherLZOrWZ = tPathingDetails[AiBotMap.subrefiLandOrWaterZoneRef]
            if tPathingDetails[AiBotMap.subrefbIsWaterZone] then iOtherPlateauOrZero = 0 end
            if iOtherLZOrWZ then
                local tOtherLZOrWZData
                local tOtherLZOrWZTeamData
                if iOtherPlateauOrZero == 0 then
                    tOtherLZOrWZData = AiBotMap.tPondDetails[tPathingDetails[AiBotMap.subrefiPlateauOrPond]][AiBotMap.subrefPondWaterZones][iOtherLZOrWZ]
                    tOtherLZOrWZTeamData = tOtherLZOrWZData[AiBotMap.subrefWZTeamData][iTeam]
                else
                    tOtherLZOrWZData = AiBotMap.tAllPlateaus[iOtherPlateauOrZero][AiBotMap.subrefPlateauLandZones][iOtherLZOrWZ]
                    tOtherLZOrWZTeamData = tOtherLZOrWZData[AiBotMap.subrefLZTeamData][iTeam]
                end
                if (tOtherLZOrWZTeamData[AiBotMap.refiEnemyAirToGroundThreat] or 0) > 0 then
                    iNearbyAirToGround = iNearbyAirToGround + tOtherLZOrWZTeamData[AiBotMap.refiEnemyAirToGroundThreat]
                    if iOptionalAbortThreshold and iNearbyAirToGround > iOptionalAbortThreshold then return iNearbyAirToGround end
                end
            end
        end
    end
    return iNearbyAirToGround
end

function GetHighestAirToGroundThreatForIndividualEnemyBrain(iTeam)
    --Gets the highest airtoground threat (ignoring torpedo threat, i.e. just bomber/gunship threat) for an individaul brain - this isnt that optimal an approach so assumed only called in rare cases
    if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoEnemyAirToGround]) then
        return 0
    else
        local toUnitsByBrain = {}
        local iCurIndex
        local iHighestThreat = 0
        for iUnit, oUnit in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoEnemyAirToGround] do
            if not(oUnit.Dead) then
                iCurIndex = oUnit:GetAIBrain():GetArmyIndex()
                if not(toUnitsByBrain[iCurIndex]) then toUnitsByBrain[iCurIndex] = {} end
                table.insert(toUnitsByBrain[iCurIndex], oUnit)
            end
        end
        if iCurIndex then
            for iIndex, tUnits in toUnitsByBrain do
                iHighestThreat = math.max(iHighestThreat, AiBotUnitInfo.GetAirThreatLevel(tUnits, true, false, false, true, true, false))
            end
        end
        return iHighestThreat
    end
end

function BaseIsSafeToRetreatTo(tPosition, iTeam)
    --E.g. send the position of the closest friendly base - used so ACU doesnt retreat to closest friendly base if it has lots of enemy units in it
    local iPlateauOrZero, iLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(tPosition)
    if iLandOrWaterZone then
        if iPlateauOrZero == 0 then
            --Only retreat here if no enemy antinavy threat
            local tTargetWZTeamData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iLandOrWaterZone]][AiBotMap.subrefPondWaterZones][iLandOrWaterZone][AiBotMap.subrefWZTeamData][iTeam]
            if (tTargetWZTeamData[AiBotMap.subrefWZThreatEnemyAntiNavy] or 0) > 0 then
                return false
            end
        else
            local tTargetLZTeamData = AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iLandOrWaterZone][AiBotMap.subrefLZTeamData][iTeam]
            if (tTargetLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0) > 0 and tTargetLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] < (tTargetLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0) * 0.8 then
                return false
            end
        end
    end
    return true
end

function GetBestCombatRangeOfUnitsOnPlateau(tUnits, iPlateau, iTeam)
    local iCombatRange = 0
    for iUnit, oUnit in tUnits do
        if not(oUnit.Dead) and (oUnit[AiBotUnitInfo.refiCombatRange] or 0) > iCombatRange and oUnit[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][1] == iPlateau then
            iCombatRange = oUnit[AiBotUnitInfo.refiCombatRange]
        end
    end
    return iCombatRange
end

function GetFriendlyMAAInThisAndAdjacentLandZones(tLZData, tLZTeamData, iPlateau, iTeam)
    local iMAAThreat =  (tLZTeamData[AiBotMap.subrefLZThreatAllyMAA] or 0)
    if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
        for _, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
            iMAAThreat = iMAAThreat + (AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefLZThreatAllyMAA] or 0)
        end
    end
    return iMAAThreat
end

function IsTeamCoalition(iTeam)
    AiBotUtilities.ErrorHandler('Update ref to refer to AiBotChat not AiBotConditions', true)
    return import('/lua/AiBot/AI/AiBotChat.lua').IsTeamCoalition(iTeam)
end

function IsFurthestACUToFriendlyBase(oACU, tLZOrWZTeamData, iTeam)
    local iACUDistToFriendlyBase = AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase])
    for iFriendlyACU, oFriendlyACU in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftAiBotACUs] do
        if not(oFriendlyACU == oACU) and not(oFriendlyACU.Dead) then
            local tCurLZOrWZData, tCurLZOrWZTeamData = AiBotMap.GetLandOrWaterZoneData(oFriendlyACU:GetPosition(), true, iTeam)
            if AiBotUtilities.GetDistanceBetweenPositions(oFriendlyACU:GetPosition(), tCurLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase]) > iACUDistToFriendlyBase then
                return false
            end
        end
    end
    return true
end

function GetEnemyMobileCombatThreatAndRangeInCurrentAndAdjacentZones(tLZData, tLZTeamData, iPlateau, iTeam, aiBrain)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'GetEnemyMobileCombatThreatAndRangeInCurrentAndAdjacentZones'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local iEnemyThreat = tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal]
    local iEnemyBestRange = math.max(tLZTeamData[AiBotMap.subrefLZThreatEnemyBestMobileDFRange], tLZTeamData[AiBotMap.subrefLZThreatEnemyBestMobileIndirectRange])

    if bDebugMessages == true then LOG(sFunctionRef..': enemy combat threat in this zone='..iEnemyThreat..'; Is table of adjacent zones empty='..tostring(AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]))) end
    if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
        function ConsiderLandZoneThreat(tAltLZTeamData)
            --onlu use df+IF i best enemy structure range is > 0 and < 35
            if (tAltLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0) > 0 then
                iEnemyBestRange = math.max(iEnemyBestRange, tAltLZTeamData[AiBotMap.subrefLZThreatEnemyBestMobileDFRange], tAltLZTeamData[AiBotMap.subrefLZThreatEnemyBestMobileIndirectRange])
                if (tAltLZTeamData[AiBotMap.subrefLZThreatEnemyBestStructureDFRange] or 50) < 35 then
                    iEnemyThreat = iEnemyThreat + (tAltLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFTotal] or 0) + (tAltLZTeamData[AiBotMap.subrefLZThreatEnemyMobileIndirectTotal] or 0)
                else
                    iEnemyThreat = iEnemyThreat + math.max(math.min(500, (tAltLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0)), (tAltLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFTotal] or 0) + (tAltLZTeamData[AiBotMap.subrefLZThreatEnemyMobileIndirectTotal] or 0))
                end
            end
        end
        --Turtle or enemy has land exp on this plateau - look further away than just adjacent zones
        if (aiBrain[AiBotOverseer.refbPrioritiseDefence] or (AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyLandExperimentals]) == false and GetBestCombatRangeOfUnitsOnPlateau(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyLandExperimentals], iPlateau, iTeam) < 50)) and not(tLZTeamData[AiBotMap.refbBaseInSafePosition]) then
            AiBotAir.RecordOtherLandAndWaterZonesByDistance(tLZData) --redundancy, highly doubt it hasnt been called yet
            local iDistThreshold = math.max(150, AiBotUtilities.GetDistanceBetweenPositions(tLZData[AiBotMap.subrefMidpoint], tLZTeamData[AiBotMap.reftClosestEnemyBase]) * 0.4, AiBotMap.iMapSize * 0.2)
            if aiBrain[AiBotOverseer.refbPrioritiseDefence] then iDistThreshold = iDistThreshold + 60
            elseif tLZTeamData[AiBotMap.subrefMexCountByTech] >= tLZData[AiBotMap.subrefLZOrWZMexCount] and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.01 and not(HaveLowPower(iTeam)) then iDistThreshold = iDistThreshold + 40
            end
            local tbConsideredZone = {}
            for iEntry, tSubtable in tLZData[AiBotMap.subrefOtherLandAndWaterZonesByDistance] do
                if tSubtable[AiBotMap.subrefiDistance] > iDistThreshold then break end
                if not(tSubtable[AiBotMap.subrefbIsWaterZone]) then
                    tbConsideredZone[tSubtable[AiBotMap.subrefiLandOrWaterZoneRef]] = true
                    if bDebugMessages == true then LOG(sFunctionRef..': Considering OtherLZ='..tSubtable[AiBotMap.subrefiLandOrWaterZoneRef]..' for turtle brain, iDistThreshold='..iDistThreshold) end
                    ConsiderLandZoneThreat(AiBotMap.tAllPlateaus[tSubtable[AiBotMap.subrefiPlateauOrPond]][AiBotMap.subrefPlateauLandZones][tSubtable[AiBotMap.subrefiLandOrWaterZoneRef]][AiBotMap.subrefLZTeamData][iTeam])
                end
            end
            --Check we included all adj zones
            for iEntry, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
                if not(tbConsideredZone[iAdjLZ]) then ConsiderLandZoneThreat(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam]) end
            end
        else
            for iEntry, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
                local tAltLZTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam]
                if bDebugMessages == true then LOG(sFunctionRef..': Considering iAdjLZ='..iAdjLZ..'; Enemy threat in AdjLZ='..(tAltLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0)..'; Mobile DF='..(tAltLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFTotal] or 0)..'; Mobile indirect='..(tAltLZTeamData[AiBotMap.subrefLZThreatEnemyMobileIndirectTotal] or 0)) end
                ConsiderLandZoneThreat(tAltLZTeamData)
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return iEnemyThreat, iEnemyBestRange
end

function GetEnemyTeamActualMassIncome(iTeam)
    --Used for ACU logic toget mass of enem yteam to iTeam (so can assess if we are far ahead on eco)
    local tiMassByTeam = {}

    for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoEnemyBrains] do
        tiMassByTeam[oBrain.AiBotTeam] = (tiMassByTeam[oBrain.AiBotTeam] or 0) + oBrain:GetEconomyIncome('MASS')
    end
    local iHighestMass = 0
    for iEnemyTeam, iMass in tiMassByTeam do
        if iMass > iHighestMass then iHighestMass = iMass end
    end
    return iHighestMass
end

function WantToPauseSMD(oUnit, bCalledFromOnMissileBuilt)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'WantToPauseSMD'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    --Returns true if SMD has enough missiles loaded and not overflowing in resources
    local iMissiles
    if bCalledFromOnMissileBuilt then iMissiles = 1 --For some reason the count is off by 1, presumably a slight delay between the event being called and the below ammo counts working
    else iMissiles = 0
    end
    if oUnit.GetTacticalSiloAmmoCount then iMissiles = iMissiles + oUnit:GetTacticalSiloAmmoCount() end
    if bDebugMessages == true then LOG(sFunctionRef..': iMissiles based on tactical silo ammo='..iMissiles) end
    if oUnit.GetNukeSiloAmmoCount then iMissiles = iMissiles + oUnit:GetNukeSiloAmmoCount() end
    local iTeam = oUnit:GetAIBrain().AiBotTeam
    local bHaveEnoughSubjectToEco = false
    if bDebugMessages == true then LOG(sFunctionRef..': Near start for SMD oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; iMissiles='..iMissiles..'; bCalledFromOnMissileBuilt='..tostring(bCalledFromOnMissileBuilt or false)) end
    if iMissiles >= 4 or AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyNukeLaunchers]) then
        bHaveEnoughSubjectToEco = true
    elseif iMissiles == 0 or (oUnit[AiBotUnitInfo.refiLastWeaponEvent] and iMissiles < 2) then
        --want more missiles
    elseif AiBotMap.bIsCampaignMap and iMissiles <= 2 and (iMissiles <= 1 or (oUnit:GetAIBrain()[AiBotEconomy.refiBrainBuildRateMultiplier] or 0) < 0.8) and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass]) then
        --Want extra missile for campaign
    else
        bHaveEnoughSubjectToEco = true --will change back to false later
        --If only SMLs are battleships with no nukes then stop at 1 missile for minor zones, or core zones with no enemy battleships within range
        local toBattleshipsToConsider
        for iNuke, oNuke in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyNukeLaunchers] do
            if not(oNuke.Dead) then
                if EntityCategoryContains(AiBotUnitInfo.refCategoryBattleship, oNuke.UnitId) then
                    if oNuke:GetNukeSiloAmmoCount() > 0 then
                        bHaveEnoughSubjectToEco = false
                        toBattleshipsToConsider = nil
                        break
                    else
                        if not(toBattleshipsToConsider) then toBattleshipsToConsider = {} end
                        table.insert(toBattleshipsToConsider, oNuke)
                    end
                else
                    bHaveEnoughSubjectToEco = false
                    toBattleshipsToConsider = nil
                    break
                end
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': Is toBattleshipsToConsider nil='..tostring(toBattleshipsToConsider == nil)) end
        if toBattleshipsToConsider and bHaveEnoughSubjectToEco and oUnit[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam] then
            local tSMDLZTeamData = AiBotMap.tAllPlateaus[oUnit[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][1]][AiBotMap.subrefPlateauLandZones][oUnit[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2]][AiBotMap.subrefLZTeamData][iTeam]
            if bDebugMessages == true then LOG(sFunctionRef..': tSMDLZTeamData[AiBotMap.subrefLZbCoreBase]='..tostring(tSMDLZTeamData[AiBotMap.subrefLZbCoreBase] or false)) end
            if iMissiles >= 3 or (iMissiles >= 1 and not(tSMDLZTeamData[AiBotMap.subrefLZbCoreBase])) then
                bHaveEnoughSubjectToEco = true
            elseif iMissiles >= 1 then
                --Pause unless battleship in range
                bHaveEnoughSubjectToEco = true
                for iNuke, oNuke in toBattleshipsToConsider do
                    if oNuke[AiBotUnitInfo.reftAssignedWaterZoneByTeam][iTeam] then
                        if bDebugMessages == true then LOG(sFunctionRef..': Dist between battleship and nuke='..AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oNuke:GetPosition())..'; Nuke range='..(oNuke[AiBotUnitInfo.refiManualRange] or 410)) end
                        if AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oNuke:GetPosition()) <= 50 + (oNuke[AiBotUnitInfo.refiManualRange] or 410) then
                            bHaveEnoughSubjectToEco = false
                            break
                        end
                    end
                end
            end
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': Near end, time='..GetGameTimeSeconds()..'; bHaveEnoughSubjectToEco='..tostring(bHaveEnoughSubjectToEco)) end
    if bHaveEnoughSubjectToEco then
    if bDebugMessages == true then LOG(sFunctionRef..': Have low power='..tostring(HaveLowPower(iTeam))..'; Gross mass='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass]..'; % stored='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored]) end
    if HaveLowPower(iTeam) or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] <= 400 and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] < 0.8 or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] <= 30 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] <= 25 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] <= 0.99)))) then
    if bDebugMessages == true then LOG(sFunctionRef..': Returning true') end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return true
    end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function WantAnotherT3MexUpgrade(iTeam)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'WantAnotherT3MexUpgrade'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    local bWantT3Mex
    local iEnemyT3Mex = GetHighestOtherTeamT3MexCount(iTeam)
    local iOurT3Mex = (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiMexCountByTech][3] or 0)

    if iOurT3Mex < math.max(iEnemyT3Mex + 2, iOurT3Mex * 1.25) or AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftTeamUpgradingMexes]) then
        bWantT3Mex = true
    else
        local tUpgradingT2Mexes = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryT2Mex, AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftTeamUpgradingMexes])
        if AiBotUtilities.IsTableEmpty(tUpgradingT2Mexes) then
            bWantT3Mex = true
        else
            if bDebugMessages == true then LOG(sFunctionRef..': We already ahve t2 mexes upgrading to t3, size of table='..table.getn(tUpgradingT2Mexes)..'; Our existing mex count by tech='..repru(AiBotTeam.tTeamData[iTeam][AiBotTeam.refiMexCountByTech])) end
            if table.getn(tUpgradingT2Mexes) < math.max(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] + 1, 0.1*AiBotTeam.tTeamData[iTeam][AiBotTeam.refiMexCountByTech][2] + 0.5*AiBotTeam.tTeamData[iTeam][AiBotTeam.refiMexCountByTech][3], math.min(1 + 10 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored], AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored] / 2500)) then
                bWantT3Mex = true
            end
        end
    end
    --If we want torp bombers to deal with navy and it is a naval map and we dont have t3 navy then delay getting t3 mex
    if bWantT3Mex and iEnemyT3Mex <= iOurT3Mex and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyNavalFactoryTech] < 3 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] < 0.7 then
        local bNavalMap = true
        local bAirOnlyMap = true
        for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains] do
            if oBrain[AiBotMap.refbCanPathToEnemyBaseWithLand] then
                bNavalMap = false
                bAirOnlyMap = false
                break
            elseif bAirOnlyMap and oBrain[AiBotMap.refbCanPathToEnemyBaseWithAmphibious] then
                bAirOnlyMap = false
            end
        end
        if bAirOnlyMap then bNavalMap = false end
        if bNavalMap then
            local tiAirSubteamsConsidered = {}
            local bLackTorpsForAllAirSubteams = true
            for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains] do
                if not(tiAirSubteamsConsidered[oBrain.AiBotAirSubteam]) then
                    tiAirSubteamsConsidered[oBrain.AiBotAirSubteam] = true
                    if not(AiBotTeam.tAirSubteamData[oBrain.AiBotAirSubteam][AiBotTeam.refbNoAvailableTorpsForEnemies]) then
                        bLackTorpsForAllAirSubteams = false
                        break
                    end
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': bLackTorpsForAllAirSubteams='..tostring(bLackTorpsForAllAirSubteams)) end
            if  bLackTorpsForAllAirSubteams then
                local iTorpLC = GetTeamLifetimeBuildCount(iTeam, AiBotUnitInfo.refCategoryTorpBomber + AiBotUnitInfo.refCategoryGunship * categories.TECH3 + AiBotUnitInfo.refCategoryBomber * categories.TECH3)
                if bDebugMessages == true then LOG(sFunctionRef..': If our team hasnt built many torp bombers relative to T2+T3 mexes we own then delay getting t3 mexes, iTorpLC incl T3 air combat='..iTorpLC) end
                if iTorpLC < 100 then
                    local iMexCurCount = GetCurrentAiBotUnitsOfCategoryInTeam(AiBotUnitInfo.refCategoryMex - categories.TECH1, iTeam)
                    if bDebugMessages == true then LOG(sFunctionRef..': iMexCurCount='..iMexCurCount) end
                    if iTorpLC < math.max(2, iMexCurCount) * 5 and (iTorpLC < 50 or iTorpLC < iMexCurCount * 2.5) then
                        bWantT3Mex = false
                    end
                end
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': We have as many t3 mex as enemy, we initially wanted more t3 mex, but have finished considering if we want to delay t3 mex due to enemy naval threat, bNavalMap='..tostring(bNavalMap)) end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': Considering if we want to get another t3 mex at this stage, bWantT3Mex='..tostring(bWantT3Mex or false)..'; iEnemyT3Mex='..iEnemyT3Mex..'; iOurT3Mex='..iOurT3Mex..'; Is table of upgrading mexes empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftTeamUpgradingMexes]))) end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return bWantT3Mex
end

function GetShieldSACUsWantedForGETemplate(iTeam)
    local iT3ArtiDPS = 983
    local iNovaxDPS = 243
    local iEnemyDPS
    --Experimental arti count as 2 t3 arti for pruposes of below, so if we have 2+ will check for experimental arti
    if AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyT3ArtiCount] >= 2 and AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyArtiAndExpStructure]) == false then
        --More precise calc needed
        local iMavorDPS = 3334
        local iSalvationDPS = 3000 --in a sandbox salvation did almost as much as a mavor; however it's less likely to be power assisted
        local iScathisDPS = 1600
        local iCurDPS
        iEnemyDPS = (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyNovaxCount] or 0) * iNovaxDPS
        for iArti, oArti in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyArtiAndExpStructure] do
            if not(oArti.Dead) then
                if oArti.UnitId == 'ueb2401' then
                    iCurDPS = iMavorDPS
                elseif oArti.UnitId == 'xab2307' then
                    iCurDPS = iSalvationDPS
                elseif oArti.UnitId == 'url0401' then
                    iCurDPS = iScathisDPS
                elseif EntityCategoryContains(categories.EXPERIMENTAL, oArti.UnitId) then iCurDPS = 2 * iT3ArtiDPS
                else iCurDPS = iT3ArtiDPS
                end
                if oArti:GetFractionComplete() >= 0.6 then
                    iEnemyDPS = iEnemyDPS + iCurDPS
                else iEnemyDPS = iEnemyDPS + iCurDPS * math.min(oArti:GetFractionComplete() * 2, 1)
                end
            end
        end
    else
        iEnemyDPS = (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyT3ArtiCount] or 0) * iT3ArtiDPS + (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyNovaxCount] or 0) * iNovaxDPS
    end
    return math.max(3, iEnemyDPS / 241 + 1.5) --want 1.5 more than we think we need to give a bit of time to get more if enemy builds another t3 arti
end

function GetNetMAAWantedForZone(tLZTeamData, iOptionalGrossFactorAdjust)
    local iMinMAARatioVsCombatWanted --i.e. even if we have lots of fixed AA in the zone we will still assign some MAA in case units are too far from the fixed AA and die for free
    local iAirSubteam = ArmyBrains[tLZTeamData[AiBotMap.reftiClosestFriendlyAiBotBrainIndex]].AiBotAirSubteam
    if not(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbHaveAirControl]) then
        if AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbFarBehindOnAir] then
            iMinMAARatioVsCombatWanted = 0.3
        else
            iMinMAARatioVsCombatWanted = 0.2
        end
    end
    local iBaseMAAWanted = tLZTeamData[AiBotMap.subrefLZMAAThreatWanted]
    if iBaseMAAWanted then
        if iOptionalGrossFactorAdjust then iBaseMAAWanted = iBaseMAAWanted * iOptionalGrossFactorAdjust end
        if iMinMAARatioVsCombatWanted and iBaseMAAWanted > (tLZTeamData[AiBotMap.subrefLZThreatAllyMAA] or 0) and iBaseMAAWanted > 200 then
            return math.max(iBaseMAAWanted - (tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] or 0), math.min(iBaseMAAWanted * iMinMAARatioVsCombatWanted - tLZTeamData[AiBotMap.subrefLZThreatAllyMAA], tLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFTotal] + tLZTeamData[AiBotMap.subrefLZThreatAllyMobileIndirectTotal] - iBaseMAAWanted))
        else return iBaseMAAWanted - tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA]
        end
    end
    return 0
end
function DoesBrainHaveOmniVision(aiBrain)
    if aiBrain.CheatEnabled and ScenarioInfo.Options.OmniCheat == 'on' and not(aiBrain.PCxModifier) then
        return true
    end
end

function DoesACUWantToConsiderGettingNavalFactoryInCurWaterZone(oACU, aiBrain, iTeam, tCurLZOrWZData, tCurLZOrWZTeamData, iCurLZorWZ, bOnlyConsiderAdjacentAndNonZoneSpecificConditions, bOnlyConsiderZoneSpecificConditions, bJustConsideringTorpLauncher)
    --Consider zone specific checks:
    if bOnlyConsiderAdjacentAndNonZoneSpecificConditions or (tCurLZOrWZTeamData[AiBotMap.subrefWZFactoryDestroyedCount] < 2 and (tCurLZOrWZTeamData[AiBotMap.subrefWZbCoreBase] or tCurLZOrWZTeamData[AiBotMap.subrefWZbContainsNavalBuildLocation]) and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiPriorityPondValues][AiBotMap.tiPondByWaterZone[iCurLZorWZ]] >= 6 and ((not(bJustConsideringTorpLauncher) and (tCurLZOrWZTeamData[AiBotMap.subreftiBPWantedByAction][AiBotEngineer.refActionBuildNavalFactory] or 0) > 0 or (tCurLZOrWZTeamData[AiBotMap.subreftiBPWantedByAction][AiBotEngineer.refActionBuildTorpLauncher] or 0) > 0) or (bJustConsideringTorpLauncher and tCurLZOrWZTeamData[AiBotMap.subrefWZTThreatAllyLauncherDefenceTotal] == 0))) then
        --Consider non-zone specific checks:
        if bOnlyConsiderZoneSpecificConditions then return true
        else
            --Non-zone specific includes hecks on the base zone we are calling from, i.e. for if we are considering moving to an adjacent WZ
            if not(aiBrain[AiBotMap.refbCanPathToEnemyBaseWithLand]) and GetGameTimeSeconds() <= 540 and (oACU[AiBotUnitInfo.refiAntiNavyRange] or 0) < 10 and aiBrain[AiBotMap.refbCanPathToEnemyBaseWithAmphibious] then
                if not(bOnlyConsiderAdjacentAndNonZoneSpecificConditions) or (not(tCurLZOrWZTeamData[AiBotMap.subrefLZTeamData][iTeam][AiBotMap.refbBaseInSafePosition]) and (AiBotUtilities.IsTableEmpty(tCurLZOrWZData[AiBotMap.subrefAdjacentWaterZones]) == false or AiBotUtilities.IsTableEmpty(tCurLZOrWZData[AiBotMap.subrefWZAdjacentWaterZones]) == false)) then
                    if aiBrain[AiBotEconomy.refiOurHighestNavalFactoryTech] < 2 and aiBrain[AiBotEconomy.refiOurHighestFactoryTechLevel] < 3 and (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemySubCount] or 0) < 4 and ((AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemySubCount] or 0) <= 2 or AiBotUnitInfo.GetUnitHealthPercent(oACU) >= 0.99) then
                        if bJustConsideringTorpLauncher or (aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryNavalFactory) <= 1 and GetLifetimeBuildCount(aiBrain, AiBotUnitInfo.refCategoryNavalFactory) <= 3) then
                            return true
                        end
                    end
                end
            end
        end
    end
end

function DelayNavyWhereLessImportant(aiBrain, tWZData, tWZTeamData, iTeam, bConsideringUpgrade)
    --E.g. if fighting 1v1 on a 10km or less, and navy is further to enemy base than our core base, likely navy is 'around the outside' of the map and risk investing too much mass for too little payoff
    if AiBotTeam.iPlayersAtGameStart <= 4 and AiBotMap.iMapSize <= 512 and (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiMexCountByTech][3] or 0) == 0 and aiBrain[AiBotEconomy.refiOurHighestFactoryTechLevel] < 3 and not(AiBotMap.bIsCampaignMap) and (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiMexCountByTech][2] < 5 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] or bConsideringUpgrade) and not(aiBrain[AiBotOverseer.refbPrioritiseNavy]) then
        if aiBrain[AiBotEconomy.refiGrossMassBaseIncome] <= 12 and (aiBrain[AiBotEconomy.refiGrossMassBaseIncome] <= 9 or bConsideringUpgrade) and (aiBrain[AiBotEconomy.refiOurHighestFactoryTechLevel] < 2 or bConsideringUpgrade) and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyNavyTech] or 0) == 0 then
            local iDistToEnemyBaseFromNavy = AiBotUtilities.GetDistanceBetweenPositions(tWZData[AiBotMap.subrefMidpoint], tWZTeamData[AiBotMap.reftClosestEnemyBase])
            local iDistToEnemyBaseFromOurBase = AiBotUtilities.GetDistanceBetweenPositions(tWZTeamData[AiBotMap.reftClosestFriendlyBase], tWZTeamData[AiBotMap.reftClosestEnemyBase])
            if iDistToEnemyBaseFromNavy > iDistToEnemyBaseFromOurBase then
                return true
            end
        end
    end
end

function IsPositionInWayOfFactory(tPosition)
    local rRect = AiBotUtilities.GetRectAroundLocation(tPosition, 4)
    local tUnitsInRect = GetUnitsInRect(rRect)
    if AiBotUtilities.IsTableEmpty(tUnitsInRect) == false then
        local tFactories = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryFactory, tUnitsInRect)
        if AiBotUtilities.IsTableEmpty(tFactories) == false then
            return true
        end
    end
    return false
end

function IsPositionInRectangle(tPosition, rRect)
    --Assumes rRect is defined with 'x0', 'x1', 'y0', 'y1' (as using for campaign rectangles)
    if tPosition[1] >= rRect['x0'] and tPosition[1] <= rRect['x1'] and tPosition[3] >= rRect['y0'] and tPosition[3] <= rRect['y1'] then return true end
end

function DoWeWantToBuildObjectiveCategory(tObjectiveLocationSubtable)
    local rRect = AiBotUtilities.GetRectAroundLocation(tObjectiveLocationSubtable[AiBotMap.subreftObjLocation], (tObjectiveLocationSubtable[AiBotMap.subrefiObjLocationSize] or 50))
    local tUnitsInRect = GetUnitsInRect(rRect)
    if AiBotUtilities.IsTableEmpty(tUnitsInRect) == false then
        local tUnitsOfCategory = EntityCategoryFilterDown(tObjectiveLocationSubtable[AiBotMap.subrefiObjCategoryToBuild], tUnitsInRect)
        if AiBotUtilities.IsTableEmpty(tUnitsOfCategory) == false then
            local iUnitsAlreadyHave = 0
            for iUnit, oUnit in tUnitsOfCategory do
                if not(oUnit.Dead) and oUnit:GetFractionComplete() == 1 then
                    iUnitsAlreadyHave = iUnitsAlreadyHave + 1
                    if iUnitsAlreadyHave >= (tObjectiveLocationSubtable[AiBotMap.subrefiNumberWanted] or 1) then
                        return false
                    end
                end
            end
        end
    end
    return true
end

function IsAirMoveLocationSafeToIdle(tMoveLocation, iTeam, bRequireCoreBase)
    local tLZOrWZData, tLZOrWZTeamData = AiBotMap.GetLandOrWaterZoneData(tMoveLocation, true, iTeam)
    if (not(bRequireCoreBase) or tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase]) and AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.reftLZEnemyAirUnits]) and AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subrefTEnemyUnits]) and (tLZOrWZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeDFThreat] or 0) == 0 and (tLZOrWZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeIFThreat] or 0) == 0 and not(tLZOrWZTeamData[AiBotMap.subrefbDangerousEnemiesInAdjacentWZ]) then
        return true
    end
end

function CanTravelToDestinationWithinMapBounds(tStart, tEnd, sPathing, bDrawPathing)
    if (AiBotMap.rMapPlayableArea[3] < AiBotMap.rMapPotentialPlayableArea[3] or AiBotMap.rMapPlayableArea[4] < AiBotMap.rMapPotentialPlayableArea[4]) then
        local tFullPath, iPathSize, iDistance = NavUtils.PathTo((sPathing or 'Land'), tStart, tEnd, nil)
        if AiBotUtilities.IsTableEmpty(tFullPath) == false then
            if bDrawPathing then AiBotUtilities.DrawPath(tFullPath) end
            for iEntry, tPosition in tFullPath do
                if not(IsLocationInPlayableArea(tPosition)) then
                    return
                end
            end
            return true
        else
            return nil
        end
    else
        return true
    end
end


function IsZoneAPacifistZone(iPlateauOrZero, iLandOrWaterZone)
    if AiBotUtilities.IsTableEmpty(AiBotOverseer.tiPacifistZonesByPlateau[iPlateauOrZero]) == false then
        for iEntry, iPacifistZone in AiBotOverseer.tiPacifistZonesByPlateau[iPlateauOrZero] do
            if iPacifistZone == iLandOrWaterZone then return true end
        end
    end
    return false
end

function IsLocationInAPacifistZone(tLocation)
    local iPlateauOrZero, iZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(tLocation)
    return IsZoneAPacifistZone(iPlateauOrZero, iZone)
end

function IsCloseToPacifistUnit(tPosition, iOptionalDistThreshold)
    if AiBotOverseer.toPacifistUnits[1] then
        for iUnit, oUnit in AiBotOverseer.toPacifistUnits do
            if not(oUnit.Dead) and AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tPosition) <= (iOptionalDistThreshold or 120) then
                return true
            end
        end
    end
    return false
end

function  HaveMinimumVisualOrRadarRange(tUnits, iMinIntelWanted)
    --Returns true if finds unit in tUnits with desired intel or radar range
    local tbConsideredUnitByID = {}
    for iUnit, oUnit in tUnits do
        if not(tbConsideredUnitByID[oUnit.UnitId]) then
            tbConsideredUnitByID[oUnit.UnitId] = true
            if (oUnit:GetBlueprint().Intel.RadarRadius or 0) >= iMinIntelWanted or (oUnit:GetBlueprint().Intel.VisionRadius or 0) >= iMinIntelWanted or (oUnit:GetBlueprint().Intel.OmniRadius or 0) >= iMinIntelWanted then
                return true
            end
        end
    end
    return false
end

function HaveEnoughGrossEcoToSupportLandHQUpgrade(aiBrain, iOptionalTechOverride)
    local iGrossMassAdjust = 0
    if AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.subrefbTeamIsStallingMass] then iGrossMassAdjust = 1 end
    if iOptionalTechOverride == 1 or (not(iOptionalTechOverride) and aiBrain[AiBotEconomy.refiOurHighestLandFactoryTech] == 1) then
        local iT1LandCombatBuilt = GetLifetimeBuildCount(aiBrain, AiBotUnitInfo.refCategoryLandCombat + AiBotUnitInfo.refCategoryIndirectT2Plus)
        if iT1LandCombatBuilt >= 50 or aiBrain[AiBotEconomy.refiGrossMassBaseIncome] /  aiBrain[AiBotEconomy.refiBrainBuildRateMultiplier] >= 3.5 + iGrossMassAdjust then
            return true
        end
    else
        --T2 land fac
        local iT2LandCombatBuilt = GetLifetimeBuildCount(aiBrain, AiBotUnitInfo.refCategoryMobileDFLand * categories.TECH2 + AiBotUnitInfo.refCategoryIndirectT2Plus)
        if iT2LandCombatBuilt >= 30 or aiBrain[AiBotEconomy.refiGrossMassBaseIncome] /  aiBrain[AiBotEconomy.refiBrainBuildRateMultiplier] >= 9 + iGrossMassAdjust or (aiBrain[AiBotEconomy.refiGrossMassBaseIncome] /  aiBrain[AiBotEconomy.refiBrainBuildRateMultiplier] >= 5 + iGrossMassAdjust + 4 * iT2LandCombatBuilt / 30) then
            return true
        end
    end
end
